type ClassValue = string | false | null | undefined | 0;
/** Joins class names, skipping empty ones: cx('a', on && 'b'). */
export function cx(...classes: ClassValue[]): string {
  return classes.filter(Boolean).join(' ');
}

/** style object with CSS custom properties (TypeScript doesn't know them). */
export const vars = (style: CSSProperties | undefined, custom: Record<string, string | number | undefined>): CSSProperties => {
  const out: Record<string, unknown> = { ...style };
  for (const [k, v] of Object.entries(custom)) if (v !== undefined) out[k] = v;
  return out as CSSProperties;
};

export const useIsoLayoutEffect = typeof window !== 'undefined' ? useLayoutEffect : useEffect;

/** Value that is controlled (value + onChange) or uncontrolled (defaultValue). */
export function useControllable<T>(value: T | undefined, defaultValue: T, onChange?: (v: T) => void): [T, (v: T) => void] {
  const [inner, setInner] = useState<T>(defaultValue);
  const controlled = value !== undefined;
  const current = controlled ? (value as T) : inner;
  const set = useCallback(
    (v: T) => {
      if (!controlled) setInner(v);
      onChange?.(v);
    },
    [controlled, onChange],
  );
  return [current, set];
}

/** A list row gives its control an id, so the row label points at it without you writing ids. */
export const FieldIdContext = createContext<string | undefined>(undefined);
export function useFieldId(id?: string): string {
  const fromRow = useContext(FieldIdContext);
  const own = useId();
  return id ?? fromRow ?? own;
}

/** iPhone-like ('compact') or iPad-like ('regular'): at least 744 px wide and 600 px tall. Same rule as ios.css. */
export type SizeClass = 'compact' | 'regular';
const REGULAR = '(min-width: 744px) and (min-height: 600px)';
export function useSizeClass(): SizeClass {
  const get = () => (typeof window !== 'undefined' && window.matchMedia(REGULAR).matches ? 'regular' : 'compact');
  const [sizeClass, setSizeClass] = useState<SizeClass>(get);
  useEffect(() => {
    const mq = window.matchMedia(REGULAR);
    const on = () => setSizeClass(mq.matches ? 'regular' : 'compact');
    on();
    mq.addEventListener('change', on);
    return () => mq.removeEventListener('change', on);
  }, []);
  return sizeClass;
}

export interface IconProps extends HTMLAttributes<HTMLSpanElement> {
  name: IconName;
}
/** An icon in the current text colour, 1em in size. Decorative: give the button around it an aria-label. */
export function Icon({ name, className, ...rest }: IconProps) {
  return <span className={cx('ios-icon', `ios-icon-${name}`, className)} aria-hidden="true" {...rest} />;
}

export interface GlassProps extends HTMLAttributes<HTMLDivElement> {
  /** regular (Regular material: controls, capsule) · prominent (solid accent) · inactive · panel (Thick material: menus,
   *  popovers, sheets; radius 34) · clear (Thin material, over media). */
  variant?: 'regular' | 'prominent' | 'inactive' | 'panel' | 'clear';
  children?: ReactNode;
}
/** A classic blur material behind its children (the name says Glass for compatibility; there is no Liquid Glass).
 *  ONLY for controls and panels floating above content. Never a material on a material. */
export function Glass({ variant = 'regular', className, children, ...rest }: GlassProps) {
  const cls =
    variant === 'panel'
      ? 'ios-glass-panel'
      : variant === 'clear'
        ? 'ios-glass-clear'
        : cx('ios-glass', variant === 'prominent' && 'ios-glass--prominent', variant === 'inactive' && 'ios-glass--inactive');
  return (
    <div className={cx(cls, className)} {...rest}>
      {children}
    </div>
  );
}
