export interface ActionSheetAction {
  label: string;
  /** destructive = red label · cancel = the way out (always add one; hidden when the sheet sits next to its button). */
  role?: 'destructive' | 'cancel';
  icon?: IconName;
  onPress?: () => void;
  disabled?: boolean;
}

export interface ActionSheetProps extends Omit<DialogHTMLAttributes<HTMLDialogElement>, 'open' | 'title' | 'onChange'> {
  open: boolean;
  /** Called with false when it closes (an action, Esc, or a tap outside = Cancel). */
  onOpenChange: (open: boolean) => void;
  /** Optional title (Semibold 17) and message (Regular 17). Leave both out for a plain list of actions. */
  title?: string;
  message?: ReactNode;
  actions: ActionSheetAction[];
  /** The button that opened it. iPhone: the sheet grows out of it (kit); iPad: it sits next to it like a popover.
   *  Without it: a card at the bottom of an iPhone, centred on an iPad. */
  anchorRef?: RefObject<HTMLElement | null>;
}

/**
 * An iOS action sheet (kit page "Action Sheets"): a few choices about the action the user just started.
 *
 *     const more = useRef<HTMLSpanElement>(null);
 *     <span ref={more}><Button variant="glass" icon="ellipsis" label="More" onClick={() => setOpen(true)} /></span>
 *     <ActionSheet open={open} onOpenChange={setOpen} anchorRef={more} title="Delete this photo?"
 *                  actions={[{ label: 'Delete Photo', role: 'destructive', onPress: remove }, { label: 'Cancel', role: 'cancel' }]} />
 */
export function ActionSheet({ open, onOpenChange, title, message, actions, anchorRef, className, onCancel, onClose, onClick, ...rest }: ActionSheetProps) {
  const ref = useRef<HTMLDialogElement>(null);
  const titleId = useId();
  const regular = useSizeClass() === 'regular';
  const openRef = useRef(open);
  openRef.current = open;
  const cancel = actions.find(a => a.role === 'cancel');
  const anchored = !!anchorRef;

  // A layout effect, so the dialog is open (and measurable) before the placement below runs.
  useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (open && !el.open) {
      el.showModal();
      el.focus({ preventScroll: true });
    } else if (!open && el.open) el.close();
  }, [open]);

  // Place it next to (iPad) or over (iPhone) its button; same rules as ios.js.
  useLayoutEffect(() => {
    const el = ref.current;
    const source = anchorRef?.current;
    if (!el || !open) return;
    el.style.removeProperty('left');
    el.style.removeProperty('top');
    if (!source) return;
    const s = source.getBoundingClientRect();
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    const w = el.offsetWidth;
    const h = el.offsetHeight;
    const margin = regular ? 8 : 4;
    const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v));
    const cx0 = s.left + s.width / 2;
    let left = cx0 > vw * 0.6 ? (regular ? s.right : s.right + 12) - w : cx0 < vw * 0.4 ? (regular ? s.left : s.left - 12) : cx0 - w / 2;
    left = clamp(left, margin, vw - w - margin);
    let top: number;
    let originY: string;
    if (regular) {
      const below = s.bottom + 8;
      [top, originY] = below + h <= vh - margin || s.top - 8 - h < margin ? [below, '0%'] : [s.top - 8 - h, '100%'];
    } else {
      [top, originY] = s.top + s.height / 2 < vh / 2 ? [s.top, '0%'] : [s.bottom - h, '100%'];
    }
    top = clamp(top, margin, vh - h - margin);
    el.style.left = `${left}px`;
    el.style.top = `${top}px`;
    el.style.transformOrigin = `${clamp(((cx0 - left) / w) * 100, 0, 100)}% ${originY}`;
  }, [open, regular, anchorRef]);

  const press = (a: ActionSheetAction) => {
    if (a.disabled) return;
    a.onPress?.();
    onOpenChange(false);
  };
  const dismiss = () => (cancel ? press(cancel) : onOpenChange(false));

  return (
    <dialog
      ref={ref}
      className={cx('ios-action-sheet', className)}
      data-anchored={anchored ? '' : undefined}
      aria-labelledby={title ? titleId : undefined}
      aria-label={title ? undefined : 'Actions'}
      tabIndex={-1}
      onCancel={e => {
        e.preventDefault();
        dismiss();
        onCancel?.(e);
      }}
      onClose={e => {
        if (openRef.current && !ref.current?.open) onOpenChange(false);
        onClose?.(e);
      }}
      onClick={e => {
        const el = ref.current;
        if (el && e.target === el) {
          const r = el.getBoundingClientRect();
          if (e.clientX < r.left || e.clientX > r.right || e.clientY < r.top || e.clientY > r.bottom) dismiss();
        }
        onClick?.(e);
      }}
      {...rest}
    >
      {(title || message != null) && (
        <div className="ios-action-sheet__text">
          {title && <h2 className="ios-action-sheet__title" id={titleId}>{title}</h2>}
          {message != null && <p className="ios-action-sheet__message">{message}</p>}
        </div>
      )}
      <div className="ios-action-sheet__actions">
        {actions.map((a, i) => (
          <button
            key={i}
            type="button"
            className={cx('ios-action-sheet__action', a.role && `ios-action-sheet__action--${a.role}`)}
            disabled={a.disabled}
            onClick={() => press(a)}
          >
            {a.icon && <Icon name={a.icon} />}
            {a.label}
          </button>
        ))}
      </div>
    </dialog>
  );
}
