export interface ActivityViewPerson {
  /** "First Last": shown on two lines (first name, last name), like iOS. */
  name: string;
  /** A second line instead of the last name, e.g. "2 People" for a group. */
  detail?: string;
  /** Photo URL. For a group pass two photos in images. Without a photo, initials on grey. */
  image?: string;
  images?: [string, string];
  /** The app icon of the conversation (kit: Messages), 20 × 20 at the bottom right. */
  badge?: string;
  onPress?: () => void;
}

export interface ActivityViewApp {
  name: string;
  /** App icon image URL (shown 66 × 66, corner 15). */
  icon: string;
  onPress?: () => void;
}

export interface ActivityViewAction {
  label: string;
  icon: IconName;
  onPress?: () => void;
  destructive?: boolean;
}

export interface ActivityViewProps
  extends Omit<SheetProps, 'title' | 'subtitle' | 'leading' | 'trailing' | 'children' | 'fullScreen' | 'inspector'> {
  /** What is shared (kit header: title Medium 15, subtitle Regular 13, 64 × 64 thumbnail). */
  title: string;
  subtitle?: string;
  thumbnail?: string;
  /** Optional material options button under the title (kit: "Collaborate ›"). */
  options?: { label: string; icon?: IconName; onPress?: () => void };
  /** Optional secondary line with a chevron (kit: "Only invited people can edit. ›"). */
  note?: { label: string; onPress?: () => void };
  /** Row 1: people (suggested conversations). */
  people?: ActivityViewPerson[];
  /** Row 2: apps (AirDrop, Messages, Mail…). */
  apps?: ActivityViewApp[];
  /** Row 3: actions as round buttons (Copy, Add to Favorites…). */
  actions?: ActivityViewAction[];
  /** Then lists of actions, one rounded group per array. */
  actionGroups?: ActivityViewAction[][];
  /** Shows the "Edit Actions" material button at the end. */
  onEditActions?: () => void;
}

function initialsOf(name: string) {
  return name
    .split(/\s+/)
    .map(p => p[0] ?? '')
    .join('')
    .slice(0, 2)
    .toUpperCase();
}

/**
 * The share sheet (kit page "Activity Views"). iPhone: a sheet (medium and large detents). iPad: a popover-style
 * Thick-material panel next to the Share button (pass anchorRef), no dimming.
 *
 *     <ActivityView open={open} onOpenChange={setOpen} anchorRef={shareRef} title="Trip to Rome" subtitle="12 Photos"
 *       apps={[{ name: 'Messages', icon: messagesPng }]} actions={[{ label: 'Copy', icon: 'doc-on-doc', onPress: copy }]}
 *       actionGroups={[[{ label: 'Add to Favorites', icon: 'star' }], [{ label: 'Print', icon: 'printer' }]]} />
 */
export function ActivityView({
  title,
  subtitle,
  thumbnail,
  options,
  note,
  people,
  apps,
  actions,
  actionGroups,
  onEditActions,
  detents = ['medium', 'large'],
  className,
  onOpenChange,
  ...sheet
}: ActivityViewProps) {
  const run = (fn?: () => void) => () => {
    fn?.();
    onOpenChange(false);
  };
  return (
    <Sheet {...sheet} onOpenChange={onOpenChange} detents={detents} className={cx('ios-activity-view', className)} aria-label="Share">
      <header className="ios-activity-view__header">
        {thumbnail ? <img className="ios-activity-view__thumbnail" src={thumbnail} alt="" /> : <span className="ios-activity-view__thumbnail" />}
        <div className="ios-activity-view__info">
          <div className="ios-activity-view__titles">
            <h2 className="ios-activity-view__title">{title}</h2>
            {subtitle && <p className="ios-activity-view__subtitle">{subtitle}</p>}
          </div>
          {options && (
            <Button variant="glass" className="ios-activity-view__options" onClick={options.onPress}>
              {options.icon && <Icon name={options.icon} />}
              {options.label}
              <Icon name="chevron-right" className="ios-activity-view__chevron" />
            </Button>
          )}
          {note && (
            <button type="button" className="ios-activity-view__note" onClick={note.onPress}>
              {note.label}
              <Icon name="chevron-right" />
            </button>
          )}
        </div>
        <Button variant="glass" icon="xmark" label="Close" className="ios-activity-view__close" onClick={() => onOpenChange(false)} />
      </header>

      {people && people.length > 0 && (
        <ul className="ios-activity-view__row" aria-label="People">
          {people.map((p, i) => {
            const [first, ...last] = p.name.split(' ');
            return (
              <li key={i}>
                <button type="button" className="ios-activity-view__target" onClick={run(p.onPress)}>
                  <span className={cx('ios-activity-view__avatar', p.images && 'ios-activity-view__avatar--group')}>
                    {p.images ? (
                      <>
                        <img src={p.images[0]} alt="" />
                        <img src={p.images[1]} alt="" />
                      </>
                    ) : p.image ? (
                      <img src={p.image} alt="" />
                    ) : (
                      <span className="ios-activity-view__initials">{initialsOf(p.name)}</span>
                    )}
                    {p.badge && <img className="ios-activity-view__badge" src={p.badge} alt="" />}
                  </span>
                  <span className="ios-activity-view__label">
                    {p.detail ? p.name : first}
                    <br />
                    {p.detail ? <span className="ios-activity-view__detail">{p.detail}</span> : last.join(' ')}
                  </span>
                </button>
              </li>
            );
          })}
        </ul>
      )}

      {apps && apps.length > 0 && (
        <ul className="ios-activity-view__row ios-activity-view__row--apps" aria-label="Apps">
          {apps.map((a, i) => (
            <li key={i}>
              <button type="button" className="ios-activity-view__target" onClick={run(a.onPress)}>
                <img className="ios-activity-view__app-icon" src={a.icon} alt="" />
                <span className="ios-activity-view__label">{a.name}</span>
              </button>
            </li>
          ))}
        </ul>
      )}

      {actions && actions.length > 0 && (
        <ul className="ios-activity-view__row ios-activity-view__row--actions" aria-label="Actions">
          {actions.map((a, i) => (
            <li key={i}>
              <button type="button" className="ios-activity-view__target" onClick={run(a.onPress)}>
                <span className="ios-activity-view__symbol">
                  <Icon name={a.icon} />
                </span>
                <span className="ios-activity-view__label">{a.label}</span>
              </button>
            </li>
          ))}
        </ul>
      )}

      {actionGroups?.map((group, g) => (
        <ul key={g} className="ios-activity-view__list">
          {group.map((a, i) => (
            <li key={i}>
              <button
                type="button"
                className={cx('ios-activity-view__list-action', a.destructive && 'ios-activity-view__list-action--destructive')}
                onClick={run(a.onPress)}
              >
                <Icon name={a.icon} />
                {a.label}
              </button>
            </li>
          ))}
        </ul>
      ))}

      {onEditActions && (
        <Button variant="glass" size="large" className="ios-activity-view__edit" onClick={onEditActions}>
          Edit Actions
        </Button>
      )}
    </Sheet>
  );
}
