export interface AlertAction {
  label: string;
  /** default = accent-filled (the likely choice; at most one) · cancel · destructive (red label) · none. */
  role?: 'default' | 'cancel' | 'destructive';
  /** Called with the text field values (in order) when pressed. The alert closes itself afterwards. */
  onPress?: (values: string[]) => void;
  disabled?: boolean;
}

export interface AlertTextField {
  placeholder?: string;
  /** Accessible name (defaults to the placeholder). */
  label?: string;
  defaultValue?: string;
  type?: 'text' | 'password' | 'email' | 'number' | 'url';
}

export interface AlertProps extends Omit<DialogHTMLAttributes<HTMLDialogElement>, 'open' | 'title' | 'onChange'> {
  open: boolean;
  /** Called with false when the alert closes (an action was pressed, or Esc pressed the Cancel action). */
  onOpenChange: (open: boolean) => void;
  /** Short title (a question or a statement). */
  title: string;
  /** Optional short, complete sentence. */
  message?: ReactNode;
  /** 1–2 actions sit side by side (Cancel left); 3+ stack (Cancel at the bottom). */
  actions: AlertAction[];
  /** Optional text fields (kit "Text Field"): a 26-radius group of 52-tall fields. */
  textFields?: AlertTextField[];
  /** auto (default) or stacked (force a column for long labels). */
  layout?: 'auto' | 'stacked';
}

/**
 * An iOS alert (kit page "Alerts"): Thick-material panel, 300 wide, left-aligned title and message, capsule actions.
 * Same on iPhone and iPad. Use it rarely: for a confirmation or an important problem.
 *
 *     <Alert open={open} onOpenChange={setOpen} title="Delete “Trip”?" message="This can't be undone."
 *            actions={[{ label: 'Cancel', role: 'cancel' }, { label: 'Delete', role: 'destructive', onPress: remove }]} />
 */
export function Alert({ open, onOpenChange, title, message, actions, textFields, layout = 'auto', className, onCancel, onClose, onKeyDown, ...rest }: AlertProps) {
  const ref = useRef<HTMLDialogElement>(null);
  const fields = useRef<(HTMLInputElement | null)[]>([]);
  const titleId = useId();
  const messageId = useId();
  const openRef = useRef(open);
  openRef.current = open;

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (open && !el.open) {
      el.showModal();
      // The first text field, otherwise the alert itself (Tab moves to the actions, Return = default action).
      const first = fields.current[0];
      if (first) first.focus();
      else el.focus({ preventScroll: true });
    } else if (!open && el.open) el.close();
  }, [open]);

  const press = (action: AlertAction) => {
    if (action.disabled) return;
    action.onPress?.(fields.current.slice(0, textFields?.length ?? 0).map(f => f?.value ?? ''));
    onOpenChange(false);
  };
  const cancel = actions.find(a => a.role === 'cancel');
  // Return in a text field = the default action.
  const submit = () => {
    const def = actions.find(a => a.role === 'default') ?? (actions.length === 1 ? actions[0] : undefined);
    if (def) press(def);
  };

  return (
    <dialog
      ref={ref}
      className={cx('ios-alert', className)}
      role="alertdialog"
      aria-labelledby={titleId}
      aria-describedby={message != null ? messageId : undefined}
      tabIndex={-1}
      onCancel={e => {
        e.preventDefault(); // Esc = Cancel; an alert without a Cancel action must be answered
        if (cancel) press(cancel);
        onCancel?.(e);
      }}
      onKeyDown={e => {
        if (e.key === 'Enter' && !(e.target as Element).closest('button')) {
          e.preventDefault();
          submit();
        }
        onKeyDown?.(e);
      }}
      onClose={e => {
        if (openRef.current && !ref.current?.open) onOpenChange(false);
        onClose?.(e);
      }}
      {...rest}
    >
      <div className="ios-alert__text">
        <h2 className="ios-alert__title" id={titleId}>{title}</h2>
        {message != null && <p className="ios-alert__message" id={messageId}>{message}</p>}
      </div>
      {textFields && textFields.length > 0 && (
        <div className="ios-alert__fields">
          {textFields.map((f, i) => (
            <input
              key={i}
              ref={el => {
                fields.current[i] = el;
              }}
              className="ios-alert__field"
              type={f.type ?? 'text'}
              placeholder={f.placeholder}
              aria-label={f.label ?? f.placeholder}
              defaultValue={f.defaultValue}
            />
          ))}
        </div>
      )}
      <div className={cx('ios-alert__actions', layout === 'stacked' && 'ios-alert__actions--stacked')}>
        {actions.map((a, i) => (
          <button
            key={i}
            type="button"
            className={cx('ios-alert__action', a.role && `ios-alert__action--${a.role}`)}
            disabled={a.disabled}
            onClick={() => press(a)}
          >
            {a.label}
          </button>
        ))}
      </div>
    </dialog>
  );
}
