// app-shell.tsx
// ---------------------------------------------------------------------------------------------------

/* ==========================================================================
   App shell — kit "Safe Areas and Margins" + Examples (Tab Bar, Tab Bars, Sidebar, Window).
   Renders the markup of app-shell.css: .ios-app (fills the viewport, safe areas) and .ios-split-view (the same
   columns inside a window or a card). Tab apps: use TabView (tab-bar.tsx), which builds on App.
   ========================================================================== */

/** What a shell tells the components inside it (Sidebar, TabBar, your own back button). */
export interface AppShellState {
  /** compact = iPhone-like, regular = iPad-like (≥ 744 × 600). */
  sizeClass: SizeClass;
  /** The shell has a sidebar. */
  hasSidebar: boolean;
  /** iPad: the sidebar column is shown. iPhone: the sidebar is the page on screen (instead of the main column). */
  sidebarVisible: boolean;
  setSidebarVisible: (visible: boolean) => void;
  toggleSidebar: () => void;
}

const AppShellContext = createContext<AppShellState | null>(null);

/** The nearest App / SplitView, or null. E.g. an iPhone back button: `const shell = useAppShell(); shell?.setSidebarVisible(true)`. */
export function useAppShell(): AppShellState | null {
  return useContext(AppShellContext);
}

interface ShellColumnProps {
  sidebar?: ReactNode;
  tabBar?: ReactNode;
  sidebarVisible?: boolean;
  defaultSidebarVisible?: boolean;
  onSidebarVisibleChange?: (visible: boolean) => void;
  compactSidebar?: boolean;
  defaultCompactSidebar?: boolean;
  onCompactSidebarChange?: (showsSidebar: boolean) => void;
}

function useShellColumns(p: ShellColumnProps) {
  const sizeClass = useSizeClass();
  const hasSidebar = p.sidebar != null && p.sidebar !== false;
  const [regularVisible, setRegularVisible] = useControllable(p.sidebarVisible, p.defaultSidebarVisible ?? true, p.onSidebarVisibleChange);
  const [compactVisible, setCompactVisible] = useControllable(
    p.compactSidebar,
    p.defaultCompactSidebar ?? (hasSidebar && p.tabBar == null),
    p.onCompactSidebarChange,
  );
  const sidebarVisible = hasSidebar && (sizeClass === 'regular' ? regularVisible : compactVisible);
  const setSidebarVisible = useCallback(
    (v: boolean) => (sizeClass === 'regular' ? setRegularVisible(v) : setCompactVisible(v)),
    [sizeClass, setRegularVisible, setCompactVisible],
  );
  const state = useMemo<AppShellState>(
    () => ({ sizeClass, hasSidebar, sidebarVisible, setSidebarVisible, toggleSidebar: () => setSidebarVisible(!sidebarVisible) }),
    [sizeClass, hasSidebar, sidebarVisible, setSidebarVisible],
  );
  return { state, hidden: hasSidebar && !regularVisible, compact: hasSidebar && compactVisible };
}

export interface AppProps extends HTMLAttributes<HTMLDivElement>, ShellColumnProps {
  /** A <Sidebar>: iPad = left column (320); iPhone = hidden, or the full-screen first page of a sidebar app. */
  sidebar?: ReactNode;
  /** A <TabBar>: iPhone = floating at the bottom; iPad = top centre of the main column. (TabView sets it for you.) */
  tabBar?: ReactNode;
  /** iPad: the sidebar column is shown (controlled). Default: shown. */
  sidebarVisible?: boolean;
  defaultSidebarVisible?: boolean;
  onSidebarVisibleChange?: (visible: boolean) => void;
  /** iPhone: the sidebar is the page on screen (controlled). Default: true for an app with a sidebar and no tab bar. */
  compactSidebar?: boolean;
  defaultCompactSidebar?: boolean;
  onCompactSidebarChange?: (showsSidebar: boolean) => void;
  /** Mockups and screenshots: pretend there is a status bar (62 / 32) and a home indicator (34 / 20). */
  device?: boolean;
  /** Page margins (16 iPhone / 20 iPad) left and right of the content. */
  inset?: boolean;
  /** The grouped background on the page (Settings, forms, cards). Automatic when the page has an inset grouped
   *  <List> or a <Grid> as a direct child; set it for other grouped content. */
  grouped?: boolean;
  /** true (default): children go into one scrolling <main class="ios-app__content">. false: you place the
   *  .ios-app__content element(s) yourself (one per tab, as TabView does). */
  scroll?: boolean;
  children?: ReactNode;
}

/**
 * The root of every iOS/iPadOS web app: fills the viewport, keeps content out of the safe areas, places the sidebar
 * and the tab bar for iPhone and iPad. Needs `<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">`.
 *
 *     <App sidebar={<Sidebar …/>}><NavigationBar title="Inbox" variant="large" />…</App>     // sidebar app
 *     <TabView>…</TabView>                                                                  // tab app (uses App)
 */
export function App({
  sidebar, tabBar, sidebarVisible, defaultSidebarVisible, onSidebarVisibleChange, compactSidebar, defaultCompactSidebar,
  onCompactSidebarChange, device, inset, grouped, scroll = true, className, children, ...rest
}: AppProps) {
  const { state, hidden, compact } = useShellColumns({
    sidebar, tabBar, sidebarVisible, defaultSidebarVisible, onSidebarVisibleChange, compactSidebar, defaultCompactSidebar, onCompactSidebarChange,
  });
  return (
    <AppShellContext.Provider value={state}>
      <div
        className={cx('ios-app', device && 'ios-app--device', hidden && 'ios-app--sidebar-hidden', compact && 'ios-app--compact-sidebar', className)}
        {...rest}
      >
        {sidebar}
        <div className="ios-app__main">
          {scroll ? <main className={cx('ios-app__content', inset && 'ios-app__content--inset', grouped && 'ios-app__content--grouped')}>{children}</main> : children}
          {tabBar}
        </div>
      </div>
    </AppShellContext.Provider>
  );
}

export interface SplitViewProps extends HTMLAttributes<HTMLDivElement>, ShellColumnProps {
  /** A <Sidebar> (iPad left column; iPhone hidden or full screen). */
  sidebar?: ReactNode;
  /** Optional <TabBar> floating over the detail column (kit Examples/Sidebar). */
  tabBar?: ReactNode;
  /** Page margins left and right of the detail content. */
  inset?: boolean;
  /** The grouped background (automatic with an inset grouped <List> or a <Grid> as a direct child). */
  grouped?: boolean;
  /** true (default): children scroll in a .ios-app__content element. false: place it yourself. */
  scroll?: boolean;
  children?: ReactNode;
}

/** Sidebar + detail columns that fill their container (inside an IpadWindow, a card, a demo). For a whole app use App. */
export function SplitView({
  sidebar, tabBar, sidebarVisible, defaultSidebarVisible, onSidebarVisibleChange, compactSidebar, defaultCompactSidebar,
  onCompactSidebarChange, inset, grouped, scroll = true, className, children, ...rest
}: SplitViewProps) {
  const { state, hidden, compact } = useShellColumns({
    sidebar, tabBar, sidebarVisible, defaultSidebarVisible, onSidebarVisibleChange, compactSidebar, defaultCompactSidebar, onCompactSidebarChange,
  });
  return (
    <AppShellContext.Provider value={state}>
      <div className={cx('ios-split-view', hidden && 'ios-split-view--sidebar-hidden', compact && 'ios-split-view--compact-sidebar', className)} {...rest}>
        {sidebar}
        <div className="ios-split-view__detail">
          {scroll ? <div className={cx('ios-app__content', inset && 'ios-app__content--inset', grouped && 'ios-app__content--grouped')}>{children}</div> : children}
          {tabBar}
        </div>
      </div>
    </AppShellContext.Provider>
  );
}

export interface GridProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title'> {
  /** A title above the cards ("Highlights"): the kit's Prominent list header, lined up with the cards' content like
   *  every list header. */
  title?: ReactNode;
  /** The cards: inset grouped <List>s (one section each) or your own card elements. */
  children?: ReactNode;
}

/**
 * A grid of cards (layout C, Summary / dashboard): one column on iPhone (as wide as a List card: at most 648, centred,
 * also when the phone is held sideways); on iPad as many 320 pt columns as fit; 16 between the cards, the page margin
 * at the sides. Put it straight in the page: the page gets the grouped background by itself.
 *
 *     <Grid>{metrics.map(m => <MetricCard key={m.id} metric={m} />)}</Grid>
 *     <Grid title="Highlights">{…}</Grid>
 */
export function Grid({ title, className, children, ...rest }: GridProps) {
  const id = useId();
  const grid = (
    <div className={cx('ios-grid', className)} aria-labelledby={title != null ? id : undefined} {...rest}>
      {children}
    </div>
  );
  if (title == null) return grid;
  return (
    <>
      <header className="ios-list-section__header ios-list-section__header--prominent">
        <h2 className="ios-list-section__title" id={id}>
          {title}
        </h2>
      </header>
      {grid}
    </>
  );
}
// ---------------------------------------------------------------------------------------------------
// button.tsx
// ---------------------------------------------------------------------------------------------------

export type ButtonVariant = 'bordered' | 'prominent' | 'borderless' | 'glass' | 'glass-prominent';
export type ButtonSize = 'small' | 'medium' | 'large';

export interface ButtonProps extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'children'> {
  /**
   * bordered (default: grey fill, tint label) · prominent (tint fill, white label: THE primary action of a screen)
   * · borderless (tint label only) · glass (Regular material) / glass-prominent (solid accent): floating over content,
   * maps, media.
   */
  variant?: ButtonVariant;
  /** small (28 tall) · medium (34, default) · large (50: the main action at the bottom of a screen or sheet). */
  size?: ButtonSize;
  /** Red: deletes or removes something. */
  destructive?: boolean;
  icon?: IconName;
  /** Required for an icon-only button (no children): the accessible name. */
  label?: string;
  children?: ReactNode;
}

/** An iOS button. One prominent button per screen; the material styles (glass / glass-prominent) only for controls
 *  floating above content. */
export function Button({ variant = 'bordered', size = 'medium', destructive, icon, label, className, children, type = 'button', ...rest }: ButtonProps) {
  const iconOnly = icon != null && children == null;
  return (
    <button
      type={type}
      className={cx(
        'ios-button',
        variant !== 'bordered' && `ios-button--${variant}`,
        size !== 'medium' && `ios-button--${size}`,
        destructive && 'ios-button--destructive',
        iconOnly && 'ios-button--icon',
        className,
      )}
      aria-label={label}
      {...rest}
    >
      {icon && <Icon name={icon} />}
      {children}
    </button>
  );
}
