/* ------------------------------------------------------------------ colour helpers */

interface Rgba {
  r: number;
  g: number;
  b: number;
  a: number;
}
const hex2 = (n: number) => Math.round(Math.max(0, Math.min(255, n))).toString(16).padStart(2, '0').toUpperCase();
function parseHex(s: string | null | undefined): Rgba | null {
  const m = /^#?([0-9a-f]{6})([0-9a-f]{2})?$/i.exec((s ?? '').trim());
  if (!m) return null;
  const v = parseInt(m[1], 16);
  return { r: v >> 16, g: (v >> 8) & 255, b: v & 255, a: m[2] ? Math.round((parseInt(m[2], 16) / 255) * 100) / 100 : 1 };
}
const toHex = (c: Rgba) => `#${hex2(c.r)}${hex2(c.g)}${hex2(c.b)}${c.a < 1 ? hex2(c.a * 255) : ''}`;
const opaqueHex = (c: Rgba) => toHex({ ...c, a: 1 });
const cssRgba = (c: Rgba) => `rgb(${Math.round(c.r)} ${Math.round(c.g)} ${Math.round(c.b)} / ${c.a})`;
function fromHsl(h: number, s: number, l: number) {
  const k = (n: number) => (n + h / 30) % 12;
  const a = s * Math.min(l, 1 - l);
  const f = (n: number) => l - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1));
  return { r: Math.round(f(0) * 255), g: Math.round(f(8) * 255), b: Math.round(f(4) * 255) };
}
function toHl({ r, g, b }: Rgba) {
  const [R, G, B] = [r / 255, g / 255, b / 255];
  const max = Math.max(R, G, B);
  const min = Math.min(R, G, B);
  const d = max - min;
  let h = 0;
  if (d) h = max === R ? ((G - B) / d) % 6 : max === G ? (B - R) / d + 2 : (R - G) / d + 4;
  return { h: (h * 60 + 360) % 360, l: (max + min) / 2 };
}

/** The kit's 12 × 10 colour grid ("Color Picker - iPhone" > Color Grid), rows top to bottom. */
export const colorPickerPalette: string[][] = [
  ['#FEFFFE', '#EBEBEB', '#D6D6D6', '#C2C2C2', '#ADADAD', '#999999', '#858585', '#707070', '#5C5C5C', '#474747', '#333333', '#000000'],
  ['#00374A', '#011D57', '#11053B', '#2E063D', '#3C071B', '#5C0701', '#5A1C00', '#583300', '#563D00', '#666100', '#4F5504', '#263E0F'],
  ['#004D65', '#012F7B', '#1A0A52', '#450D59', '#551029', '#831100', '#7B2900', '#7A4A00', '#785800', '#8D8602', '#6F760A', '#38571A'],
  ['#016E8F', '#0042A9', '#2C0977', '#61187C', '#791A3D', '#B51A00', '#AD3E00', '#A96800', '#A67B01', '#C4BC00', '#9BA50E', '#4E7A27'],
  ['#008CB4', '#0056D6', '#371A94', '#7A219E', '#99244F', '#E22400', '#DA5100', '#D38301', '#D19D01', '#F5EC00', '#C3D117', '#669D34'],
  ['#00A1D8', '#0061FD', '#4D22B2', '#982ABC', '#B92D5D', '#FF4015', '#FF6A00', '#FFAB01', '#FCC700', '#FEFB41', '#D9EC37', '#76BB40'],
  ['#01C7FC', '#3A87FD', '#5E30EB', '#BE38F3', '#E63B7A', '#FE6250', '#FE8648', '#FEB43F', '#FECB3E', '#FFF76B', '#E4EF65', '#96D35F'],
  ['#52D6FC', '#74A7FF', '#864FFD', '#D357FE', '#EE719E', '#FF8C82', '#FEA57D', '#FEC777', '#FED977', '#FFF994', '#EAF28F', '#B1DD8B'],
  ['#93E3FC', '#A7C6FF', '#B18CFE', '#E292FE', '#F4A4C0', '#FFB5AF', '#FFC5AB', '#FED9A8', '#FDE4A8', '#FFFBB9', '#F1F7B7', '#CDE8B5'],
  ['#CBF0FF', '#D2E2FE', '#D8C9FE', '#EFCAFE', '#F9D3E0', '#FFDAD8', '#FFE2D6', '#FEECD4', '#FEF1D5', '#FDFBDD', '#F6FADB', '#DEEED4'],
];
/** The kit's saved colours (system Green … Brown, Light values). */
const DEFAULT_SAVED = ['#34C759', '#FFCC00', '#FF8D28', '#FF383C', '#CB30E0', '#0088FF', '#6155F5', '#FF2D55', '#AC7F5E'];

/* ------------------------------------------------------------------ ColorPicker */

export type ColorPickerMode = 'grid' | 'spectrum' | 'sliders';

export interface ColorPickerProps extends Omit<HTMLAttributes<HTMLElement>, 'onChange' | 'defaultValue'> {
  /** "#RRGGBB" or "#RRGGBBAA" (controlled). */
  value?: string;
  defaultValue?: string;
  /** Receives "#RRGGBB" ("#RRGGBBAA" when the opacity is below 100 %). */
  onChange?: (value: string) => void;
  /** Show the opacity slider. Default true. */
  supportsOpacity?: boolean;
  /** Title in the header. Default "Colors". */
  title?: string;
  /** The saved colours under the grid (hex). The "+" button adds the current colour. */
  savedColors?: string[];
  onSavedColorsChange?: (colors: string[]) => void;
  /** Close (×) button. Without it, no close button is shown. */
  onClose?: () => void;
  /** inline: a panel in the page · dialog: a modal <dialog> (sheet on iPhone, popover on iPad); `open` shows it. */
  presentation?: 'inline' | 'dialog';
  open?: boolean;
  /** For presentation="dialog" on iPad sizes: the element the popover appears next to. */
  anchor?: HTMLElement | null;
}

/**
 * The iOS color picker (UIColorPickerViewController, kit "Color Picker - iPhone / iPad"): Grid, Spectrum and Sliders,
 * opacity, the current colour and saved colours. Usually opened by a <ColorWell>.
 */
export function ColorPicker({
  value,
  defaultValue = '#AF52DE',
  onChange,
  supportsOpacity = true,
  title = 'Colors',
  savedColors,
  onSavedColorsChange,
  onClose,
  presentation = 'inline',
  open = false,
  anchor,
  className,
  style,
  ...rest
}: ColorPickerProps) {
  const [hex, setHex] = useControllable(value, defaultValue, onChange);
  const color = parseHex(hex) ?? { r: 0, g: 0, b: 0, a: 1 };
  const [saved, setSaved] = useControllable(savedColors, DEFAULT_SAVED, onSavedColorsChange);
  const [mode, setMode] = useState<ColorPickerMode>('grid');
  const [hexDraft, setHexDraft] = useState<string | null>(null);
  const [percentDraft, setPercentDraft] = useState<string | null>(null);
  const [spot, setSpot] = useState<{ x: number; y: number } | null>(null);
  const dialog = useRef<HTMLDialogElement>(null);
  const opacityId = useId();
  const set = (c: Rgba) => setHex(toHex({ r: Math.round(c.r), g: Math.round(c.g), b: Math.round(c.b), a: Math.round(c.a * 100) / 100 }));
  const hasEyeDropper = typeof window !== 'undefined' && 'EyeDropper' in window;

  // Dialog presentation: showModal / close, placed next to the anchor on iPad sizes.
  useIsoLayoutEffect(() => {
    const d = dialog.current;
    if (!d || presentation !== 'dialog') return;
    if (open && !d.open) d.showModal();
    if (!open && d.open) d.close();
    if (!open) return;
    const regular = window.matchMedia('(min-width: 744px) and (min-height: 600px)').matches;
    if (regular && anchor) {
      const r = anchor.getBoundingClientRect();
      const vw = document.documentElement.clientWidth;
      const vh = document.documentElement.clientHeight;
      let top = r.bottom + 12;
      if (top + d.offsetHeight > vh - 12) top = Math.max(12, r.top - 12 - d.offsetHeight);
      d.style.left = `${Math.round(Math.max(12, Math.min(vw - d.offsetWidth - 12, r.left + r.width / 2 - d.offsetWidth / 2)))}px`;
      d.style.top = `${Math.round(top)}px`;
    } else {
      d.style.left = d.style.top = '';
    }
  }, [open, presentation, anchor]);
  useEffect(() => {
    const d = dialog.current;
    if (!d || !onClose) return;
    const onCloseEvent = () => onClose();
    d.addEventListener('close', onCloseEvent);
    return () => d.removeEventListener('close', onCloseEvent);
  }, [onClose]);

  const pickSpectrum = (e: ReactPointerEvent<HTMLDivElement>) => {
    const r = e.currentTarget.getBoundingClientRect();
    const x = Math.max(0, Math.min(1, (e.clientX - r.left) / r.width));
    const y = Math.max(0, Math.min(1, (e.clientY - r.top) / r.height));
    setSpot({ x, y });
    set({ ...fromHsl(x * 360, 1, 1 - y), a: color.a });
  };
  const hl = toHl(color);
  const marker = spot ?? { x: hl.h / 360, y: 1 - hl.l };
  const gridKey = (e: ReactKeyboardEvent<HTMLButtonElement>, row: number, col: number) => {
    const step = ({ ArrowLeft: [0, -1], ArrowRight: [0, 1], ArrowUp: [-1, 0], ArrowDown: [1, 0] } as Record<string, number[]>)[e.key];
    if (!step) return;
    e.preventDefault();
    const r = Math.max(0, Math.min(9, row + step[0]));
    const c = Math.max(0, Math.min(11, col + step[1]));
    set({ ...parseHex(colorPickerPalette[r][c])!, a: color.a });
    e.currentTarget.parentElement?.querySelector<HTMLButtonElement>(`[data-cell="${r}-${c}"]`)?.focus();
  };
  const current = opaqueHex(color);
  const selectedCell = useMemo(() => {
    for (let r = 0; r < 10; r++) for (let c = 0; c < 12; c++) if (colorPickerPalette[r][c] === current) return `${r}-${c}`;
    return null;
  }, [current]);

  const body = (
    <>
      <div className="ios-color-picker__header">
        <button
          className="ios-color-picker__tool"
          type="button"
          aria-label="Pick a Color from the Screen"
          hidden={!hasEyeDropper}
          onClick={() => {
            const Dropper = (window as unknown as { EyeDropper?: new () => { open: () => Promise<{ sRGBHex: string }> } }).EyeDropper;
            if (Dropper) new Dropper().open().then(r => set({ ...parseHex(r.sRGBHex)!, a: color.a })).catch(() => {});
          }}
        >
          <span className="ios-icon ios-icon-eyedropper" aria-hidden="true" />
        </button>
        <h2 className="ios-color-picker__title">{title}</h2>
        <button className="ios-color-picker__tool" type="button" aria-label="Close" hidden={!onClose} onClick={() => onClose?.()}>
          <Icon name="xmark" />
        </button>
      </div>
      <div className="ios-color-picker__modes" role="tablist" aria-label="Picker Style">
        {(['grid', 'spectrum', 'sliders'] as const).map(m => (
          <button key={m} className="ios-color-picker__mode" type="button" role="tab" aria-selected={mode === m} onClick={() => setMode(m)}>
            {m === 'grid' ? 'Grid' : m === 'spectrum' ? 'Spectrum' : 'Sliders'}
          </button>
        ))}
      </div>
      {mode === 'grid' && (
        <div className="ios-color-picker__grid" role="radiogroup" aria-label="Color Grid">
          {colorPickerPalette.map((row, r) =>
            row.map((c, i) => {
              const key = `${r}-${i}`;
              const checked = selectedCell === key;
              return (
                <button
                  key={key}
                  data-cell={key}
                  className="ios-color-picker__swatch"
                  type="button"
                  role="radio"
                  aria-checked={checked}
                  aria-label={c}
                  tabIndex={checked || (!selectedCell && key === '0-0') ? 0 : -1}
                  onClick={() => set({ ...parseHex(c)!, a: color.a })}
                  onKeyDown={e => gridKey(e, r, i)}
                />
              );
            }),
          )}
        </div>
      )}
      {mode === 'spectrum' && (
        <div
          className="ios-color-picker__spectrum"
          role="img"
          aria-label="Spectrum"
          style={vars(undefined, { '--x': `${marker.x * 100}%`, '--y': `${marker.y * 100}%` })}
          onPointerDown={e => {
            e.currentTarget.setPointerCapture(e.pointerId);
            pickSpectrum(e);
          }}
          onPointerMove={e => e.buttons && pickSpectrum(e)}
        >
          <span className="ios-color-picker__marker" />
        </div>
      )}
      {mode === 'sliders' && (
        <div className="ios-color-picker__sliders">
          {(['r', 'g', 'b'] as const).map(ch => {
            const name = ch === 'r' ? 'Red' : ch === 'g' ? 'Green' : 'Blue';
            return (
              <div key={ch}>
                <span className="ios-color-picker__label" id={`${opacityId}-${ch}`}>
                  {name}
                </span>
                <div className="ios-color-picker__row">
                  <input
                    className="ios-color-picker__slider"
                    type="range"
                    min={0}
                    max={255}
                    value={color[ch]}
                    aria-labelledby={`${opacityId}-${ch}`}
                    style={vars(undefined, { '--ios-color-picker-track': `linear-gradient(to right, ${opaqueHex({ ...color, [ch]: 0 })}, ${opaqueHex({ ...color, [ch]: 255 })})` })}
                    onChange={e => set({ ...color, [ch]: Number(e.target.value) })}
                  />
                  <input
                    className="ios-color-picker__field"
                    type="number"
                    min={0}
                    max={255}
                    value={color[ch]}
                    aria-label={`${name} Value`}
                    onChange={e => set({ ...color, [ch]: Math.max(0, Math.min(255, Number(e.target.value) || 0)) })}
                  />
                </div>
              </div>
            );
          })}
          <div className="ios-color-picker__row">
            <span className="ios-color-picker__label" id={`${opacityId}-hex`} style={{ flex: '1 1 auto' }}>
              Hex Color #
            </span>
            <input
              className="ios-color-picker__field"
              type="text"
              style={{ flexBasis: 100, width: 100 }}
              value={hexDraft ?? current.slice(1)}
              aria-labelledby={`${opacityId}-hex`}
              onChange={e => setHexDraft(e.target.value)}
              onBlur={() => {
                const c = parseHex(hexDraft);
                if (c) set({ ...c, a: color.a });
                setHexDraft(null);
              }}
              onKeyDown={e => e.key === 'Enter' && e.currentTarget.blur()}
            />
          </div>
        </div>
      )}
      {!supportsOpacity && <div className="ios-color-picker__opacity" hidden />}
      {supportsOpacity && (
        <div className="ios-color-picker__opacity">
          <span className="ios-color-picker__label" id={opacityId}>
            Opacity
          </span>
          <div className="ios-color-picker__row">
            <input
              className="ios-color-picker__slider ios-color-picker__slider--opacity"
              type="range"
              min={0}
              max={100}
              value={Math.round(color.a * 100)}
              aria-labelledby={opacityId}
              onChange={e => set({ ...color, a: Number(e.target.value) / 100 })}
            />
            <input
              className="ios-color-picker__field"
              type="text"
              inputMode="numeric"
              aria-label="Opacity Percent"
              value={percentDraft ?? `${Math.round(color.a * 100)}%`}
              onChange={e => setPercentDraft(e.target.value)}
              onBlur={() => {
                const n = parseFloat(percentDraft ?? '');
                if (!Number.isNaN(n)) set({ ...color, a: Math.max(0, Math.min(100, n)) / 100 });
                setPercentDraft(null);
              }}
              onKeyDown={e => e.key === 'Enter' && e.currentTarget.blur()}
            />
          </div>
        </div>
      )}
      <div className="ios-color-picker__footer">
        <span className="ios-color-picker__current" aria-hidden="true" />
        <div className="ios-color-picker__saved" role="radiogroup" aria-label="Saved Colors">
          {saved.map((c, i) => (
            <button
              key={`${c}-${i}`}
              className="ios-color-picker__dot"
              type="button"
              role="radio"
              aria-checked={c.toUpperCase() === current}
              aria-label={c}
              style={vars(undefined, { '--ios-color-picker-dot': c })}
              onClick={() => set({ ...(parseHex(c) ?? color), a: color.a })}
            />
          ))}
          <button className="ios-color-picker__add" type="button" aria-label="Add Color" onClick={() => setSaved([...saved, current])}>
            <Icon name="plus" />
          </button>
        </div>
      </div>
    </>
  );
  const panelStyle = vars(style, { '--ios-color-picker-color': cssRgba(color) });
  if (presentation === 'dialog') {
    return (
      <dialog
        ref={dialog}
        className={cx('ios-color-picker', className)}
        aria-label={title}
        style={panelStyle}
        onClick={e => {
          // Light dismiss: a click on the backdrop.
          const r = e.currentTarget.getBoundingClientRect();
          if (e.target === e.currentTarget && (e.clientX < r.left || e.clientX > r.right || e.clientY < r.top || e.clientY > r.bottom)) e.currentTarget.close();
        }}
        {...(rest as HTMLAttributes<HTMLDialogElement>)}
      >
        {open && body}
      </dialog>
    );
  }
  return (
    <div className={cx('ios-color-picker', className)} role="dialog" aria-label={title} style={panelStyle} {...(rest as HTMLAttributes<HTMLDivElement>)}>
      {body}
    </div>
  );
}

/* ------------------------------------------------------------------ ColorWell */

export interface ColorWellProps extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'value' | 'defaultValue' | 'onChange' | 'color'> {
  /** "#RRGGBB" / "#RRGGBBAA", or null = no colour yet (rainbow disc). Controlled. */
  value?: string | null;
  defaultValue?: string | null;
  /** Receives the picked colour. */
  onChange?: (value: string) => void;
  /** small = 28 pt (default, list rows) · large = 36 pt. */
  size?: 'small' | 'large';
  /** Accessible name. Default "Color". The current colour is added for VoiceOver. */
  label?: string;
  /** Show the opacity slider in the picker. Default true. */
  supportsOpacity?: boolean;
  /** Title of the picker. Default "Colors". */
  title?: string;
}

/**
 * The iOS color well (SwiftUI ColorPicker, kit "Picker Button"): a rainbow ring with the colour inside. Tapping it opens the
 * color picker — a sheet on iPhone, a popover on iPad.
 *
 *     <ColorWell value={color} onChange={setColor} label="Highlight Color" />
 */
export function ColorWell({ value, defaultValue = null, onChange, size = 'small', label = 'Color', supportsOpacity = true, title = 'Colors', className, style, onClick, ...rest }: ColorWellProps) {
  const [hex, setHex] = useControllable<string | null>(value, defaultValue, onChange as ((v: string | null) => void) | undefined);
  const [open, setOpen] = useState(false);
  const button = useRef<HTMLButtonElement>(null);
  const close = useCallback(() => setOpen(false), []);
  const c = parseHex(hex);
  return (
    <>
      <button
        ref={button}
        type="button"
        className={cx('ios-color-well', size === 'large' && 'ios-color-well--large', !c && 'ios-color-well--empty', className)}
        style={c ? vars(style, { '--ios-color-well-color': cssRgba(c) }) : style}
        aria-label={c ? `${label}, ${hex}` : label}
        aria-haspopup="dialog"
        aria-expanded={open}
        onClick={e => {
          onClick?.(e);
          if (!e.defaultPrevented) setOpen(true);
        }}
        {...rest}
      />
      <ColorPicker
        presentation="dialog"
        open={open}
        anchor={button.current}
        onClose={close}
        value={hex ?? '#AF52DE'}
        onChange={v => setHex(v)}
        supportsOpacity={supportsOpacity}
        title={title}
      />
    </>
  );
}
// ---------------------------------------------------------------------------------------------------
// date-picker.tsx
// ---------------------------------------------------------------------------------------------------

/* ------------------------------------------------------------------ helpers */

const pad2 = (n: number) => String(n).padStart(2, '0');
const sameDay = (a?: Date | null, b?: Date | null) =>
  !!a && !!b && a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();
const dayStart = (d: Date) => new Date(d.getFullYear(), d.getMonth(), d.getDate());
const pageLocale = (locale?: string) => locale ?? (typeof navigator !== 'undefined' ? navigator.language : 'en-US');
const reduceMotion = () => typeof window !== 'undefined' && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

/** Places a top-layer popover under its anchor (above when there is no room); centred on iPhone sizes. */
function placePopover(panel: HTMLElement, anchor: HTMLElement | null) {
  if (!anchor) return;
  const r = anchor.getBoundingClientRect();
  const w = panel.offsetWidth;
  const h = panel.offsetHeight;
  const vw = document.documentElement.clientWidth;
  const vh = document.documentElement.clientHeight;
  const compact = !window.matchMedia('(min-width: 744px) and (min-height: 600px)').matches;
  let left = compact ? (vw - w) / 2 : r.left + r.width / 2 - w / 2;
  left = Math.max(16, Math.min(vw - w - 16, left));
  let top = r.bottom + 8;
  if (top + h > vh - 8 && r.top - 8 - h > 8) top = r.top - 8 - h;
  panel.style.left = `${Math.round(left)}px`;
  panel.style.top = `${Math.round(Math.max(8, top))}px`;
}

interface AnchoredPopoverProps {
  anchor: RefObject<HTMLElement | null>;
  open: boolean;
  onClose: () => void;
  label: string;
  children: ReactNode;
}
/** A native [popover] (top layer, light dismiss, Esc) placed next to its anchor. The panel inside draws the material. */
function AnchoredPopover({ anchor, open, onClose, label, children }: AnchoredPopoverProps) {
  const ref = useRef<HTMLDivElement>(null);
  const [shown, setShown] = useState(false);
  useIsoLayoutEffect(() => {
    const el = ref.current;
    if (!el || typeof el.showPopover !== 'function') return;
    const isOpen = el.matches(':popover-open');
    if (open && !isOpen) el.showPopover();
    if (!open && isOpen) el.hidePopover();
    setShown(open);
  }, [open]);
  // Children render once the popover is visible (wheels can scroll to their value), then it is placed at its real size.
  useIsoLayoutEffect(() => {
    if (shown && ref.current) placePopover(ref.current, anchor.current);
  }, [shown, anchor]);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const onToggle = (e: Event) => {
      if ((e as ToggleEvent).newState !== 'closed') return;
      // Give the focus back to the capsule when it was inside the popover (or got lost).
      const active = document.activeElement;
      if (!active || active === document.body || el.contains(active)) anchor.current?.focus();
      onClose();
    };
    el.addEventListener('toggle', onToggle);
    return () => el.removeEventListener('toggle', onToggle);
  }, [onClose, anchor]);
  return (
    <div ref={ref} popover="auto" className="ios-date-picker__popover" role="dialog" aria-label={label}>
      {shown && children}
    </div>
  );
}

/* ------------------------------------------------------------------ WheelPicker */

export interface WheelPickerOption {
  value: string;
  label: string;
  disabled?: boolean;
}
export interface WheelPickerColumn {
  /** Accessible name of the wheel ("Hour", "Size"). */
  label: string;
  options: (WheelPickerOption | string)[];
  /** Text alignment in the wheel. Default centre. */
  align?: 'start' | 'center' | 'end';
  /** Fixed width in pt; columns without a width share the rest. */
  width?: number;
}
export interface WheelPickerProps extends Omit<HTMLAttributes<HTMLDivElement>, 'onChange' | 'defaultValue'> {
  /** One entry per wheel. */
  columns: WheelPickerColumn[];
  /** The selected value of every wheel, in column order. */
  value?: string[];
  defaultValue?: string[];
  /** Receives the selected values of all wheels. */
  onChange?: (value: string[]) => void;
  /** Accessible name of the whole picker. */
  label?: string;
  /** Draw it on a Thick-material panel (radius 13), as in a popover (the prop name says glass for compatibility). */
  glass?: boolean;
}

const normalize = (o: WheelPickerOption | string): WheelPickerOption => (typeof o === 'string' ? { value: o, label: o } : o);

interface WheelColumnProps {
  column: WheelPickerColumn;
  value: string;
  onSelect: (value: string) => void;
}
function WheelColumn({ column, value, onSelect }: WheelColumnProps) {
  const ref = useRef<HTMLDivElement>(null);
  const baseId = useId();
  const options = useMemo(() => column.options.map(normalize), [column.options]);
  const index = Math.max(0, options.findIndex(o => o.value === value));
  const rowHeight = () => (ref.current?.querySelector<HTMLElement>('.ios-wheel-picker__option')?.offsetHeight || 32);
  // Keep the scroll position on the value (only when it differs: the user's own scrolling settles on it).
  useIsoLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const h = rowHeight();
    if (Math.round(el.scrollTop / h) !== index) el.scrollTop = index * h;
  }, [index]);
  const settle = useCallback(() => {
    const el = ref.current;
    if (!el) return;
    let i = Math.max(0, Math.min(options.length - 1, Math.round(el.scrollTop / rowHeight())));
    if (options[i]?.disabled) {
      const next = options.findIndex((o, n) => n > i && !o.disabled);
      i = next >= 0 ? next : index;
      el.scrollTo({ top: i * rowHeight(), behavior: 'smooth' });
    }
    if (options[i] && options[i].value !== value) onSelect(options[i].value);
  }, [options, value, index, onSelect]);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if ('onscrollend' in window) {
      el.addEventListener('scrollend', settle);
      return () => el.removeEventListener('scrollend', settle);
    }
    let timer = 0;
    const onScroll = () => {
      window.clearTimeout(timer);
      timer = window.setTimeout(settle, 120);
    };
    el.addEventListener('scroll', onScroll);
    return () => {
      window.clearTimeout(timer);
      el.removeEventListener('scroll', onScroll);
    };
  }, [settle]);
  const scrollTo = (i: number) =>
    ref.current?.scrollTo({ top: Math.max(0, Math.min(options.length - 1, i)) * rowHeight(), behavior: reduceMotion() ? 'auto' : 'smooth' });
  const onKeyDown = (e: ReactKeyboardEvent<HTMLDivElement>) => {
    const step = ({ ArrowUp: -1, ArrowDown: 1, PageUp: -5, PageDown: 5 } as Record<string, number>)[e.key];
    if (step) scrollTo(index + step);
    else if (e.key === 'Home') scrollTo(0);
    else if (e.key === 'End') scrollTo(options.length - 1);
    else return;
    e.preventDefault();
  };
  return (
    <div
      ref={ref}
      className={cx('ios-wheel-picker__column', column.align && column.align !== 'center' && `ios-wheel-picker__column--${column.align}`)}
      style={column.width ? { flex: `0 0 ${column.width}px` } : undefined}
      role="listbox"
      tabIndex={0}
      aria-label={column.label}
      aria-activedescendant={`${baseId}-${index}`}
      onKeyDown={onKeyDown}
    >
      {options.map((o, i) => (
        <div
          key={o.value}
          id={`${baseId}-${i}`}
          className="ios-wheel-picker__option"
          role="option"
          aria-selected={i === index}
          aria-disabled={o.disabled || undefined}
          onClick={() => !o.disabled && scrollTo(i)}
        >
          {o.label}
        </div>
      ))}
    </div>
  );
}

/**
 * Spinning wheels (iOS Picker(.wheel) / UIPickerView): one wheel per column, 32 pt rows, a 35 pt selection band.
 *
 *     <WheelPicker columns={[{ label: 'Size', options: ['Small', 'Medium', 'Large'] }]} value={[size]} onChange={([s]) => setSize(s)} />
 */
export function WheelPicker({ columns, value, defaultValue, onChange, label, glass, className, ...rest }: WheelPickerProps) {
  const fallback = useMemo(() => columns.map(c => normalize(c.options[0] ?? '').value), [columns]);
  const [values, setValues] = useControllable(value, defaultValue ?? fallback, onChange);
  return (
    <div className={cx('ios-wheel-picker', glass && 'ios-wheel-picker--popover', className)} role="group" aria-label={label} {...rest}>
      {columns.map((c, i) => (
        <WheelColumn
          key={`${c.label}-${i}`}
          column={c}
          value={values[i] ?? fallback[i]}
          onSelect={v => setValues(columns.map((_, n) => (n === i ? v : values[n] ?? fallback[n])))}
        />
      ))}
    </div>
  );
}

/* ------------------------------------------------------------------ time and date wheels */

function timeColumns(locale: string) {
  const f = new Intl.DateTimeFormat(locale, { hour: 'numeric' });
  const h12 = f.resolvedOptions().hour12 !== false;
  const period = (h: number) =>
    new Intl.DateTimeFormat(locale, { hour: 'numeric', hour12: true }).formatToParts(new Date(2023, 0, 1, h)).find(p => p.type === 'dayPeriod')?.value;
  const cols: WheelPickerColumn[] = [
    {
      label: 'Hour',
      align: 'end',
      width: 36,
      options: h12
        ? Array.from({ length: 12 }, (_, i) => ({ value: String(i === 0 ? 12 : i), label: String(i === 0 ? 12 : i) }))
        : Array.from({ length: 24 }, (_, i) => ({ value: String(i), label: pad2(i) })),
    },
    { label: 'Minute', width: 80, options: Array.from({ length: 60 }, (_, i) => ({ value: String(i), label: pad2(i) })) },
  ];
  if (h12) cols.push({ label: 'AM/PM', align: 'start', width: 42, options: [{ value: 'AM', label: period(9) ?? 'AM' }, { value: 'PM', label: period(21) ?? 'PM' }] });
  return { cols, h12 };
}
const timeValues = (d: Date, h12: boolean) =>
  h12 ? [String(d.getHours() % 12 === 0 ? 12 : d.getHours() % 12), String(d.getMinutes()), d.getHours() >= 12 ? 'PM' : 'AM'] : [String(d.getHours()), String(d.getMinutes())];
function withTime(d: Date, v: string[], h12: boolean) {
  const n = new Date(d);
  const hour = h12 ? (Number(v[0]) % 12) + (v[2] === 'PM' ? 12 : 0) : Number(v[0]);
  n.setHours(hour, Number(v[1]), 0, 0);
  return n;
}

interface TimeWheelsProps {
  value: Date;
  onChange: (d: Date) => void;
  locale: string;
  glass?: boolean;
}
function TimeWheels({ value, onChange, locale, glass }: TimeWheelsProps) {
  const { cols, h12 } = useMemo(() => timeColumns(locale), [locale]);
  return <WheelPicker label="Time" glass={glass} columns={cols} value={timeValues(value, h12)} onChange={v => onChange(withTime(value, v, h12))} />;
}

/* ------------------------------------------------------------------ CalendarPicker */

export interface CalendarPickerProps extends Omit<HTMLAttributes<HTMLDivElement>, 'onChange' | 'defaultValue'> {
  /** The selected day (controlled). */
  value?: Date | null;
  defaultValue?: Date | null;
  /** Receives the new day (time of day kept from the old value). */
  onChange?: (date: Date) => void;
  /** First and last day you can pick. */
  min?: Date;
  max?: Date;
  /** Today (the accent-coloured day). Default: the real today. */
  today?: Date;
  /** 0 = Sunday (default), 1 = Monday. */
  firstWeekday?: number;
  /** BCP 47 language for month and weekday names. Default: the browser language. */
  locale?: string;
  /** Adds the "Time" row with a time capsule that opens the time wheels (kit "Show Time"). */
  showTime?: boolean;
  /** Label of the time row. Default "Time". */
  timeLabel?: string;
  /** Draw it on a Thick-material panel (radius 13) — what the compact DatePicker opens. */
  glass?: boolean;
}

/**
 * A month calendar (iOS DatePicker(.graphical), kit "Date and time - Pickers"): month title, arrows, weekday letters,
 * 38 pt day circles. Tap the title for month and year wheels.
 *
 *     <CalendarPicker value={day} onChange={setDay} />
 */
export function CalendarPicker({
  value,
  defaultValue = null,
  onChange,
  min,
  max,
  today,
  firstWeekday = 0,
  locale,
  showTime,
  timeLabel = 'Time',
  glass,
  className,
  ...rest
}: CalendarPickerProps) {
  const lang = pageLocale(locale);
  const [selected, setSelected] = useControllable<Date | null>(value, defaultValue, onChange as ((d: Date | null) => void) | undefined);
  const now = today ?? new Date();
  const [shown, setShown] = useState(() => {
    const d = selected ?? now;
    return new Date(d.getFullYear(), d.getMonth(), 1);
  });
  const [wheels, setWheels] = useState(false);
  const [focusDay, setFocusDay] = useState<Date | null>(null);
  const [timeOpen, setTimeOpen] = useState(false);
  const timePill = useRef<HTMLButtonElement>(null);
  const days = useRef<HTMLDivElement>(null);
  const y = shown.getFullYear();
  const m = shown.getMonth();
  const title = new Intl.DateTimeFormat(lang, { month: 'long', year: 'numeric' }).format(shown);
  const weekday = new Intl.DateTimeFormat(lang, { weekday: 'short' });
  const full = new Intl.DateTimeFormat(lang, { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });
  const count = new Date(y, m + 1, 0).getDate();
  const startCol = ((new Date(y, m, 1).getDay() - firstWeekday + 7) % 7) + 1;
  const outOfRange = (d: Date) => (!!min && d < dayStart(min)) || (!!max && d > max);

  useEffect(() => {
    if (!focusDay) return;
    days.current?.querySelector<HTMLButtonElement>(`[data-day="${focusDay.getDate()}"]`)?.focus();
    setFocusDay(null);
  }, [focusDay, shown]);

  const pick = (d: Date) => {
    const n = new Date(d);
    if (selected) n.setHours(selected.getHours(), selected.getMinutes(), 0, 0);
    setSelected(n);
  };
  const onDayKey = (e: ReactKeyboardEvent<HTMLButtonElement>, d: Date) => {
    const step = ({ ArrowLeft: -1, ArrowRight: 1, ArrowUp: -7, ArrowDown: 7 } as Record<string, number>)[e.key];
    if (!step) return;
    e.preventDefault();
    const next = new Date(d.getFullYear(), d.getMonth(), d.getDate() + step);
    setShown(new Date(next.getFullYear(), next.getMonth(), 1));
    setFocusDay(next);
  };
  const monthNames = useMemo(() => {
    const f = new Intl.DateTimeFormat(lang, { month: 'long' });
    return Array.from({ length: 12 }, (_, i) => ({ value: String(i), label: f.format(new Date(2023, i, 1)) }));
  }, [lang]);
  const years = useMemo(() => Array.from({ length: 201 }, (_, i) => String(new Date().getFullYear() - 100 + i)), []);
  const prevDisabled = !!min && new Date(y, m, 0) < min;
  const nextDisabled = !!max && new Date(y, m + 1, 1) > max;
  const timeText = selected ? new Intl.DateTimeFormat(lang, { hour: 'numeric', minute: '2-digit' }).format(selected) : '';
  const closeTime = useCallback(() => setTimeOpen(false), []);

  return (
    <div className={cx('ios-calendar', glass && 'ios-calendar--popover', className)} {...rest}>
      <div className="ios-calendar__header">
        <button className="ios-calendar__title" type="button" aria-expanded={wheels} onClick={() => setWheels(!wheels)}>
          {title}
          <Icon name="chevron-right-bold" />
        </button>
        <div className="ios-calendar__nav">
          <button className="ios-calendar__arrow" type="button" aria-label="Previous Month" disabled={prevDisabled} onClick={() => setShown(new Date(y, m - 1, 1))}>
            <Icon name="chevron-left" />
          </button>
          <button className="ios-calendar__arrow" type="button" aria-label="Next Month" disabled={nextDisabled} onClick={() => setShown(new Date(y, m + 1, 1))}>
            <Icon name="chevron-right" />
          </button>
        </div>
      </div>
      {wheels ? (
        <div className="ios-calendar__wheels" style={{ minHeight: 242 }}>
          <WheelPicker
            label="Month and year"
            columns={[
              { label: 'Month', options: monthNames },
              { label: 'Year', options: years },
            ]}
            value={[String(m), String(y)]}
            onChange={([mm, yy]) => setShown(new Date(Number(yy), Number(mm), 1))}
          />
        </div>
      ) : (
        <>
          <div className="ios-calendar__weekdays" aria-hidden="true">
            {Array.from({ length: 7 }, (_, i) => (
              <span key={i}>{weekday.format(new Date(2023, 0, 1 + ((firstWeekday + i) % 7))).replace('.', '')}</span>
            ))}
          </div>
          <div className="ios-calendar__days" role="group" aria-label={title} ref={days}>
            {Array.from({ length: count }, (_, i) => {
              const d = new Date(y, m, i + 1);
              const isSelected = sameDay(d, selected);
              return (
                <button
                  key={i}
                  type="button"
                  className="ios-calendar__day"
                  data-day={i + 1}
                  style={i === 0 ? { gridColumnStart: startCol } : undefined}
                  aria-label={full.format(d)}
                  aria-current={sameDay(d, now) ? 'date' : undefined}
                  aria-pressed={isSelected}
                  disabled={outOfRange(d)}
                  tabIndex={isSelected || (!selected && i === 0) ? 0 : -1}
                  onClick={() => pick(d)}
                  onKeyDown={e => onDayKey(e, d)}
                >
                  {i + 1}
                </button>
              );
            })}
          </div>
        </>
      )}
      {showTime && (
        <div className="ios-calendar__time">
          <span>{timeLabel}</span>
          <button
            ref={timePill}
            type="button"
            className="ios-date-picker__pill"
            aria-haspopup="dialog"
            aria-expanded={timeOpen}
            onClick={() => setTimeOpen(o => !o)}
          >
            {timeText || '--:--'}
          </button>
          <AnchoredPopover anchor={timePill} open={timeOpen} onClose={closeTime} label={timeLabel}>
            <TimeWheels value={selected ?? now} onChange={d => setSelected(d)} locale={lang} glass />
          </AnchoredPopover>
        </div>
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ DatePicker */

export type DatePickerComponents = 'date' | 'time' | 'date-and-time';
/** compact (default: capsules that open a popover) · inline (the calendar in place) · wheels (spinning wheels). */
export type DatePickerVariant = 'compact' | 'inline' | 'wheels';

export interface DatePickerProps extends Omit<HTMLAttributes<HTMLDivElement>, 'onChange' | 'defaultValue'> {
  /** The date and time (controlled). */
  value?: Date;
  defaultValue?: Date;
  /** Receives the new Date. */
  onChange?: (date: Date) => void;
  /** What the user picks: date · time · date-and-time (default). */
  components?: DatePickerComponents;
  variant?: DatePickerVariant;
  min?: Date;
  max?: Date;
  /** 0 = Sunday (default), 1 = Monday. */
  firstWeekday?: number;
  /** BCP 47 language for the formats. Default: the browser language. */
  locale?: string;
  disabled?: boolean;
  /** Accessible name ("Start Date"). Put the visible label in the list row. */
  label?: string;
}

/**
 * The iOS date picker (SwiftUI DatePicker). Compact: grey capsules ("Apr 1, 2026" "9:41 AM") that open the calendar or the
 * time wheels in a popover. Inline: the calendar. Wheels: spinning wheels.
 *
 *     <DatePicker value={start} onChange={setStart} label="Starts" />
 *     <DatePicker variant="inline" components="date" value={day} onChange={setDay} />
 */
export function DatePicker({
  value,
  defaultValue,
  onChange,
  components = 'date-and-time',
  variant = 'compact',
  min,
  max,
  firstWeekday = 0,
  locale,
  disabled,
  label,
  className,
  ...rest
}: DatePickerProps) {
  const lang = pageLocale(locale);
  const [initial] = useState(() => defaultValue ?? new Date());
  const [date, setDate] = useControllable(value, initial, onChange);
  const [open, setOpen] = useState<'date' | 'time' | null>(null);
  const datePill = useRef<HTMLButtonElement>(null);
  const timePill = useRef<HTMLButtonElement>(null);
  const close = useCallback(() => setOpen(null), []);
  const hasDate = components !== 'time';
  const hasTime = components !== 'date';
  const clamp = (d: Date) => (min && d < min ? new Date(min) : max && d > max ? new Date(max) : d);
  // Light dismiss closes the popover on pointer down; the click that follows must not reopen it.
  const wasOpen = useRef(false);

  if (variant === 'inline' && hasDate) {
    return (
      <CalendarPicker
        className={className}
        aria-label={label}
        value={date}
        onChange={d => setDate(clamp(d))}
        min={min}
        max={max}
        firstWeekday={firstWeekday}
        locale={lang}
        showTime={hasTime}
        {...rest}
      />
    );
  }
  if (variant === 'wheels' || (variant === 'inline' && !hasDate)) {
    return (
      <div className={className} aria-label={label} {...rest}>
        {hasDate && !hasTime && <DateWheels value={date} onChange={d => setDate(clamp(d))} locale={lang} />}
        {hasTime && !hasDate && <TimeWheels value={date} onChange={d => setDate(clamp(d))} locale={lang} />}
        {hasDate && hasTime && <DateTimeWheels value={date} onChange={d => setDate(clamp(d))} locale={lang} />}
      </div>
    );
  }
  const dateText = new Intl.DateTimeFormat(lang, { month: 'short', day: 'numeric', year: 'numeric' }).format(date);
  const timeText = new Intl.DateTimeFormat(lang, { hour: 'numeric', minute: '2-digit' }).format(date);
  return (
    <div className={cx('ios-date-picker', className)} role="group" aria-label={label} {...rest}>
      {hasDate && (
        <button
          ref={datePill}
          type="button"
          className="ios-date-picker__pill"
          aria-haspopup="dialog"
          aria-expanded={open === 'date'}
          aria-label={label ? `${label}, ${dateText}` : undefined}
          disabled={disabled}
          onPointerDown={() => (wasOpen.current = open === 'date')}
          onClick={() => setOpen(wasOpen.current ? null : 'date')}
        >
          {dateText}
        </button>
      )}
      {hasTime && (
        <button
          ref={timePill}
          type="button"
          className="ios-date-picker__pill"
          aria-haspopup="dialog"
          aria-expanded={open === 'time'}
          aria-label={label ? `${label}, ${timeText}` : undefined}
          disabled={disabled}
          onPointerDown={() => (wasOpen.current = open === 'time')}
          onClick={() => setOpen(wasOpen.current ? null : 'time')}
        >
          {timeText}
        </button>
      )}
      {hasDate && (
        <AnchoredPopover anchor={datePill} open={open === 'date'} onClose={close} label="Date">
          <CalendarPicker glass value={date} onChange={d => setDate(clamp(d))} min={min} max={max} firstWeekday={firstWeekday} locale={lang} />
        </AnchoredPopover>
      )}
      {hasTime && (
        <AnchoredPopover anchor={timePill} open={open === 'time'} onClose={close} label="Time">
          <TimeWheels value={date} onChange={d => setDate(clamp(d))} locale={lang} glass />
        </AnchoredPopover>
      )}
    </div>
  );
}

interface WheelsProps {
  value: Date;
  onChange: (d: Date) => void;
  locale: string;
}
function DateWheels({ value, onChange, locale }: WheelsProps) {
  const months = useMemo(() => {
    const f = new Intl.DateTimeFormat(locale, { month: 'long' });
    return Array.from({ length: 12 }, (_, i) => ({ value: String(i), label: f.format(new Date(2023, i, 1)) }));
  }, [locale]);
  const days = new Date(value.getFullYear(), value.getMonth() + 1, 0).getDate();
  const years = useMemo(() => Array.from({ length: 201 }, (_, i) => String(new Date().getFullYear() - 100 + i)), []);
  return (
    <WheelPicker
      label="Date"
      columns={[
        { label: 'Month', align: 'start', width: 130, options: months },
        { label: 'Day', width: 48, options: Array.from({ length: 31 }, (_, i) => ({ value: String(i + 1), label: String(i + 1), disabled: i + 1 > days })) },
        { label: 'Year', align: 'end', options: years },
      ]}
      value={[String(value.getMonth()), String(value.getDate()), String(value.getFullYear())]}
      onChange={([mm, dd, yy]) => {
        const last = new Date(Number(yy), Number(mm) + 1, 0).getDate();
        onChange(new Date(Number(yy), Number(mm), Math.min(Number(dd), last), value.getHours(), value.getMinutes()));
      }}
    />
  );
}
function DateTimeWheels({ value, onChange, locale }: WheelsProps) {
  const { cols, h12 } = useMemo(() => timeColumns(locale), [locale]);
  const base = useMemo(() => dayStart(new Date()), []);
  const dayOptions = useMemo(() => {
    const f = new Intl.DateTimeFormat(locale, { weekday: 'short', month: 'short', day: 'numeric' });
    return Array.from({ length: 731 }, (_, i) => {
      const d = new Date(base.getFullYear(), base.getMonth(), base.getDate() + i - 365);
      return { value: String(i - 365), label: i === 365 ? 'Today' : f.format(d) };
    });
  }, [locale, base]);
  const offset = Math.round((dayStart(value).getTime() - base.getTime()) / 86400000);
  return (
    <WheelPicker
      label="Date and time"
      columns={[{ label: 'Day', align: 'end', width: 130, options: dayOptions }, ...cols]}
      value={[String(offset), ...timeValues(value, h12)]}
      onChange={([day, ...time]) => {
        const d = new Date(base.getFullYear(), base.getMonth(), base.getDate() + Number(day));
        onChange(withTime(d, time, h12));
      }}
    />
  );
}
