/** Device models of the kit page "Product Bezels" (screen size in pt). */
export type DeviceModel =
  | 'iphone-17' // 402 × 874
  | 'iphone-17-pro' // 402 × 874
  | 'iphone-17-pro-max' // 440 × 956
  | 'iphone-air' // 420 × 912
  | 'iphone-18-pro' // 402 × 874
  | 'iphone-18-pro-max' // 440 × 956
  | 'iphone-duo' // inner display, 669 × 951
  | 'iphone-duo-outer' // outer display, 466 × 678
  | 'ipad-pro-11' // 1210 × 834 (landscape)
  | 'ipad-pro-13' // 1376 × 1032 (landscape)
  | 'ipad-mini'; // 1133 × 744 (landscape)

/** Finishes (kit "Color"). Use the ones the kit has for the model; any works. */
export type DeviceFinish =
  | 'silver' | 'cosmic-orange' | 'deep-blue' | 'black' | 'lavender' | 'mist-blue' | 'sage' | 'white' | 'sky-blue'
  | 'cloud-white' | 'space-black' | 'light-gold' | 'burgundy' | 'glacier' | 'night-sky' | 'star-white' | 'space-gray' | 'starlight';

export interface DeviceFrameProps extends HTMLAttributes<HTMLDivElement> {
  model?: DeviceModel;
  finish?: DeviceFinish;
  /** iPhones are portrait and iPads landscape by default. */
  orientation?: 'portrait' | 'landscape';
  /** Draw the home indicator at the bottom of the screen. Default true. */
  homeIndicator?: boolean;
  /** Force the screen's appearance (its content follows Light or Dark Mode). Default: the page's. */
  theme?: 'light' | 'dark';
  /** Extra class / style for the screen element (e.g. a wallpaper background). */
  screenClassName?: string;
  screenStyle?: CSSProperties;
  /** The screen content, edge to edge. Pad it with var(--ios-device-safe-top/-bottom/-left/-right). */
  children?: ReactNode;
}

const deviceIsIpad = (m: DeviceModel) => m.startsWith('ipad');

/**
 * A device frame for mockups and screenshots (kit page "Product Bezels"), drawn in CSS: metal band, black border,
 * rounded display, Dynamic Island / camera, side buttons. The screen clips your content to the display corners.
 *
 *     <DeviceFrame model="iphone-17-pro" finish="deep-blue"><MyApp /></DeviceFrame>
 *     <DeviceFrame model="ipad-pro-11" orientation="portrait" theme="dark">…</DeviceFrame>
 * Scale it with CSS zoom on a wrapper (style={{ zoom: 0.5 }}), never by changing the screen size.
 */
export function DeviceFrame({
  model = 'iphone-17-pro', finish, orientation, homeIndicator = true, theme, screenClassName, screenStyle, className, children, ...rest
}: DeviceFrameProps) {
  const natural = deviceIsIpad(model) ? 'landscape' : 'portrait';
  const turned = orientation && orientation !== natural;
  return (
    <div
      className={cx(
        'ios-device',
        `ios-device--${model}`,
        finish && `ios-device--${finish}`,
        turned && (natural === 'portrait' ? 'ios-device--landscape' : 'ios-device--portrait'),
        className,
      )}
      {...rest}
    >
      <div className={cx('ios-device__screen', screenClassName)} style={screenStyle} data-theme={theme}>
        {children}
        {homeIndicator && <HomeIndicator />}
      </div>
    </div>
  );
}

export interface HomeIndicatorProps extends HTMLAttributes<HTMLDivElement> {
  /** Wider bar of a landscape iPhone or iPad (226 / 315). Automatic inside a turned DeviceFrame. */
  landscape?: boolean;
}

/** The home indicator bar at the bottom of a full-screen mockup (kit "System / Home Indicator"). Decorative. */
export function HomeIndicator({ landscape, className, ...rest }: HomeIndicatorProps) {
  return <div className={cx('ios-home-indicator', landscape && 'ios-home-indicator--landscape', className)} aria-hidden="true" {...rest} />;
}
