export interface EmptyStateProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title'> {
  /** What is missing, in a few words: "No Favorites", "No Results" (Semibold 22). */
  title: ReactNode;
  /** One sentence: why it is empty or what to do (Medium 22, secondary). */
  description?: ReactNode;
  /** Optional symbol above the text, in the accent colour. */
  icon?: IconName;
  /** large (default: Semibold 41, kit "Large Symbol") · circle (22 in a 50 circle with the accent at 15%, kit "Symbol in Circle"). */
  iconStyle?: 'large' | 'circle';
  /** The title in secondary colour too (kit Examples "No Notes"). */
  secondaryTitle?: boolean;
  /** The one action at the bottom: a large prominent button (solid accent). */
  actionLabel?: string;
  onAction?: () => void;
  /** Your own actions instead of actionLabel (e.g. <Button variant="glass-prominent" size="large">). */
  children?: ReactNode;
}

/**
 * An empty state (kit "Empty States"; SwiftUI ContentUnavailableView). Fills its container: put it where the
 * list or content would be. The accent colour tints the symbol and the button (className="ios-accent-pink"…).
 *
 *     <EmptyState icon="star-fill" title="No Favorites" description="Tap the star on a recipe to add it here."
 *       actionLabel="Browse Recipes" onAction={browse} />
 */
export function EmptyState({
  title,
  description,
  icon,
  iconStyle = 'large',
  secondaryTitle,
  actionLabel,
  onAction,
  className,
  children,
  ...rest
}: EmptyStateProps) {
  return (
    <div className={cx('ios-empty-state', secondaryTitle && 'ios-empty-state--secondary', className)} {...rest}>
      <div className="ios-empty-state__content">
        {icon && (
          <span className={cx('ios-empty-state__symbol', iconStyle === 'circle' && 'ios-empty-state__symbol--circle')} aria-hidden="true">
            <Icon name={icon} />
          </span>
        )}
        <div className="ios-empty-state__text">
          <h2 className="ios-empty-state__title">{title}</h2>
          {description != null && <p className="ios-empty-state__description">{description}</p>}
        </div>
      </div>
      {(actionLabel != null || children != null) && (
        <div className="ios-empty-state__actions">
          {actionLabel != null && (
            <button type="button" className="ios-button ios-button--glass-prominent ios-button--large" onClick={onAction}>
              {actionLabel}
            </button>
          )}
          {children}
        </div>
      )}
    </div>
  );
}
// ---------------------------------------------------------------------------------------------------
// keyboard.tsx
// ---------------------------------------------------------------------------------------------------

/** Which system keyboard to picture (kit "Keyboard" Type). The real one is chosen by the field: see keyboards.md. */
export type KeyboardMockupType =
  | 'lowercase' | 'uppercase' | 'numeric' | 'punctuation' | 'email' | 'url' | 'web' | 'number-pad';

/** The return key: default ↵ (white), or a blue action key. The system picks it from enterkeyhint / submitLabel. */
export type KeyboardReturnKey = 'default' | 'go' | 'search' | 'send' | 'done';

export interface KeyboardMockupProps extends HTMLAttributes<HTMLDivElement> {
  /** lowercase (default) · uppercase (shift on) · numeric (123) · punctuation (#+=) · email · url · web · number-pad. */
  type?: KeyboardMockupType;
  /** iphone (402 wide, default) or ipad (1210 wide; lowercase and uppercase only). */
  device?: 'iphone' | 'ipad';
  /** QuickType suggestions (3). Pass [] to hide the bar. Email shows an AutoFill suggestion instead. */
  suggestions?: string[];
  /** Email keyboard: the AutoFill suggestion (an e-mail address). */
  autofill?: string;
  /** Return key look. Default: 'go' for the web keyboard, 'default' otherwise. */
  returnKey?: KeyboardReturnKey;
}

const KB_RETURN_ICONS: Record<Exclude<KeyboardReturnKey, 'default'>, IconName> = {
  go: 'arrow-right', search: 'magnifyingglass', send: 'arrow-up', done: 'checkmark',
};

// Keyboard symbols added to ios.css by this component (shift, delete-left, return, face-smiling, key, …).
const KbIcon = ({ n }: { n: string }) => <Icon name={n as IconName} />;

type KbKeySpec = { c?: ReactNode; m?: string };
const kbKey = (c: ReactNode, m?: string): KbKeySpec => ({ c, m });
const kbChars = (s: string | string[]) => [...s].map(c => kbKey(c));

function KbKey({ k }: { k: KbKeySpec }) {
  return (
    <span className={cx('ios-keyboard__key', ...(k.m ? k.m.split(' ').map(m => `ios-keyboard__key--${m}`) : []))}>{k.c}</span>
  );
}
function KbRow({ keys, mod, group }: { keys: KbKeySpec[]; mod?: string; group?: { at: number; keys: KbKeySpec[] } }) {
  return (
    <div className={cx('ios-keyboard__row', mod && `ios-keyboard__row--${mod}`)}>
      {keys.slice(0, group ? group.at : keys.length).map((k, i) => <KbKey key={i} k={k} />)}
      {group && (
        <span className="ios-keyboard__group">
          {group.keys.map((k, i) => <KbKey key={i} k={k} />)}
        </span>
      )}
      {group && keys.slice(group.at).map((k, i) => <KbKey key={`e${i}`} k={k} />)}
    </div>
  );
}

/**
 * A STATIC picture of the iOS keyboard (kit page "Keyboards") for mockups and screenshots. Never use it as an input
 * method: real apps get the system keyboard. It is aria-hidden.
 *
 *     <KeyboardMockup type="email" />
 *     <KeyboardMockup type="web" />                     // blue Go key
 *     <KeyboardMockup device="ipad" />
 */
export function KeyboardMockup({
  type = 'lowercase', device = 'iphone', suggestions = ['“Design”', 'Designs', 'Designed'], autofill = 'Smith.Trev@icloud.com',
  returnKey, className, ...rest
}: KeyboardMockupProps) {
  if (device === 'ipad') return <KbIpadKeyboard shift={type === 'uppercase'} suggestions={suggestions} className={className} {...rest} />;

  if (type === 'number-pad') {
    const digits: [string, string][] = [['1', ''], ['2', 'ABC'], ['3', 'DEF'], ['4', 'GHI'], ['5', 'JKL'], ['6', 'MNO'], ['7', 'PQRS'], ['8', 'TUV'], ['9', 'WXYZ']];
    const cell = ([d, l]: [string, string]) => kbKey(<><span className="ios-keyboard__digit">{d}</span><span className="ios-keyboard__letters">{l}</span></>);
    return (
      <div className={cx('ios-keyboard ios-keyboard--numpad', className)} aria-hidden="true" {...rest}>
        <div className="ios-keyboard__keys">
          {[0, 3, 6].map(i => <KbRow key={i} keys={digits.slice(i, i + 3).map(cell)} />)}
          <KbRow keys={[kbKey(null, 'blank'), kbKey(<span className="ios-keyboard__digit">0</span>, 'zero'), kbKey(<KbIcon n="delete-left" />, 'delete')]} />
        </div>
      </div>
    );
  }

  const ret = returnKey ?? (type === 'web' ? 'go' : 'default');
  const returnK = ret === 'default' ? kbKey(<KbIcon n="return" />, 'return') : kbKey(<Icon name={KB_RETURN_ICONS[ret]} />, type === 'web' ? 'go' : 'return prominent');
  const space = kbKey(null, 'space');
  const del = kbKey(<KbIcon n="delete-left" />, 'delete');
  const symbols = type === 'numeric' || type === 'punctuation';
  const upper = type === 'uppercase';
  const L = (s: string) => kbChars(upper ? s.toUpperCase() : s);

  let rows: ReactNode;
  if (symbols) {
    const r1 = type === 'numeric' ? '1234567890' : '[]{}#%^*+=';
    const r2 = type === 'numeric' ? ['-', '/', ':', ';', '(', ')', '$', '&', '@', '”'] : ['_', '\\', '|', '~', '<', '>', '€', '£', '¥', '•'];
    rows = (
      <>
        <KbRow keys={kbChars(r1)} />
        <KbRow keys={kbChars(r2)} />
        <KbRow mod="split" keys={[kbKey(type === 'numeric' ? '#+=' : '123', 'mode label'), del]} group={{ at: 1, keys: kbChars(['.', ',', '?', '!', '’']) }} />
        <KbRow keys={[kbKey('ABC', 'switch label'), space, returnK]} />
      </>
    );
  } else {
    let r4: { keys: KbKeySpec[]; group?: { at: number; keys: KbKeySpec[] } };
    if (type === 'email') r4 = { keys: [kbKey('123', 'switch label'), returnK], group: { at: 1, keys: [space, kbKey('@', 'narrow'), kbKey('.', 'narrow punct')] } };
    else if (type === 'url') r4 = { keys: [kbKey('123', 'switch label'), returnK], group: { at: 1, keys: [kbKey('.', 'punct'), kbKey('/', 'punct'), kbKey('.com', 'label')] } };
    else if (type === 'web') r4 = { keys: [kbKey('123', 'switch label'), space, kbKey('.', 'compact punct'), returnK] };
    else r4 = { keys: [kbKey('123', 'switch label'), space, returnK] };
    rows = (
      <>
        <KbRow keys={L('qwertyuiop')} />
        <KbRow mod="inset" keys={L('asdfghjkl')} />
        <KbRow mod="split" keys={[kbKey(<KbIcon n={upper ? 'shift-fill' : 'shift'} />, 'shift'), del]} group={{ at: 1, keys: L('zxcvbnm') }} />
        <KbRow keys={r4.keys} group={r4.group} />
      </>
    );
  }

  const showBar = type !== 'url' && type !== 'web' && (type === 'email' || suggestions.length > 0);
  return (
    <div className={cx('ios-keyboard', !upper && !symbols && 'ios-keyboard--lowercase', className)} aria-hidden="true" {...rest}>
      {showBar && (
        <div className="ios-keyboard__bar">
          {type === 'email' ? (
            <>
              <span className="ios-keyboard__suggestion ios-keyboard__suggestion--autofill">
                <small>password for this website — Passwords</small>
                {autofill}
              </span>
              <KbIcon n="key" />
            </>
          ) : (
            suggestions.slice(0, 3).map(s => <span key={s} className="ios-keyboard__suggestion">{s}</span>)
          )}
        </div>
      )}
      <div className="ios-keyboard__keys">{rows}</div>
      <div className="ios-keyboard__footer">
        <KbIcon n="face-smiling" />
        <Icon name="mic" />
      </div>
    </div>
  );
}

function KbIpadKeyboard({ shift, suggestions, className, ...rest }: { shift: boolean; suggestions: string[] } & HTMLAttributes<HTMLDivElement>) {
  const C = (c: ReactNode, m: string) => kbKey(c, `command ${m}`);
  const two = (alt: string, ch: string) => kbKey(<><span className="ios-keyboard__alt">{alt}</span>{shift ? ch.toUpperCase() : ch}</>);
  const punct = (top: string, bottom: string) => kbKey(<><span className="ios-keyboard__alt">{top}</span>{bottom}</>, 'punct');
  const shiftIcon = <KbIcon n={shift ? 'shift-fill' : 'shift'} />;
  const rows: KbKeySpec[][] = [
    [C(<KbIcon n="keyboard-tab" />, 'tab'), ...[...'1234567890'].map((a, i) => two(a, 'qwertyuiop'[i])), C(<KbIcon n="delete-left" />, 'delete end')],
    [C(<KbIcon n="capslock" />, 'caps'), ...['@', '#', '$', '&', '*', '(', ')', '’', '”'].map((a, i) => two(a, 'asdfghjkl'[i])), C(<KbIcon n="return" />, 'return end')],
    [C(shiftIcon, 'shift'), ...['%', '-', '+', '=', '/', ';', ':'].map((a, i) => two(a, 'zxcvbnm'[i])), punct('!', ','), punct('?', '.'), C(shiftIcon, 'shift end')],
    [C(<KbIcon n="face-smiling" />, 'emoji'), C('.?123', 'switch'), C(<Icon name="mic" />, 'dictation'), kbKey(null, 'space'), C('.?123', 'switch end'), C(<KbIcon n="keyboard-chevron-down" />, 'hide end')],
  ];
  return (
    <div className={cx('ios-keyboard ios-keyboard--ipad', className)} aria-hidden="true" {...rest}>
      <div className="ios-keyboard__bar">
        <span className="ios-keyboard__tools">
          <KbIcon n="arrow-uturn-left" />
          <KbIcon n="arrow-uturn-right" />
          <KbIcon n="doc-on-clipboard" />
        </span>
        {suggestions.slice(0, 3).map(s => <span key={s} className="ios-keyboard__suggestion">{s}</span>)}
      </div>
      <div className="ios-keyboard__keys">
        {rows.map((r, i) => <KbRow key={i} keys={r} />)}
      </div>
    </div>
  );
}
