/** 'green' → var(--ios-green): system colour names mean the iOS system colours (not the CSS named colours). */
const SYSTEM_COLORS = new Set(['red', 'orange', 'yellow', 'green', 'mint', 'teal', 'cyan', 'blue', 'indigo', 'purple', 'pink', 'brown', 'gray']);
function systemColor(c: string): string {
  return SYSTEM_COLORS.has(c) ? `var(--ios-${c})` : c;
}

// ---------------------------------------------------------------------------------------------------------------
// List (kit page "Lists"): List > ListSection > ListRow. Same markup as lists.css; behaviour (swipe, reorder,
// index scrubbing, collapse) is done here with React state — don't load ios.js / lists.js in a React app.
// ---------------------------------------------------------------------------------------------------------------

/** inset-grouped: white cards on the grouped background (Settings, forms, detail screens). plain: full-width rows. */
export type ListVariant = 'inset-grouped' | 'plain';

interface ListContextValue {
  variant: ListVariant;
  editing: boolean;
  openRow: string | null;
  setOpenRow: (id: string | null) => void;
}
const ListContext = createContext<ListContextValue>({ variant: 'inset-grouped', editing: false, openRow: null, setOpenRow: () => {} });

interface SectionContextValue {
  /** Reorder handler of the section (edit mode). */
  onMove?: (from: number, to: number) => void;
}
const SectionContext = createContext<SectionContextValue>({});
const RowIndexContext = createContext(0);

export interface ListProps extends HTMLAttributes<HTMLDivElement> {
  /** inset-grouped (default; Settings-style cards) · plain (full-width rows, e.g. contacts, mail). */
  variant?: ListVariant;
  /** Edit mode: rows show their delete (red minus) / selection circles, sections with onMove show reorder grabbers. */
  editing?: boolean;
  /** Section index letters at the trailing edge (plain lists). A letter jumps to the ListSection with that indexTitle (or header). */
  index?: string[];
  children?: ReactNode;
}

/**
 * An iOS list. Settings screens and forms are inset grouped lists of ListSections.
 *
 *     <List>
 *       <ListSection header="Network" footer="Applies to all networks.">
 *         <ListRow title="Wi-Fi" detail="Home" icon="wifi" href="#wifi" />
 *         <FormRow label="Airplane Mode"><Toggle checked={on} onChange={setOn} /></FormRow>
 *       </ListSection>
 *     </List>
 */
export function List({ variant = 'inset-grouped', editing = false, index, className, children, ...rest }: ListProps) {
  const [openRow, setOpenRow] = useState<string | null>(null);
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (editing) setOpenRow(null);
  }, [editing]);
  return (
    <ListContext.Provider value={{ variant, editing, openRow, setOpenRow }}>
      <div ref={ref} className={cx('ios-list', `ios-list--${variant}`, editing && 'ios-list--editing', className)} {...rest}>
        {index && index.length > 0 && <ListIndexBar letters={index} listRef={ref} />}
        {children}
      </div>
    </ListContext.Provider>
  );
}

function ListIndexBar({ letters, listRef }: { letters: string[]; listRef: { current: HTMLDivElement | null } }) {
  const last = useRef<string | null>(null);
  const scrubbing = useRef(false);
  const jump = (letter: string | null) => {
    if (!letter || letter === last.current) return;
    last.current = letter;
    const target = listRef.current?.querySelector(`[data-index-title="${CSS.escape(letter)}"]`);
    target?.scrollIntoView({ block: 'start' });
  };
  const letterAt = (e: ReactPointerEvent<HTMLElement>) => {
    const r = e.currentTarget.getBoundingClientRect();
    const el = document.elementFromPoint(r.left + r.width / 2, e.clientY);
    return el instanceof HTMLElement ? el.dataset.letter ?? null : null;
  };
  return (
    <nav
      className="ios-list__index"
      aria-label="Section index"
      onPointerDown={e => {
        scrubbing.current = true;
        last.current = null;
        e.currentTarget.setPointerCapture(e.pointerId);
        jump(letterAt(e));
      }}
      onPointerMove={e => scrubbing.current && jump(letterAt(e))}
      onPointerUp={() => (scrubbing.current = false)}
      onPointerCancel={() => (scrubbing.current = false)}
    >
      {letters.map(l => (
        <button
          key={l}
          type="button"
          data-letter={l}
          onClick={e => {
            if (e.detail === 0) {
              last.current = null;
              jump(l); // keyboard
            }
          }}
        >
          {l}
        </button>
      ))}
    </nav>
  );
}

export type ListHeaderStyle = 'nested' | 'prominent' | 'extra-prominent';

export interface ListSectionProps extends Omit<HTMLAttributes<HTMLElement>, 'title'> {
  /** Section header text (kit "Header"). */
  header?: ReactNode;
  /** nested (default: Semibold 17, secondary) · prominent (Semibold 20) · extra-prominent (Bold 22). */
  headerStyle?: ListHeaderStyle;
  /** Small text above / below the header title (Regular 15, secondary). */
  supertitle?: ReactNode;
  subtitle?: ReactNode;
  /** Trailing accessory of the header, e.g. <ListHeaderAction onClick={…}>See All</ListHeaderAction>. */
  headerTrailing?: ReactNode;
  /** Footer text under the rows (Regular 13, secondary): explains the settings above. */
  footer?: ReactNode;
  /** Collapsible section: a "Show Less / Show More" toggle with a chevron in the header. */
  collapsible?: boolean;
  expanded?: boolean;
  defaultExpanded?: boolean;
  onExpandedChange?: (expanded: boolean) => void;
  /** Text of the collapse toggle (default: Show Less / Show More). */
  toggleLabel?: (expanded: boolean) => ReactNode;
  /** Letter of the section index (List index). Defaults to the header when it is a string. */
  indexTitle?: string;
  /** Reorder rows in edit mode: grabbers appear on the rows; you move the item in your state. Give rows stable keys. */
  onMove?: (from: number, to: number) => void;
  children?: ReactNode;
}

/** One section of a List: optional header, the rows (ListRow), optional footer. */
export function ListSection({
  header,
  headerStyle = 'nested',
  supertitle,
  subtitle,
  headerTrailing,
  footer,
  collapsible,
  expanded,
  defaultExpanded = true,
  onExpandedChange,
  toggleLabel = open => (open ? 'Show Less' : 'Show More'),
  indexTitle,
  onMove,
  className,
  children,
  ...rest
}: ListSectionProps) {
  const [innerOpen, setInnerOpen] = useState(defaultExpanded);
  const open = expanded ?? innerOpen;
  const setOpen = (v: boolean) => {
    if (expanded === undefined) setInnerOpen(v);
    onExpandedChange?.(v);
  };
  const rowsId = useId();
  const title = <h2 className="ios-list-section__title">{header}</h2>;
  const hasHeader = header != null || headerTrailing != null || collapsible;
  return (
    <SectionContext.Provider value={{ onMove }}>
      <section
        className={cx('ios-list-section', className)}
        data-index-title={indexTitle ?? (typeof header === 'string' ? header : undefined)}
        {...rest}
      >
        {hasHeader && (
          <header className={cx('ios-list-section__header', headerStyle !== 'nested' && `ios-list-section__header--${headerStyle}`)}>
            {supertitle || subtitle ? (
              <div className="ios-list-section__heading">
                {supertitle && <p className="ios-list-section__supertitle">{supertitle}</p>}
                {title}
                {subtitle && <p className="ios-list-section__subtitle">{subtitle}</p>}
              </div>
            ) : (
              title
            )}
            {collapsible && (
              <button
                type="button"
                className="ios-list-section__toggle"
                aria-expanded={open}
                aria-controls={rowsId}
                onClick={() => setOpen(!open)}
              >
                {toggleLabel(open)}
              </button>
            )}
            {headerTrailing}
          </header>
        )}
        <ul className="ios-list-section__rows" id={rowsId}>
          {Children.map(children, (child, i) => (
            <RowIndexContext.Provider value={i}>{child}</RowIndexContext.Provider>
          ))}
        </ul>
        {footer != null && <p className="ios-list-section__footer">{footer}</p>}
      </section>
    </SectionContext.Provider>
  );
}

export interface ListHeaderActionProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  /** An icon makes it the 44 pt round icon button (kit "Button"); give `label` then. */
  icon?: IconName;
  label?: string;
}
/** A header accessory: an accent text button ("See All", "Edit") or a round icon button. */
export function ListHeaderAction({ icon, label, className, children, type = 'button', ...rest }: ListHeaderActionProps) {
  return (
    <button
      type={type}
      className={cx(icon && children == null ? 'ios-list-section__button' : 'ios-list-section__action', className)}
      aria-label={label}
      {...rest}
    >
      {icon && <Icon name={icon} />}
      {children}
    </button>
  );
}

// ---- Swipe actions ------------------------------------------------------------------------------------------

export type ListRowActionColor = 'gray' | 'red' | 'orange' | 'blue' | 'green' | 'accent';

export interface ListRowActionProps extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'children' | 'color'> {
  /** The action's name ("Delete", "Flag"). Shown under/next to the icon unless iconOnly. */
  label: string;
  icon?: IconName;
  /** gray (default) · red · orange · blue · green · accent. destructive = red. */
  color?: ListRowActionColor;
  destructive?: boolean;
  /** Show only the symbol (kit "Symbol only"); label stays the accessible name. */
  iconOnly?: boolean;
}

const SwipeContext = createContext<{ close: () => void }>({ close: () => {} });

/** One swipe action of a ListRow (kit "_Swipe Actions"): a coloured capsule. Pass them in leadingActions / trailingActions. */
export function ListRowAction({ label, icon, color = 'gray', destructive, iconOnly, className, onClick, type = 'button', ...rest }: ListRowActionProps) {
  const { close } = useContext(SwipeContext);
  const tone = destructive ? 'red' : color;
  const mod = tone === 'gray' ? null : tone === 'red' ? 'destructive' : tone;
  return (
    <button
      type={type}
      className={cx('ios-swipe-actions__action', mod && `ios-swipe-actions__action--${mod}`, className)}
      aria-label={iconOnly ? label : undefined}
      onClick={e => {
        onClick?.(e);
        close();
      }}
      {...rest}
    >
      {icon && <Icon name={icon} />}
      {(!iconOnly || !icon) && <span className="ios-swipe-actions__label">{label}</span>}
    </button>
  );
}

// ---- Rows -----------------------------------------------------------------------------------------------------

export type ListRowImageStyle = 'fill' | 'circle' | 'rounded' | 'symbol';

export interface ListRowProps extends Omit<HTMLAttributes<HTMLLIElement>, 'title' | 'onClick'> {
  /** Main text (Regular 17). */
  title?: ReactNode;
  /** Second line (Regular 15, secondary): makes the row 68 tall. */
  subtitle?: ReactNode;
  /** Value on the trailing side (Regular 17, secondary): the current setting ("Home", "On"). */
  detail?: ReactNode;
  /** Settings-style icon tile: a white symbol on a coloured 30 pt rounded square (iconColor, default accent). */
  icon?: IconName;
  /** A system colour name ('green', 'orange', 'blue' … = the iOS system colour) or any CSS colour (`var(--ios-orange)`). */
  iconColor?: string;
  /** Leading image: an image URL or your own element (<img>, avatar). imageStyle: fill (square, full height) · circle · rounded. */
  image?: string | ReactElement;
  imageStyle?: ListRowImageStyle;
  /** Accessible text of the image (empty = decorative). */
  imageAlt?: string;
  /** Leading accent symbol without a tile (kit Image "Symbol"). */
  leadingSymbol?: IconName;
  /** Trailing accent symbol (kit "Symbol"), e.g. "star". */
  symbol?: IconName;
  /** Drill-in chevron (navigates to another screen). On by default for href / onClick rows; false hides it. */
  chevron?: boolean;
  /** Navigation: a link row. */
  href?: string;
  /** Tap action of the whole row (navigation in your router, open a sheet, toggle a choice). */
  onClick?: (event: ReactMouseEvent<HTMLElement>) => void;
  /** Info button (info.circle, accent) next to the chevron. */
  onInfo?: () => void;
  infoLabel?: string;
  /** Checkmark row: true shows the checkmark (single choice: role radio; multiple: role checkbox). */
  checked?: boolean;
  multiple?: boolean;
  /** Expandable row: accent chevron that turns down when expanded (put the expanded content in the next row). */
  expanded?: boolean;
  /** A control on the trailing side (Toggle, Stepper, DatePicker, PopUpButton…). The title becomes its label.
   *  Without a title the control fills the row: a full-width slider row is `<ListRow control={<Slider label="…" />} />`. */
  control?: ReactNode;
  /** A text button on the trailing side (kit "Button"). */
  buttonLabel?: string;
  onButtonClick?: () => void;
  /** Pop-up menu value (kit "Pop-up"): secondary text + chevron.up.chevron.down. Pass a <PopUpButton> (it then looks
   *  like the row's value, with one chevron, and opens the iOS menu). A plain <select> here opens the browser's own list
   *  in React (ios.js isn't loaded), so use a PopUpButton. */
  popup?: ReactNode;
  /** Action row (kit "Row - Button"): the title is an accent action. destructive = red. center = centred. */
  action?: boolean;
  destructive?: boolean;
  center?: boolean;
  disabled?: boolean;
  /** Swipe actions (ListRowAction elements). Trailing = swipe left; the last one runs on a long swipe. */
  leadingActions?: ReactNode;
  trailingActions?: ReactNode;
  /** Delete: adds a red "Delete" swipe action and the red minus in edit mode. */
  onDelete?: () => void;
  deleteLabel?: string;
  /** iPad list column (split view): this row's item is the one open in the detail column. Draws the grey selection
   *  fill on iPad sizes (nothing on iPhone, where lists keep no selection) and sets aria-current="true". */
  current?: boolean;
  /** Edit-mode selection circle (several rows can be selected). */
  selected?: boolean;
  onSelectedChange?: (selected: boolean) => void;
  /** Extra content inside the row after the title (custom trailing views). */
  children?: ReactNode;
}

const imageClass: Record<ListRowImageStyle, string> = {
  fill: 'ios-cell__image ios-cell__image--fill',
  circle: 'ios-cell__image ios-cell__image--circle',
  rounded: 'ios-cell__image ios-cell__image--rounded',
  symbol: 'ios-cell__image ios-cell__image--symbol',
};

/**
 * One list row (kit "Row"). Use it inside a ListSection.
 *
 *     <ListRow title="Wi-Fi" detail="Home" icon="wifi" href="#wifi" />                  navigation
 *     <ListRow title="Name" checked={sort === 'name'} onClick={() => setSort('name')} /> checkmark choice
 *     <ListRow title="Notifications" control={<Toggle checked={n} onChange={setN} />} />  control (see FormRow)
 *     <ListRow title="Sign Out" action destructive onClick={signOut} />                    action row
 *     <ListRow title="Anna" subtitle="Lunch?" onDelete={remove}
 *       trailingActions={<ListRowAction label="Flag" icon="flag" color="orange" onClick={flag} />} />
 *     <ListRow title={note.title} current={note.id === openId} onClick={() => open(note.id)} /> iPad list column
 * The ref is the row's <li> (e.g. to anchor an ActionSheet to the row on iPad).
 */
export const ListRow = forwardRef(function ListRow({
  title,
  subtitle,
  detail,
  icon,
  iconColor,
  image,
  imageStyle = 'rounded',
  imageAlt = '',
  leadingSymbol,
  symbol,
  chevron,
  href,
  onClick,
  onInfo,
  infoLabel = 'More Info',
  checked,
  multiple,
  expanded,
  control,
  buttonLabel,
  onButtonClick,
  popup,
  action,
  destructive,
  center,
  disabled,
  leadingActions,
  trailingActions,
  onDelete,
  deleteLabel = 'Delete',
  current,
  selected,
  onSelectedChange,
  className,
  style,
  children,
  ...rest
}: ListRowProps, ref: ForwardedRef<HTMLLIElement>) {
  const list = useContext(ListContext);
  const section = useContext(SectionContext);
  const rowIndex = useContext(RowIndexContext);
  const rowId = useId();
  const fieldId = useId();
  const editing = list.editing;
  const reorder = editing && section.onMove != null;

  // Swipe state ------------------------------------------------------------------------------
  const trailing =
    trailingActions ?? (onDelete ? <ListRowAction label={deleteLabel} icon="trash" destructive onClick={onDelete} /> : null);
  const hasSwipe = !disabled && (leadingActions != null || trailing != null);
  const liRef = useRef<HTMLLIElement | null>(null);
  const setLi = useCallback(
    (el: HTMLLIElement | null) => {
      liRef.current = el;
      if (typeof ref === 'function') ref(el);
      else if (ref) ref.current = el;
    },
    [ref],
  );
  const [side, setSide] = useState<'leading' | 'trailing' | null>(null);
  const [offset, setOffset] = useState<number | null>(null); // translateX while dragging
  const drag = useRef<{ x0: number; y0: number; base: number; active: boolean; natural: number; id: number } | null>(null);
  const suppressClick = useRef(false);
  const isOpen = list.openRow === rowId && side != null;

  const close = useCallback(() => {
    setSide(null);
    setOffset(null);
    if (list.openRow === rowId) list.setOpenRow(null);
  }, [list, rowId]);
  const closeAnimated = useCallback(() => {
    if (!side) return close();
    const acts = liRef.current?.querySelector<HTMLElement>(`:scope > .ios-swipe-actions__actions--${side}`);
    const w = (acts?.scrollWidth ?? 0) + 26;
    setOffset(side === 'trailing' ? w : -w); // slide back to x = 0, then leave the open layout
    window.setTimeout(close, 300);
  }, [side, close]);
  useEffect(() => {
    if (list.openRow !== rowId && side != null && offset == null) setSide(null); // another row opened
  }, [list.openRow, rowId, side, offset]);
  useEffect(() => {
    if (!isOpen) return;
    const onDown = (e: PointerEvent) => {
      if (!liRef.current?.contains(e.target as Node)) closeAnimated();
    };
    const onScroll = () => closeAnimated();
    document.addEventListener('pointerdown', onDown);
    window.addEventListener('scroll', onScroll, { capture: true, passive: true });
    return () => {
      document.removeEventListener('pointerdown', onDown);
      window.removeEventListener('scroll', onScroll, { capture: true });
    };
  }, [isOpen, closeAnimated]);

  const naturalFor = (s: 'leading' | 'trailing') => {
    // Width the cell moves when open: the actions + 10 gap + 16 margin.
    const acts = liRef.current?.querySelector<HTMLElement>(`:scope > .ios-swipe-actions__actions--${s}`);
    const w = (acts?.scrollWidth ?? 0) + 26;
    return s === 'trailing' ? -w : w;
  };
  const onPointerDown = (e: ReactPointerEvent<HTMLElement>) => {
    if (!hasSwipe || editing || e.button !== 0) return;
    if ((e.target as HTMLElement).closest('.ios-cell__info, .ios-cell__grabber, .ios-cell__edit, .ios-cell__select')) return;
    drag.current = { x0: e.clientX, y0: e.clientY, base: side ? naturalFor(side) : 0, active: false, natural: 0, id: e.pointerId };
  };
  const onPointerMove = (e: ReactPointerEvent<HTMLElement>) => {
    const d = drag.current;
    if (!d || e.pointerId !== d.id) return;
    const dx = e.clientX - d.x0;
    const dy = e.clientY - d.y0;
    if (!d.active) {
      if (Math.abs(dx) < 10 && Math.abs(dy) < 10) return;
      if (Math.abs(dy) >= Math.abs(dx)) {
        drag.current = null;
        return;
      }
      d.active = true;
      e.currentTarget.setPointerCapture(e.pointerId);
      list.setOpenRow(rowId);
    }
    let x = d.base + dx;
    let s: 'leading' | 'trailing' | null = x < 0 ? 'trailing' : x > 0 ? 'leading' : null;
    if ((s === 'trailing' && trailing == null) || (s === 'leading' && leadingActions == null)) {
      s = null;
      x /= 6;
    }
    d.natural = s ? naturalFor(s) : 0;
    setSide(s);
    setOffset(x - d.natural);
  };
  const onPointerEnd = (e: ReactPointerEvent<HTMLElement>) => {
    const d = drag.current;
    drag.current = null;
    if (!d || !d.active || e.pointerId !== d.id) return;
    suppressClick.current = true;
    const x = (offset ?? 0) + d.natural;
    const width = liRef.current?.clientWidth ?? 400;
    const s = side;
    if (s && Math.abs(x) > width * 0.6) {
      const acts = liRef.current?.querySelectorAll<HTMLButtonElement>(`:scope > .ios-swipe-actions__actions--${s} .ios-swipe-actions__action`);
      const edge = acts && (s === 'trailing' ? acts[acts.length - 1] : acts[0]);
      close();
      edge?.click();
    } else if (s && Math.abs(x) > Math.abs(d.natural) / 2) {
      setOffset(null); // settle open
      list.setOpenRow(rowId);
    } else {
      // animate back, then leave the open layout
      setOffset(-d.natural);
      window.setTimeout(close, 300);
    }
  };
  const onClickCapture = (e: ReactMouseEvent<HTMLElement>) => {
    if (suppressClick.current) {
      suppressClick.current = false;
      e.preventDefault();
      e.stopPropagation();
      return;
    }
    if (isOpen && !(e.target as HTMLElement).closest('.ios-swipe-actions__actions')) {
      e.preventDefault();
      e.stopPropagation();
      closeAnimated();
    }
  };

  // Reorder ---------------------------------------------------------------------------------
  const moveDrag = useRef<{ y0: number; index: number; id: number } | null>(null);
  const [dragY, setDragY] = useState<number | null>(null);
  const grabber = reorder && (
    <button
      type="button"
      className="ios-cell__grabber"
      aria-label={`Reorder ${typeof title === 'string' ? title : ''}`.trim()}
      onKeyDown={(e: ReactKeyboardEvent) => {
        if (e.key === 'ArrowUp' && rowIndex > 0) {
          e.preventDefault();
          section.onMove?.(rowIndex, rowIndex - 1);
        } else if (e.key === 'ArrowDown') {
          const count = liRef.current?.parentElement?.children.length ?? 0;
          if (rowIndex < count - 1) {
            e.preventDefault();
            section.onMove?.(rowIndex, rowIndex + 1);
          }
        }
      }}
      onPointerDown={e => {
        if (e.button !== 0) return;
        e.preventDefault();
        e.currentTarget.setPointerCapture(e.pointerId);
        moveDrag.current = { y0: e.clientY, index: rowIndex, id: e.pointerId };
        setDragY(0);
      }}
      onPointerMove={e => {
        const m = moveDrag.current;
        if (!m || e.pointerId !== m.id) return;
        let dy = e.clientY - m.y0;
        const li = liRef.current;
        const next = li?.nextElementSibling as HTMLElement | null;
        const prev = li?.previousElementSibling as HTMLElement | null;
        if (dy > 0 && next && dy > next.offsetHeight / 2) {
          section.onMove?.(m.index, m.index + 1);
          m.index += 1;
          m.y0 += next.offsetHeight;
          dy -= next.offsetHeight;
        } else if (dy < 0 && prev && -dy > prev.offsetHeight / 2) {
          section.onMove?.(m.index, m.index - 1);
          m.index -= 1;
          m.y0 -= prev.offsetHeight;
          dy += prev.offsetHeight;
        }
        setDragY(dy);
      }}
      onPointerUp={() => {
        moveDrag.current = null;
        setDragY(null);
      }}
      onPointerCancel={() => {
        moveDrag.current = null;
        setDragY(null);
      }}
    />
  );

  // Cell content -----------------------------------------------------------------------------
  const tall = subtitle != null;
  const isChoice = checked !== undefined;
  const ownButtons = onInfo != null || buttonLabel != null || popup != null || (editing && (onDelete != null || onSelectedChange != null || reorder));
  const interactive = href != null || onClick != null;
  const showChevron = chevron ?? (interactive && !isChoice && !action && expanded === undefined && control == null);

  const leading = (
    <>
      {editing && onDelete && (
        <button
          type="button"
          className="ios-cell__edit ios-cell__edit--remove"
          aria-label={`${deleteLabel} ${typeof title === 'string' ? title : ''}`.trim()}
          onClick={() => {
            if (side === 'trailing') closeAnimated();
            else {
              setSide('trailing');
              setOffset(null);
              list.setOpenRow(rowId);
            }
          }}
        />
      )}
      {editing && onSelectedChange && (
        <input
          type="checkbox"
          className="ios-cell__select"
          aria-label={`Select ${typeof title === 'string' ? title : ''}`.trim()}
          checked={!!selected}
          onChange={e => onSelectedChange(e.target.checked)}
        />
      )}
      {icon && (
        <span className={imageClass.rounded} style={iconColor ? vars(undefined, { '--ios-cell-icon-bg': systemColor(iconColor) }) : undefined} aria-hidden="true">
          <Icon name={icon} />
        </span>
      )}
      {leadingSymbol && <span className={cx(imageClass.symbol, 'ios-icon', `ios-icon-${leadingSymbol}`)} aria-hidden="true" />}
      {image != null &&
        (typeof image === 'string' ? <img className={imageClass[imageStyle]} src={image} alt={imageAlt} /> : <span className={imageClass[imageStyle]}>{image}</span>)}
    </>
  );
  const textParts = (
    <>
      {title != null && <span className="ios-cell__title">{title}</span>}
      {subtitle != null && <span className="ios-cell__subtitle">{subtitle}</span>}
    </>
  );
  const trailingParts = (
    <>
      {children}
      {detail != null && <span className="ios-cell__detail">{detail}</span>}
      {symbol && <Icon name={symbol} className="ios-cell__symbol" />}
      {popup != null && <span className="ios-cell__popup">{popup}</span>}
      {buttonLabel != null && (
        <button type="button" className="ios-cell__button" onClick={onButtonClick}>
          {buttonLabel}
        </button>
      )}
      {control != null && <FieldIdContext.Provider value={fieldId}>{control}</FieldIdContext.Provider>}
      {onInfo && <button type="button" className="ios-cell__info" aria-label={infoLabel} onClick={onInfo} />}
      {checked && <span className="ios-cell__checkmark" aria-hidden="true" />}
      {expanded !== undefined && <span className="ios-cell__disclosure" aria-hidden="true" />}
      {showChevron && <span className="ios-cell__chevron" aria-hidden="true" />}
      {grabber}
    </>
  );

  const swipeHandlers = hasSwipe
    ? {
        onPointerDown,
        onPointerMove,
        onPointerUp: onPointerEnd,
        onPointerCancel: onPointerEnd,
        onClickCapture,
        onDragStart: (e: ReactMouseEvent<HTMLElement>) => e.preventDefault(), // a mouse drag on a link row would drag the link
      }
    : {};
  const cellStyle: CSSProperties | undefined = offset != null ? { transform: `translateX(${offset}px)` } : undefined;
  const currentProps = current ? { 'aria-current': 'true' as const } : {};

  let cell: ReactNode;
  if (action) {
    cell = (
      <button
        type="button"
        className={cx('ios-cell', 'ios-cell--button', destructive && 'ios-cell--destructive', center && 'ios-cell--center')}
        disabled={disabled}
        onClick={onClick}
        style={cellStyle}
        {...currentProps}
        {...swipeHandlers}
      >
        {title}
      </button>
    );
  } else if (control != null) {
    cell = (
      <div className="ios-cell" aria-disabled={disabled || undefined} style={cellStyle} {...currentProps} {...swipeHandlers}>
        {leading}
        {(title != null || subtitle != null) && (
          <label className="ios-cell__content" htmlFor={fieldId}>
            {textParts}
          </label>
        )}
        {trailingParts}
      </div>
    );
  } else if (interactive && !ownButtons) {
    const common = {
      className: 'ios-cell',
      style: cellStyle,
      ...currentProps,
      ...swipeHandlers,
    };
    const choiceProps = isChoice ? { role: multiple ? 'checkbox' : 'radio', 'aria-checked': checked } : {};
    const expandProps = expanded !== undefined ? { 'aria-expanded': expanded } : {};
    cell =
      href != null && !disabled ? (
        <a href={href} onClick={onClick} {...common} {...choiceProps} {...expandProps}>
          {leading}
          <span className="ios-cell__content">{textParts}</span>
          {trailingParts}
        </a>
      ) : (
        <button type="button" disabled={disabled} onClick={onClick} {...common} {...choiceProps} {...expandProps}>
          {leading}
          <span className="ios-cell__content">{textParts}</span>
          {trailingParts}
        </button>
      );
  } else if (interactive) {
    // The row has its own buttons: the content is the link that covers the row.
    const choiceProps = isChoice ? { role: multiple ? 'checkbox' : 'radio', 'aria-checked': checked } : {};
    cell = (
      <div className="ios-cell" aria-disabled={disabled || undefined} style={cellStyle} {...swipeHandlers}>
        {leading}
        {href != null && !disabled ? (
          <a className="ios-cell__content ios-cell__link" href={href} onClick={editing ? e => e.preventDefault() : onClick} {...choiceProps} {...currentProps}>
            {textParts}
          </a>
        ) : (
          <button
            type="button"
            className="ios-cell__content ios-cell__link"
            disabled={disabled}
            onClick={editing ? undefined : onClick}
            aria-expanded={expanded}
            {...choiceProps}
            {...currentProps}
          >
            {textParts}
          </button>
        )}
        {trailingParts}
      </div>
    );
  } else {
    cell = (
      <div className="ios-cell" aria-disabled={disabled || undefined} style={cellStyle} {...currentProps} {...swipeHandlers}>
        {leading}
        <span className="ios-cell__content">{textParts}</span>
        {trailingParts}
      </div>
    );
  }

  const liStyle: CSSProperties | undefined =
    dragY != null ? { ...style, transform: `translateY(${dragY}px)`, position: 'relative', zIndex: 3 } : style;
  if (!hasSwipe && !(editing && onDelete)) {
    return (
      <li ref={setLi} className={cx(dragY != null && 'is-dragging', className)} style={liStyle} {...rest}>
        {cell}
      </li>
    );
  }
  return (
    <SwipeContext.Provider value={{ close }}>
      <li
        ref={setLi}
        className={cx(
          'ios-swipe-actions',
          side && `ios-swipe-actions--open-${side}`,
          tall && 'ios-swipe-actions--stacked',
          offset != null && drag.current?.active && 'is-swiping',
          className,
        )}
        style={liStyle}
        {...rest}
      >
        {leadingActions != null && <div className="ios-swipe-actions__actions ios-swipe-actions__actions--leading">{leadingActions}</div>}
        {cell}
        {trailing != null && <div className="ios-swipe-actions__actions ios-swipe-actions__actions--trailing">{trailing}</div>}
      </li>
    </SwipeContext.Provider>
  );
});

export interface FormRowProps extends Omit<ListRowProps, 'control' | 'title'> {
  /** The setting's name; it labels the control. */
  label: ReactNode;
  /** The control: Toggle, Stepper, TextField, DatePicker, PopUpButton, Slider… */
  children: ReactNode;
}

/**
 * A Settings-style row: label on the leading side, the control on the trailing side.
 *
 *     <FormRow label="Airplane Mode" icon="bolt" iconColor="var(--ios-orange)"><Toggle checked={on} onChange={setOn} /></FormRow>
 */
export const FormRow = forwardRef(function FormRow({ label, children, ...rest }: FormRowProps, ref: ForwardedRef<HTMLLIElement>) {
  return <ListRow ref={ref} title={label} control={children} {...rest} />;
});
// ---------------------------------------------------------------------------------------------------
// menu.tsx
// ---------------------------------------------------------------------------------------------------

// ---------------------------------------------------------------------------------------------------------------
// Shared helpers (names are prefixed: every component file is merged into one module).
// ---------------------------------------------------------------------------------------------------------------

const MENU_REGULAR_QUERY = '(min-width: 744px) and (min-height: 600px)';
/** iPad-like layout at this element: the .ios-regular / .ios-compact classes win, else the screen size. */
export function menuIsRegular(el: Element | null): boolean {
  if (el && el.closest('.ios-regular')) return true;
  if (el && el.closest('.ios-compact')) return false;
  return typeof window !== 'undefined' && window.matchMedia(MENU_REGULAR_QUERY).matches;
}
const menuClamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(v, Math.max(lo, hi)));
const menuIsOpen = (el: Element | null | undefined) => !!el && el.matches(':popover-open');
const MENU_ITEMS = '.ios-menu-item, .ios-menu__control, .ios-menu__more';
const menuEnabled = (el: HTMLElement) =>
  !(el as HTMLButtonElement).disabled && el.getAttribute('aria-disabled') !== 'true';
/** The enabled items of one menu panel (not those of its submenus). */
const menuItemsOf = (menu: HTMLElement) =>
  [...menu.querySelectorAll<HTMLElement>(MENU_ITEMS)].filter(
    i => i.closest('.ios-menu') === menu && menuEnabled(i) && i.offsetParent !== null,
  );

/** Places an open menu popover 8 below (or above) an anchor rect, inside the screen margins (16 / 20). */
export function menuPlace(menu: HTMLElement, r: DOMRect) {
  const vw = document.documentElement.clientWidth;
  const vh = window.innerHeight;
  const m = menuIsRegular(menu) ? 20 : 16;
  const gap = 8;
  menu.style.maxHeight = '';
  const w = menu.offsetWidth;                          // layout size: the opening animation scales the menu
  let h = menu.offsetHeight;
  const alignRight = r.left + r.width / 2 > vw / 2;
  const left = menuClamp(alignRight ? r.right - w : r.left, m, vw - m - w);
  let top: number;
  let below = true;
  if (r.bottom + gap + h <= vh - m) top = r.bottom + gap;
  else if (r.top - gap - h >= m) {
    top = r.top - gap - h;
    below = false;
  } else {
    below = vh - r.bottom >= r.top;
    h = Math.max(120, (below ? vh - r.bottom : r.top) - gap - m);
    menu.style.maxHeight = `${h}px`;
    top = below ? r.bottom + gap : r.top - gap - h;
  }
  menu.style.inset = 'auto';
  menu.style.margin = '0';
  menu.style.left = `${Math.round(left)}px`;
  menu.style.top = `${Math.round(top)}px`;
  menu.style.setProperty('--ios-menu-origin', `${alignRight ? 'right' : 'left'} ${below ? 'top' : 'bottom'}`);
}

/** Listens to the native 'toggle' event of a popover element (works in React 18 and 19). */
export function useMenuToggle(ref: { current: HTMLElement | null }, onClosed: () => void) {
  const cb = useRef(onClosed);
  cb.current = onClosed;
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const on = (e: Event) => {
      if ((e as ToggleEvent).newState === 'closed') cb.current();
    };
    el.addEventListener('toggle', on);
    return () => el.removeEventListener('toggle', on);
  }, [ref]);
}

/** Arrow keys, Home/End, ←/→ for submenus and Tab (closes) inside one menu panel. */
function menuKeyDown(e: ReactKeyboardEvent<HTMLDivElement>, close: () => void, popup = true) {
  const panel = e.currentTarget;
  const t = e.target as HTMLElement;
  if (t.closest('.ios-menu') !== panel) return;      // handled by the nested submenu panel
  const items = menuItemsOf(panel);
  const i = items.indexOf(t.closest(MENU_ITEMS) as HTMLElement);
  const go = (n: number) => {
    e.preventDefault();
    if (items.length) items[(n + items.length) % items.length].focus();
  };
  switch (e.key) {
    case 'ArrowDown': return go(i < 0 ? 0 : i + 1);
    case 'ArrowUp': return go(i < 0 ? items.length - 1 : i - 1);
    case 'Home': return go(0);
    case 'End': return go(items.length - 1);
    case 'ArrowRight': {
      const row = t.closest<HTMLElement>('.ios-menu-item[aria-haspopup]');
      if (row && row.getAttribute('aria-expanded') !== 'true' && !row.classList.contains('ios-menu-item--header')) {
        e.preventDefault();
        row.click();
      }
      return;
    }
    case 'ArrowLeft':
      if (panel.classList.contains('ios-menu--submenu') && menuIsOpen(panel)) {
        e.preventDefault();
        panel.hidePopover();
      }
      return;
    case 'Tab':
      if (!popup) return;                              // a static menu in the page keeps normal Tab order
      e.preventDefault();
      close();
      return;
    default:
  }
}

interface MenuScopeValue {
  /** Closes the whole menu (after a choice). */
  close: () => void;
  variant: 'menu' | 'edit';
  inControls: boolean;
}
const MenuScope = createContext<MenuScopeValue>({ close: () => {}, variant: 'menu', inControls: false });

// ---------------------------------------------------------------------------------------------------------------
// Menu
// ---------------------------------------------------------------------------------------------------------------

export interface MenuProps {
  /**
   * The element that opens the menu when clicked: a Button, a bar button, any element with onClick.
   * Omit it for a static menu drawn in the page (a demo, or a menu you place yourself).
   */
  trigger?: ReactElement<{ onClick?: (e: ReactMouseEvent<HTMLElement>) => void; onPointerDown?: (e: ReactPointerEvent<HTMLElement>) => void }>;
  /** Accessible name of the menu ("Sort By", "More"). */
  label?: string;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** menu (default: the Thick-material panel) · edit (the Cut / Copy / Paste capsule over a text selection). */
  variant?: 'menu' | 'edit';
  /** Edit menu only: shows the round "more" button at the end and calls this when it is tapped. */
  onMore?: () => void;
  /** Indent every item for checkmarks (automatic when an item has `checked`; ios.css does it with :has()). */
  hasSelection?: boolean;
  className?: string;
  style?: CSSProperties;
  /** MenuControlGroup (first), MenuItem, MenuSection, MenuDivider. */
  children?: ReactNode;
}

/**
 * An iOS menu: a Thick-material panel that opens from ANY trigger, 8 below it (above when there is no room).
 * Choosing an item runs its onSelect and closes the menu.
 *
 *     <Menu label="More" trigger={<Button icon="ellipsis" label="More" />}>
 *       <MenuControlGroup>…3–4 MenuItem with icon…</MenuControlGroup>
 *       <MenuItem icon="pencil" label="Rename" onSelect={rename} />
 *       <MenuSection title="Sort By">…</MenuSection>
 *       <MenuItem icon="trash" label="Delete" destructive onSelect={remove} />
 *     </Menu>
 */
export function Menu({
  trigger,
  label,
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  variant = 'menu',
  onMore,
  hasSelection,
  className,
  style,
  children,
}: MenuProps) {
  const id = useId();
  const [open, setOpen] = useControllable(openProp, defaultOpen, onOpenChange);
  const panel = useRef<HTMLDivElement>(null);
  const triggerEl = useRef<HTMLElement | null>(null);
  const openRef = useRef(open);
  openRef.current = open;
  const wasOpenAtPointerDown = useRef(false);
  const keyboardOpen = useRef(false);
  const close = useCallback(() => {
    if (openRef.current) setOpen(false);
  }, [setOpen]);

  // Show / hide the popover and place it next to the trigger (before paint: no flash).
  useIsoLayoutEffect(() => {
    const el = panel.current;
    if (!el || !trigger) return;
    if (open && !menuIsOpen(el)) {
      // Opened from code (open / defaultOpen) before any click: find the trigger by aria-controls.
      triggerEl.current ??= document.querySelector<HTMLElement>(`[aria-controls="${CSS.escape(id)}"]`);
      el.showPopover();
      if (triggerEl.current) menuPlace(el, triggerEl.current.getBoundingClientRect());
      const first = menuItemsOf(el)[0];
      if (keyboardOpen.current && first) first.focus({ preventScroll: true });
      else el.focus({ preventScroll: true });
    } else if (!open && menuIsOpen(el)) el.hidePopover();
  }, [open, trigger, id]);

  // Closed by the browser (tap outside, Esc): update the state and give focus back to the trigger.
  useMenuToggle(panel, () => {
    const el = panel.current;
    const active = document.activeElement;
    if (triggerEl.current && (!active || active === document.body || (el && el.contains(active)))) triggerEl.current.focus({ preventScroll: true });
    if (openRef.current) setOpen(false);
  });

  const scope: MenuScopeValue = { close, variant, inControls: false };

  const body = (
    <div
      ref={panel}
      id={id}
      className={cx('ios-menu', variant === 'edit' && 'ios-menu--edit', hasSelection && 'ios-menu--has-selection', className)}
      style={style}
      role="menu"
      aria-label={label}
      tabIndex={-1}
      popover={trigger ? 'auto' : undefined}
      onKeyDown={e => menuKeyDown(e, close, !!trigger)}
    >
      <MenuScope.Provider value={scope}>{children}</MenuScope.Provider>
      {variant === 'edit' && onMore && <button className="ios-menu__more" type="button" aria-label="More" onClick={onMore} />}
    </div>
  );
  if (!trigger) return body;

  const tp = trigger.props;
  const t = cloneElement(trigger as ReactElement<Record<string, unknown>>, {
    'aria-haspopup': 'menu',
    'aria-expanded': open,
    'aria-controls': id,
    onPointerDown: (e: ReactPointerEvent<HTMLElement>) => {
      wasOpenAtPointerDown.current = menuIsOpen(panel.current);
      tp.onPointerDown?.(e);
    },
    onClick: (e: ReactMouseEvent<HTMLElement>) => {
      tp.onClick?.(e);
      if (e.defaultPrevented) return;
      triggerEl.current = e.currentTarget;
      if (wasOpenAtPointerDown.current || open) {
        // The tap that started on the trigger already closed the menu (light dismiss): keep it closed.
        wasOpenAtPointerDown.current = false;
        setOpen(false);
        return;
      }
      keyboardOpen.current = e.detail === 0;
      setOpen(true);
    },
  });
  return (
    <>
      {t}
      {body}
    </>
  );
}

// ---------------------------------------------------------------------------------------------------------------
// MenuItem (action, checkable item, submenu row, control-group button, edit-menu item)
// ---------------------------------------------------------------------------------------------------------------

export interface MenuItemProps extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'children' | 'onSelect' | 'role' | 'value'> {
  /** The title (a verb for actions: "Rename", "Delete"). */
  label: ReactNode;
  /** A second line in secondary grey ("Makes a copy"). */
  subtitle?: ReactNode;
  icon?: IconName;
  /** Keyboard shortcut shown at the trailing edge (iPad with a keyboard): "⌘R", "⇧⌘N". */
  shortcut?: string;
  /** Red: deletes or removes something. */
  destructive?: boolean;
  /** true / false = a checkable item: a checkmark in front when true (menuitemcheckbox by default). */
  checked?: boolean;
  /** menuitemradio for one choice out of several (PopUpButton uses it), menuitemcheckbox for an on/off option. */
  role?: 'menuitem' | 'menuitemcheckbox' | 'menuitemradio';
  /** Runs when the item is chosen. */
  onSelect?: () => void;
  /** Keep the menu open after choosing (for on/off options you flip several times). */
  keepOpen?: boolean;
  /** Value reported by a PopUpButton. */
  value?: string;
  /** MenuItem children make this row a SUBMENU (chevron.right; opens over its row on iPhone, beside the menu on iPad). */
  children?: ReactNode;
}

/** One menu row. Inside MenuControlGroup it renders as an icon button; inside an edit menu as a text button. */
export function MenuItem({
  label,
  subtitle,
  icon,
  shortcut,
  destructive,
  checked,
  role,
  onSelect,
  keepOpen,
  value,
  disabled,
  className,
  children,
  onClick,
  type = 'button',
  ...rest
}: MenuItemProps) {
  const scope = useContext(MenuScope);
  const hasSub = Children.toArray(children).length > 0;
  const itemRole = role ?? (checked !== undefined ? 'menuitemcheckbox' : 'menuitem');
  const choose = (e: ReactMouseEvent<HTMLButtonElement>) => {
    onClick?.(e);
    if (e.defaultPrevented || disabled) return;
    onSelect?.();
    if (!keepOpen) scope.close();
  };
  const common = {
    ...rest,
    type,
    role: itemRole,
    'aria-checked': itemRole === 'menuitem' ? undefined : !!checked,
    'aria-disabled': disabled || undefined,
    disabled,
    'data-value': value,
  };

  if (scope.inControls) {
    return (
      <button {...common} className={cx('ios-menu__control', destructive && 'ios-menu__control--destructive', className)} onClick={choose}>
        {icon && <Icon name={icon} />}
        <span className="ios-menu__control-label">{label}</span>
      </button>
    );
  }
  if (scope.variant === 'edit') {
    return (
      <button {...common} className={cx('ios-menu-item', destructive && 'ios-menu-item--destructive', className)} onClick={choose}>
        {label}
      </button>
    );
  }
  const content = (
    <>
      {icon && <Icon name={icon} />}
      <span className="ios-menu-item__label">
        {label}
        {subtitle != null && <span className="ios-menu-item__subtitle">{subtitle}</span>}
      </span>
      {shortcut && <span className="ios-menu-item__shortcut">{shortcut}</span>}
    </>
  );
  if (hasSub)
    return (
      <MenuSubmenu label={label} disabled={disabled} className={className} content={content} buttonProps={rest}>
        {children}
      </MenuSubmenu>
    );
  return (
    <button {...common} className={cx('ios-menu-item', destructive && 'ios-menu-item--destructive', className)} onClick={choose}>
      {content}
    </button>
  );
}

function MenuSubmenu({
  label,
  disabled,
  className,
  content,
  buttonProps,
  children,
}: {
  label: ReactNode;
  disabled?: boolean;
  className?: string;
  content: ReactNode;
  buttonProps?: ButtonHTMLAttributes<HTMLButtonElement>;
  children: ReactNode;
}) {
  const scope = useContext(MenuScope);
  const id = useId();
  const [open, setOpen] = useState(false);
  const [compact, setCompact] = useState(true);
  const row = useRef<HTMLButtonElement>(null);
  const sub = useRef<HTMLDivElement>(null);
  const keyboard = useRef(false);
  const openRef = useRef(open);
  openRef.current = open;

  useIsoLayoutEffect(() => {
    const el = sub.current;
    const r = row.current;
    if (!el || !r) return;
    if (open && !menuIsOpen(el)) {
      el.showPopover();
      const parent = r.closest<HTMLElement>('.ios-menu');
      if (!parent) return;
      parent.getAnimations({ subtree: true }).forEach(a => a.finish());
      const pr = parent.getBoundingClientRect();
      const rr = r.getBoundingClientRect();
      const vw = document.documentElement.clientWidth;
      const vh = window.innerHeight;
      const m = compact ? 16 : 20;
      if (compact) el.style.width = `${pr.width}px`;
      const w = el.offsetWidth;
      const h = el.offsetHeight;
      let left = compact ? pr.left : pr.right - 8;       // iPad: beside the menu, overlapping it by 8
      if (!compact && left + w > vw - m) left = pr.left - w + 8;
      el.style.inset = 'auto';
      el.style.margin = '0';
      el.style.left = `${Math.round(menuClamp(left, m, vw - m - w))}px`;
      el.style.top = `${Math.round(menuClamp(rr.top - 10, m, vh - m - h))}px`;
      el.style.setProperty('--ios-menu-origin', 'left top');
      const first = menuItemsOf(el).filter(i => !i.classList.contains('ios-menu-item--header'))[0];
      (keyboard.current && first ? first : el).focus({ preventScroll: true });
    } else if (!open && menuIsOpen(el)) el.hidePopover();
  }, [open, compact]);

  useMenuToggle(sub, () => {
    if (openRef.current) setOpen(false);
    const active = document.activeElement;
    if (row.current && (!active || active === document.body || (sub.current && sub.current.contains(active)))) row.current.focus({ preventScroll: true });
  });

  const toggle = (e: ReactMouseEvent<HTMLButtonElement>) => {
    if (disabled) return;
    keyboard.current = e.detail === 0;
    if (!open) setCompact(!menuIsRegular(e.currentTarget));
    setOpen(!open);
  };
  return (
    <>
      <button
        {...buttonProps}
        ref={row}
        type="button"
        role="menuitem"
        className={cx('ios-menu-item', className)}
        aria-haspopup="menu"
        aria-expanded={open}
        aria-controls={id}
        aria-disabled={disabled || undefined}
        disabled={disabled}
        onClick={toggle}
      >
        {content}
      </button>
      <div
        ref={sub}
        id={id}
        className="ios-menu ios-menu--submenu"
        role="menu"
        aria-label={typeof label === 'string' ? label : undefined}
        tabIndex={-1}
        popover="auto"
        onKeyDown={e => menuKeyDown(e, scope.close)}
      >
        {open && compact && (
          <button type="button" role="menuitem" className="ios-menu-item ios-menu-item--header" aria-haspopup="menu" aria-expanded="true" onClick={() => setOpen(false)}>
            {content}
          </button>
        )}
        <MenuScope.Provider value={{ ...scope, inControls: false }}>{children}</MenuScope.Provider>
      </div>
    </>
  );
}

// ---------------------------------------------------------------------------------------------------------------
// Sections, dividers, control group
// ---------------------------------------------------------------------------------------------------------------

export interface MenuSectionProps {
  /** Optional title in small grey letters ("Sort By"). Without a title it's just a group with a separator above. */
  title?: string;
  className?: string;
  children?: ReactNode;
}
/** A group of items with a separator above it (unless it is the first thing in the menu) and an optional title. */
export function MenuSection({ title, className, children }: MenuSectionProps) {
  const id = useId();
  return (
    <div className={cx('ios-menu__section', className)} role="group" aria-labelledby={title ? id : undefined}>
      {title && (
        <div className="ios-menu__section-title" id={id}>
          {title}
        </div>
      )}
      {children}
    </div>
  );
}

/** A separator between groups of items (prefer MenuSection for a titled group). */
export function MenuDivider({ className }: { className?: string }) {
  return <hr className={cx('ios-menu__separator', className)} />;
}

/** The row of 3–4 icon buttons at the top of a menu (kit "Control Group"): the most common actions. Children: MenuItem with icon + short label. */
export function MenuControlGroup({ label, className, children }: { label?: string; className?: string; children?: ReactNode }) {
  const scope = useContext(MenuScope);
  return (
    <div className={cx('ios-menu__controls', className)} role="group" aria-label={label}>
      <MenuScope.Provider value={{ ...scope, inControls: true }}>{children}</MenuScope.Provider>
    </div>
  );
}

// ---------------------------------------------------------------------------------------------------------------
// ContextMenu
// ---------------------------------------------------------------------------------------------------------------

export interface ContextMenuProps {
  /** The menu items (MenuControlGroup, MenuItem, MenuSection, MenuDivider). */
  menu: ReactNode;
  /** Accessible name of the menu. */
  label?: string;
  /** What is lifted above the menu. Default: a copy of the children at their size. */
  preview?: ReactNode;
  onOpenChange?: (open: boolean) => void;
  /** The content that opens the menu on touch-and-hold (500 ms) or right-click. One element. */
  children: ReactNode;
}

interface ContextLayout {
  left: number;
  top: number;
  above: boolean;
  horizontal: boolean;
  leading: boolean;
  trailing: boolean;
  maxHeight?: number;
}

/**
 * Touch-and-hold or right-click on the content lifts a preview of it over a dimmed page and shows a menu next to it.
 *
 *     <ContextMenu label="Photo" menu={<><MenuItem icon="doc-on-doc" label="Copy" onSelect={copy} /> … </>}>
 *       <PhotoCard />
 *     </ContextMenu>
 */
export function ContextMenu({ menu, label, preview, onOpenChange, children }: ContextMenuProps) {
  const [open, setOpenState] = useState(false);
  const [size, setSize] = useState<{ w: number; h: number; radius: string; rect: DOMRect } | null>(null);
  const [layout, setLayout] = useState<ContextLayout | null>(null);
  const wrap = useRef<HTMLDivElement>(null);
  const cm = useRef<HTMLDivElement>(null);
  const timer = useRef(0);
  const start = useRef<{ x: number; y: number } | null>(null);
  const suppress = useRef(false);
  const [pressed, setPressed] = useState(false);
  const openRef = useRef(open);
  openRef.current = open;
  const onChange = useRef(onOpenChange);
  onChange.current = onOpenChange;

  const setOpen = useCallback((v: boolean) => {
    if (openRef.current === v) return;
    setOpenState(v);
    onChange.current?.(v);
  }, []);
  const close = useCallback(() => setOpen(false), [setOpen]);

  const show = () => {
    const target = wrap.current?.firstElementChild as HTMLElement | null;
    if (!target) return;
    const r = target.getBoundingClientRect();
    setSize({ w: r.width, h: r.height, radius: getComputedStyle(target).borderRadius, rect: r });
    setLayout(null);
    setPressed(false);
    setOpen(true);
  };

  // Open: show the popover, then measure and place the preview over the content and the menu next to it.
  useIsoLayoutEffect(() => {
    const el = cm.current;
    if (!el) return;
    if (open && size && !layout) {
      if (!menuIsOpen(el)) el.showPopover();
      const r = size.rect;
      const vw = document.documentElement.clientWidth;
      const vh = window.innerHeight;
      const m = menuIsRegular(el) ? 20 : 16;
      const panel = el.querySelector<HTMLElement>('.ios-menu');
      const mw = panel ? panel.offsetWidth : 0;
      const mh = panel ? panel.offsetHeight : 0;
      const trailing = r.left + r.width / 2 > vw / 2;
      const next: ContextLayout = { left: r.left, top: r.top, above: false, horizontal: false, leading: false, trailing };
      if (r.bottom + 16 + mh <= vh - m) {
        next.left = trailing ? r.right - Math.max(size.w, mw) : r.left;
      } else if (r.top - 16 - mh >= m) {
        next.above = true;
        next.top = r.top - 16 - mh;
        next.left = trailing ? r.right - Math.max(size.w, mw) : r.left;
      } else if (menuIsRegular(el) && (r.right + 16 + mw <= vw - m || r.left - 16 - mw >= m)) {
        next.horizontal = true;
        next.trailing = false;
        next.leading = r.right + 16 + mw > vw - m;
        next.top = Math.min(r.top, vh - m - Math.max(size.h, mh));
        next.left = next.leading ? r.left - 16 - mw : r.left;
      } else {
        next.top = Math.max(m, vh - m - size.h - 16 - mh);
        if (next.top + size.h + 16 + mh > vh - m) next.maxHeight = vh - 2 * m - size.h - 16;
        next.left = trailing ? r.right - Math.max(size.w, mw) : r.left;
      }
      const cw = next.horizontal ? size.w + 16 + mw : Math.max(size.w, mw);
      next.left = menuClamp(next.left, Math.min(m, r.left), vw - Math.min(m, vw - r.right) - cw);
      next.top = menuClamp(next.top, Math.min(m, Math.max(0, r.top)), vh - m - (next.horizontal ? Math.max(size.h, mh) : size.h + 16 + mh));
      setLayout(next);
      (panel ?? el).focus({ preventScroll: true });
    } else if (!open && menuIsOpen(el)) el.hidePopover();
  }, [open, size, layout]);

  // Light dismiss (a manual popover, so the finger lifting after a long press doesn't close it): tap outside, Esc.
  useEffect(() => {
    if (!open) return;
    const down = (e: PointerEvent) => {
      const el = cm.current;
      if (el && e.target instanceof Node && !el.contains(e.target)) {
        e.preventDefault();
        suppress.current = true;
        window.setTimeout(() => (suppress.current = false), 800);
        close();
      }
    };
    const key = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && !cm.current?.querySelector('.ios-menu:popover-open')) close();
    };
    const click = (e: MouseEvent) => {
      if (suppress.current) {
        suppress.current = false;
        e.preventDefault();
        e.stopPropagation();
      }
    };
    document.addEventListener('pointerdown', down, true);
    document.addEventListener('keydown', key);
    document.addEventListener('click', click, true);
    return () => {
      document.removeEventListener('pointerdown', down, true);
      document.removeEventListener('keydown', key);
      document.removeEventListener('click', click, true);
    };
  }, [open, close]);

  const cancel = () => {
    window.clearTimeout(timer.current);
    timer.current = 0;
    start.current = null;
    setPressed(false);
  };
  useEffect(() => () => window.clearTimeout(timer.current), []);

  const firstChild = Children.toArray(children)[0];
  const lifted = preview ?? (isValidElement(firstChild) ? cloneElement(firstChild as ReactElement<{ style?: CSSProperties }>, { style: { ...(firstChild as ReactElement<{ style?: CSSProperties }>).props.style, width: size?.w, height: size?.h, margin: 0 } }) : firstChild);

  return (
    <>
      <div
        ref={wrap}
        className={cx('ios-context-menu__target', pressed && 'is-pressed')}
        onContextMenu={e => {
          e.preventDefault();
          cancel();
          show();
        }}
        onPointerDown={e => {
          if (e.button !== 0 || e.pointerType === 'mouse') return;
          start.current = { x: e.clientX, y: e.clientY };
          setPressed(true);
          timer.current = window.setTimeout(() => {
            timer.current = 0;
            suppress.current = true;
            window.setTimeout(() => (suppress.current = false), 800);
            show();
          }, 500);
        }}
        onPointerMove={e => {
          if (start.current && Math.hypot(e.clientX - start.current.x, e.clientY - start.current.y) > 8) cancel();
        }}
        onPointerUp={() => timer.current && cancel()}
        onPointerCancel={cancel}
        onClickCapture={e => {
          if (suppress.current) {
            suppress.current = false;
            e.preventDefault();
            e.stopPropagation();
          }
        }}
      >
        {children}
      </div>
      <div
        ref={cm}
        className={cx(
          'ios-context-menu',
          layout?.above && 'ios-context-menu--above',
          layout?.horizontal && 'ios-context-menu--horizontal',
          layout?.leading && 'ios-context-menu--leading',
          layout?.trailing && 'ios-context-menu--trailing',
        )}
        style={layout ? { left: layout.left, top: layout.top } : { visibility: open ? 'hidden' : undefined }}
        popover="manual"
        tabIndex={-1}
      >
        {open && size && (
          <div className="ios-context-menu__preview" style={{ width: size.w, height: size.h, borderRadius: size.radius !== '0px' ? size.radius : undefined }} onClick={close}>
            {lifted}
          </div>
        )}
        <div
          className="ios-menu"
          role="menu"
          aria-label={label}
          tabIndex={-1}
          style={layout?.maxHeight ? { maxHeight: layout.maxHeight, overflowY: 'auto' } : undefined}
          onKeyDown={e => menuKeyDown(e, close)}
        >
          <MenuScope.Provider value={{ close, variant: 'menu', inControls: false }}>{open && menu}</MenuScope.Provider>
        </div>
      </div>
    </>
  );
}

// ---------------------------------------------------------------------------------------------------------------
// PopUpButton and PullDownButton
// ---------------------------------------------------------------------------------------------------------------

export type PopUpOption<T extends string = string> = T | { value: T; label: string; icon?: IconName; disabled?: boolean };

export interface PopUpButtonProps<T extends string = string> {
  /** The choices (strings, or { value, label, icon }). */
  options: ReadonlyArray<PopUpOption<T>>;
  value?: T;
  defaultValue?: T;
  /** Receives the chosen value. */
  onChange?: (value: T) => void;
  /** What is being chosen ("Sort By"): the menu's name and part of the button's accessible name. */
  label?: string;
  disabled?: boolean;
  className?: string;
  style?: CSSProperties;
}

/**
 * Pop-up button: shows the current choice + chevron.up.chevron.down; tapping opens a menu of mutually exclusive choices.
 *
 *     <PopUpButton label="Sort By" options={['Name', 'Date', 'Size']} value={sort} onChange={setSort} />
 */
export function PopUpButton<T extends string = string>({ options, value, defaultValue, onChange, label, disabled, className, style }: PopUpButtonProps<T>) {
  const norm = options.map(o => (typeof o === 'string' ? { value: o as T, label: o as string, icon: undefined as IconName | undefined, disabled: false } : { icon: undefined, disabled: false, ...o }));
  const [current, setCurrent] = useControllable<T>(value, defaultValue ?? (norm[0]?.value as T), onChange);
  const chosen = norm.find(o => o.value === current) ?? norm[0];
  return (
    <Menu
      label={label}
      hasSelection
      trigger={
        <button
          type="button"
          className={cx('ios-popup-button', className)}
          style={style}
          disabled={disabled}
          aria-label={label ? `${label}, ${chosen?.label ?? ''}` : undefined}
        >
          <span className="ios-popup-button__label">{chosen?.label}</span>
        </button>
      }
    >
      {norm.map(o => (
        <MenuItem
          key={o.value}
          role="menuitemradio"
          label={o.label}
          icon={o.icon}
          value={o.value}
          disabled={o.disabled}
          checked={o.value === current}
          onSelect={() => setCurrent(o.value)}
        />
      ))}
    </Menu>
  );
}

export interface PullDownButtonProps {
  /** The fixed label: a verb or the name of the group of actions ("Add", "Sort"). */
  label: string;
  icon?: IconName;
  disabled?: boolean;
  className?: string;
  style?: CSSProperties;
  /** The actions: MenuItem, MenuSection, MenuDivider. */
  children?: ReactNode;
}

/**
 * Pull-down button: a fixed label + chevron.down; tapping opens a menu of ACTIONS related to the label.
 *
 *     <PullDownButton label="Add"><MenuItem icon="doc" label="New Document" onSelect={newDoc} /></PullDownButton>
 */
export function PullDownButton({ label, icon, disabled, className, style, children }: PullDownButtonProps) {
  return (
    <Menu
      label={label}
      trigger={
        <button type="button" className={cx('ios-pulldown-button', className)} style={style} disabled={disabled}>
          {icon && <Icon name={icon} />}
          <span className="ios-pulldown-button__label">{label}</span>
        </button>
      }
    >
      {children}
    </Menu>
  );
}
// ---------------------------------------------------------------------------------------------------
// notification.tsx
// ---------------------------------------------------------------------------------------------------

/** One action of an expanded notification (kit "Notification - Expanded" menu). */
export interface NotificationAction {
  label: string;
  icon?: IconName;
  /** Red label: the action deletes or removes something. */
  destructive?: boolean;
  onSelect?: () => void;
}

export interface NotificationProps extends Omit<HTMLAttributes<HTMLElement>, 'title'> {
  /** The app icon: an image URL or your own element (38 × 38, rounded by the CSS). */
  appIcon?: string | ReactNode;
  /** Bold first line: the app name or the sender. */
  title: ReactNode;
  /** The text (up to 4 lines). */
  message?: ReactNode;
  /** "9:41 AM", "now", "2m ago". */
  time?: ReactNode;
  /** Optional 32 × 32 thumbnail under the time (a photo in the message). */
  image?: string;
  /**
   * lock-screen (default): Regular material + label colours (follow Light/Dark), over a wallpaper or photo (Lock Screen,
   * Notification Center).
   * banner: over an app's content (in-app banner): Thick material + label colours, follows Light/Dark.
   */
  variant?: 'lock-screen' | 'banner';
  /** Notifications grouped in this stack: 2 or 3 (= 3 or more) draw the cards peeking out below. */
  stack?: 1 | 2 | 3;
  /** The long-press view: header card + your content (children) + actions menu below. */
  expanded?: boolean;
  /** Actions of the expanded view (2–4, verbs: "Reply", "Mark as Read"). */
  actions?: NotificationAction[];
  /** Expanded view only: the custom content under the header. */
  children?: ReactNode;
  /** Makes the notification a button (opens the related content). */
  onClick?: () => void;
}

function NotificationAppIcon({ icon }: { icon: NotificationProps['appIcon'] }) {
  if (typeof icon === 'string') return <img className="ios-notification__icon" src={icon} alt="" />;
  if (icon != null) return <span className="ios-notification__icon">{icon}</span>;
  return <span className="ios-notification__icon" />;
}

function NotificationParts({ appIcon, title, message, time, image }: Pick<NotificationProps, 'appIcon' | 'title' | 'message' | 'time' | 'image'>) {
  return (
    <>
      <NotificationAppIcon icon={appIcon} />
      <div className="ios-notification__content">
        <div className="ios-notification__headline">
          <p className="ios-notification__title">{title}</p>
          {time != null && <time className="ios-notification__time">{time}</time>}
        </div>
        {image && <img className="ios-notification__image" src={image} alt="" />}
        {message != null && <p className="ios-notification__message">{message}</p>}
      </div>
    </>
  );
}

/**
 * An iOS notification (kit page "Notifications"). Static: shows one notification wherever you put it.
 * For a banner that slides in over your app use <NotificationBanner>; for a list use <NotificationList>.
 */
export function Notification({
  appIcon, title, message, time, image, variant = 'lock-screen', stack = 1, expanded, actions, children, onClick, className, ...rest
}: NotificationProps) {
  if (expanded) {
    return (
      <div className={cx('ios-notification ios-notification--expanded', className)} {...rest}>
        <div className="ios-notification__card">
          <div className="ios-notification__header">
            <NotificationParts appIcon={appIcon} title={title} message={message} time={time} image={image} />
          </div>
          {children != null && <div className="ios-notification__body">{children}</div>}
        </div>
        {actions && actions.length > 0 && (
          <div className="ios-notification__actions" role="menu">
            {actions.map(a => (
              <button
                key={a.label}
                type="button"
                role="menuitem"
                className={cx('ios-notification__action', a.destructive && 'ios-notification__action--destructive')}
                onClick={a.onSelect}
              >
                {a.icon && <Icon name={a.icon} />}
                {a.label}
              </button>
            ))}
          </div>
        )}
      </div>
    );
  }
  const cls = cx(
    'ios-notification',
    variant === 'banner' && 'ios-notification--banner',
    stack > 1 && `ios-notification--stack-${stack}`,
    className,
  );
  if (onClick) {
    return (
      <button type="button" className={cls} onClick={onClick} {...rest}>
        <NotificationParts appIcon={appIcon} title={title} message={message} time={time} image={image} />
      </button>
    );
  }
  return (
    <div className={cls} {...rest}>
      <NotificationParts appIcon={appIcon} title={title} message={message} time={time} image={image} />
    </div>
  );
}

export interface NotificationListProps extends HTMLAttributes<HTMLUListElement> {
  /** <Notification> elements, newest first. */
  children?: ReactNode;
}

/** Notifications 8 apart with 14 px side padding (Lock Screen / Notification Center, kit "Notification - Collapsed - List"). */
export function NotificationList({ className, children, ...rest }: NotificationListProps) {
  const items = Array.isArray(children) ? children : [children];
  return (
    <ul className={cx('ios-notification-list', className)} {...rest}>
      {items.filter(c => c != null && c !== false).map((c, i) => (
        <li key={i}>{c}</li>
      ))}
    </ul>
  );
}

export interface NotificationBannerProps extends Omit<NotificationProps, 'variant' | 'expanded' | 'actions' | 'stack'> {
  /** Shown (slides down from the top) or hidden. */
  open: boolean;
  /** Called when the banner hides itself (after `duration`, or when swiped up). */
  onClose: () => void;
  /** Milliseconds before it hides itself; 0 = stays until `open` is false. Default 4000. */
  duration?: number;
}

/**
 * An in-app notification banner: Thick material, fixed at the top of the screen, slides down, hides after 4 s or when
 * swiped up. Tap = onClick (open the related content). Announced politely to VoiceOver.
 *
 *     const [open, setOpen] = useState(false);
 *     <NotificationBanner open={open} onClose={() => setOpen(false)} appIcon="/icon.png" title="Anna" message="Lunch?" time="now" />
 */
export function NotificationBanner({ open, onClose, duration = 4000, className, ...notification }: NotificationBannerProps) {
  const host = useRef<HTMLDivElement>(null);
  const drag = useRef<{ y: number; dy: number } | null>(null);
  // Keep the content while it slides out; insert it when opening (so VoiceOver announces it).
  const [mounted, setMounted] = useState(open);
  useEffect(() => {
    if (open) {
      setMounted(true);
      return;
    }
    const t = window.setTimeout(() => setMounted(false), 450);
    return () => window.clearTimeout(t);
  }, [open]);

  useEffect(() => {
    if (!open || duration <= 0) return;
    const t = window.setTimeout(onClose, duration);
    return () => window.clearTimeout(t);
  }, [open, duration, onClose]);

  const move = (dy: number) => {
    if (host.current) host.current.style.transform = dy < -4 ? `translateY(${dy}px)` : '';
  };

  return (
    <div
      ref={host}
      className={cx('ios-notification-host', className)}
      data-state={open ? 'open' : 'closed'}
      role="status"
      aria-live="polite"
      onPointerDown={e => {
        drag.current = { y: e.clientY, dy: 0 };
        e.currentTarget.setPointerCapture(e.pointerId);
      }}
      onPointerMove={e => {
        if (!drag.current) return;
        drag.current.dy = Math.min(0, e.clientY - drag.current.y);
        move(drag.current.dy);
      }}
      onPointerUp={() => {
        const d = drag.current;
        drag.current = null;
        move(0);
        if (d && d.dy < -24) onClose();
      }}
      onPointerCancel={() => {
        drag.current = null;
        move(0);
      }}
    >
      {(open || mounted) && <Notification variant="banner" {...notification} />}
    </div>
  );
}
// ---------------------------------------------------------------------------------------------------
// page-control.tsx
// ---------------------------------------------------------------------------------------------------

export interface PageControlProps extends Omit<HTMLAttributes<HTMLElement>, 'onChange' | 'defaultValue' | 'children'> {
  /** Number of pages. */
  count: number;
  /** Current page, 0-based (controlled). Use with onChange. */
  value?: number;
  /** Start page when uncontrolled. Default 0. */
  defaultValue?: number;
  /** Receives the new page index (0-based), not an event. */
  onChange?: (page: number) => void;
  /** Accessible name of the control. Default "Pages". */
  label?: string;
  /** Accessible name of one dot. Default: "Page 3 of 8". */
  pageLabel?: (page: number, count: number) => string;
}

type PageDotKind = 'dot' | 'adjacent' | 'overflow' | 'hidden';

/** Which dots are visible and how big (kit Page Control 1-6 · 7 · 8+). Exported for tests. */
export function pageControlDots(count: number, current: number): PageDotKind[] {
  if (count <= 6) return Array.from({ length: count }, () => 'dot');
  let start = Math.min(Math.max(current - 2, 0), count - 5);
  let end = start + 4;
  if (start === 0) end = 5;
  else if (end === count - 1) start = count - 6;
  return Array.from({ length: count }, (_, i) => {
    if (i >= start && i <= end) return 'dot';
    if (i === start - 1 || i === end + 1) return 'adjacent';
    if (i === start - 2 || i === end + 2) return 'overflow';
    return 'hidden';
  });
}

/**
 * An iOS page control (kit "Page Control"): dots for the pages of a paged view, the current one dark.
 * 7+ pages: the dots at the edges shrink. Tap a dot or use the arrow keys to change pages.
 * <PageControl count={5} value={page} onChange={setPage} />
 */
export function PageControl({ count, value, defaultValue = 0, onChange, label = 'Pages', pageLabel, className, ...rest }: PageControlProps) {
  const [current, setCurrent] = useControllable(value, defaultValue, onChange);
  const nav = useRef<HTMLElement>(null);
  const page = Math.min(Math.max(current, 0), Math.max(count - 1, 0));
  const kinds = pageControlDots(count, page);
  const go = (next: number) => {
    const p = Math.min(Math.max(next, 0), count - 1);
    if (p === page) return;
    setCurrent(p);
    requestAnimationFrame(() => nav.current?.querySelector<HTMLButtonElement>('[aria-current="page"]')?.focus());
  };
  const onKeyDown = (e: ReactKeyboardEvent<HTMLElement>) => {
    const dir = document.documentElement.dir === 'rtl' ? -1 : 1;
    if (e.key === 'ArrowRight') go(page + dir);
    else if (e.key === 'ArrowLeft') go(page - dir);
    else if (e.key === 'Home') go(0);
    else if (e.key === 'End') go(count - 1);
    else return;
    e.preventDefault();
  };
  return (
    <nav ref={nav} className={cx('ios-page-control', className)} aria-label={label} onKeyDown={onKeyDown} {...rest}>
      {kinds.map((kind, i) =>
        kind === 'hidden' ? null : (
          <button
            key={i}
            type="button"
            className={cx(
              'ios-page-control__dot',
              kind === 'adjacent' && 'ios-page-control__dot--adjacent',
              kind === 'overflow' && 'ios-page-control__dot--overflow',
            )}
            aria-label={pageLabel ? pageLabel(i, count) : `Page ${i + 1} of ${count}`}
            aria-current={i === page ? 'page' : undefined}
            tabIndex={i === page ? 0 : -1}
            onClick={() => go(i)}
          />
        ),
      )}
    </nav>
  );
}
// ---------------------------------------------------------------------------------------------------
// popover.tsx
// ---------------------------------------------------------------------------------------------------

export type PopoverEdge = 'auto' | 'top' | 'bottom' | 'leading' | 'trailing';

const POPOVER_ARROW = 13;                                // kit arrow height
const POPOVER_GAP = 4;                                   // arrow tip → anchor
const POPOVER_CORNER = 72;                               // kit: the arrow centre sits 44 + 28 from a corner
const POPOVER_MIN_ARROW = 56;                            // …or 28 + 28 for an anchor at the screen edge
const popoverClamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(v, Math.max(lo, hi)));

/** Places an open popover next to an anchor rect with its arrow pointing at it. Returns the arrow edge used. */
function popoverPlace(pop: HTMLElement, r: DOMRect, prefer: PopoverEdge): Exclude<PopoverEdge, 'auto'> {
  const vw = document.documentElement.clientWidth;
  const vh = window.innerHeight;
  const m = 20;
  const w = pop.offsetWidth;                             // layout size: the opening animation scales the popover
  const h = pop.offsetHeight;
  const out = POPOVER_ARROW + POPOVER_GAP;
  const fits = {
    top: r.bottom + out + h <= vh - m,
    bottom: r.top - out - h >= m,
    leading: r.right + out + w <= vw - m,
    trailing: r.left - out - w >= m,
  };
  const order = ['top', 'bottom', 'leading', 'trailing'] as const;
  const side = prefer !== 'auto' && fits[prefer] ? prefer : (order.find(s => fits[s]) ?? 'top');
  let left: number;
  let top: number;
  let arrow: number;
  if (side === 'top' || side === 'bottom') {
    const cx = r.left + r.width / 2;
    left = popoverClamp(cx - w / 2, m, vw - m - w);
    if (cx - left < POPOVER_CORNER) left = Math.max(4, cx - POPOVER_CORNER);
    else if (left + w - cx < POPOVER_CORNER) left = Math.min(vw - 4 - w, cx + POPOVER_CORNER - w);
    top = side === 'top' ? r.bottom + out : r.top - out - h;
    arrow = popoverClamp(cx - left, Math.min(POPOVER_MIN_ARROW, w / 2), Math.max(w - POPOVER_MIN_ARROW, w / 2));
    pop.style.setProperty('--ios-popover-origin', `${arrow}px ${side === 'top' ? '0' : '100%'}`);
  } else {
    const cy = r.top + r.height / 2;
    top = popoverClamp(cy - h / 2, m, vh - m - h);
    if (cy - top < POPOVER_CORNER) top = Math.max(4, cy - POPOVER_CORNER);
    else if (top + h - cy < POPOVER_CORNER) top = Math.min(vh - 4 - h, cy + POPOVER_CORNER - h);
    left = side === 'leading' ? r.right + out : r.left - out - w;
    arrow = popoverClamp(cy - top, Math.min(POPOVER_MIN_ARROW, h / 2), Math.max(h - POPOVER_MIN_ARROW, h / 2));
    pop.style.setProperty('--ios-popover-origin', `${side === 'leading' ? '0' : '100%'} ${arrow}px`);
  }
  pop.style.inset = 'auto';
  pop.style.margin = '0';
  pop.style.left = `${Math.round(left)}px`;
  pop.style.top = `${Math.round(top)}px`;
  pop.style.setProperty('--ios-popover-arrow', `${Math.round(arrow)}px`);
  return side;
}

export interface PopoverProps {
  /** The control that opens the popover when clicked (a Button, a bar button…). The arrow points at it. */
  trigger: ReactElement<{ onClick?: (e: ReactMouseEvent<HTMLElement>) => void; onPointerDown?: (e: ReactPointerEvent<HTMLElement>) => void }>;
  /** Accessible name (or put a heading inside and pass its text). */
  label?: string;
  /**
   * The ARROW edge on iPad: auto (default: below the trigger if it fits, then above, then beside) · top (popover
   * below) · bottom (popover above) · leading (popover on the trailing side) · trailing (popover on the leading side).
   */
  edge?: PopoverEdge;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Style of the content box (give it a width: popovers are as wide as their content, 320 is typical). */
  className?: string;
  style?: CSSProperties;
  /** The content. Call the close function from a "Done" button with the render-prop form: {close => …}. */
  children?: ReactNode | ((close: () => void) => ReactNode);
}

/**
 * iPad: a Thick-material panel with an arrow pointing at its trigger (a tap outside or Esc closes it).
 * iPhone (compact width): the same content opens as a sheet from the bottom — iOS has no popovers on iPhone.
 *
 *     <Popover label="Filters" trigger={<Button>Filters</Button>} style={{ width: 320 }}>
 *       {close => <FiltersForm onDone={close} />}
 *     </Popover>
 */
export function Popover({
  trigger,
  label,
  edge = 'auto',
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  className,
  style,
  children,
}: PopoverProps) {
  const id = useId();
  const [open, setOpen] = useControllable(openProp, defaultOpen, onOpenChange);
  const [side, setSide] = useState<Exclude<PopoverEdge, 'auto'>>('top');
  const [sheet, setSheet] = useState(false);
  const pop = useRef<HTMLDivElement>(null);
  const triggerEl = useRef<HTMLElement | null>(null);
  const openRef = useRef(open);
  openRef.current = open;
  const wasOpenAtPointerDown = useRef(false);
  const keyboardOpen = useRef(false);
  const close = () => {
    if (openRef.current) setOpen(false);
  };

  useIsoLayoutEffect(() => {
    const el = pop.current;
    if (!el) return;
    if (open && !el.matches(':popover-open')) {
      // Opened from code (open / defaultOpen) before any click: find the trigger by aria-controls.
      triggerEl.current ??= document.querySelector<HTMLElement>(`[aria-controls="${CSS.escape(id)}"]`);
      const asSheet = !menuIsRegular(triggerEl.current ?? el);
      el.classList.toggle('ios-popover--sheet', asSheet);
      el.showPopover();
      if (!asSheet && triggerEl.current) {
        const s = popoverPlace(el, triggerEl.current.getBoundingClientRect(), edge);
        el.classList.remove('ios-popover--top', 'ios-popover--bottom', 'ios-popover--leading', 'ios-popover--trailing');
        el.classList.add(`ios-popover--${s}`);
        setSide(s);
      } else {
        el.style.inset = el.style.margin = el.style.left = el.style.top = '';
      }
      setSheet(asSheet);
      // Keyboard: focus the first control inside; pointer: focus the panel itself (no ring).
      const first = keyboardOpen.current ? el.querySelector<HTMLElement>('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])') : null;
      (first ?? el).focus({ preventScroll: true });
    } else if (!open && el.matches(':popover-open')) el.hidePopover();
  }, [open, edge, id]);

  useMenuToggle(pop, () => {
    const el = pop.current;
    const active = document.activeElement;
    if (triggerEl.current && (!active || active === document.body || (el && el.contains(active)))) triggerEl.current.focus({ preventScroll: true });
    if (openRef.current) setOpen(false);
  });

  const tp = trigger.props;
  const t = cloneElement(trigger as ReactElement<Record<string, unknown>>, {
    'aria-haspopup': 'dialog',
    'aria-expanded': open,
    'aria-controls': id,
    onPointerDown: (e: ReactPointerEvent<HTMLElement>) => {
      wasOpenAtPointerDown.current = !!pop.current && pop.current.matches(':popover-open');
      tp.onPointerDown?.(e);
    },
    onClick: (e: ReactMouseEvent<HTMLElement>) => {
      tp.onClick?.(e);
      if (e.defaultPrevented) return;
      triggerEl.current = e.currentTarget;
      if (wasOpenAtPointerDown.current || open) {
        wasOpenAtPointerDown.current = false;
        setOpen(false);
        return;
      }
      keyboardOpen.current = e.detail === 0;
      setOpen(true);
    },
  });
  return (
    <>
      {t}
      <div
        ref={pop}
        id={id}
        className={cx('ios-popover', !sheet && `ios-popover--${side}`, sheet && 'ios-popover--sheet')}
        popover="auto"
        role="dialog"
        aria-label={label}
        tabIndex={-1}
      >
        <div className={cx('ios-popover__content', className)} style={style}>
          {open && (typeof children === 'function' ? children(close) : children)}
        </div>
      </div>
    </>
  );
}
// ---------------------------------------------------------------------------------------------------
// progress.tsx
// ---------------------------------------------------------------------------------------------------

export interface ProgressBarProps extends Omit<ProgressHTMLAttributes<HTMLProgressElement>, 'value' | 'max' | 'children'> {
  /** Done so far, 0…max. Omit it for "not started yet" (an empty track). Unknown duration: use Spinner. */
  value?: number;
  /** Default 1 (value is a fraction, like SwiftUI ProgressView). */
  max?: number;
  /** Visible text above the bar (kit "Show Label"), e.g. "Downloading 3 of 8…". Also its accessible name. */
  label?: ReactNode;
}

/**
 * An iOS progress bar (kit "Progress Bar - Determinate Linear"): 4 pt accent bar on a Fills/Primary track.
 * <ProgressBar value={0.4} aria-label="Downloading" />    <ProgressBar value={done} max={total} label="Importing Photos…" />
 */
export function ProgressBar({ value, max = 1, label, className, ...rest }: ProgressBarProps) {
  const bar = <progress className={cx('ios-progress', !label && className)} value={value} max={max} {...rest} />;
  if (label == null) return bar;
  return (
    <label className={cx('ios-progress__label', className)}>
      {label}
      {bar}
    </label>
  );
}

export type SpinnerSize = 'small' | 'regular' | 'large';

export interface SpinnerProps extends Omit<HTMLAttributes<HTMLSpanElement>, 'children'> {
  /** small (14) · regular (20, default) · large (35). */
  size?: SpinnerSize;
  /** Visible text next to the spinner (kit "Show Label"), e.g. "Loading…". */
  label?: ReactNode;
}

/**
 * The iOS activity indicator (kit "Progress Bar - Indeterminate Circular (Spinner)"): 8 spokes turning clockwise.
 * <Spinner />   <Spinner size="large" />   <Spinner label="Loading…" />
 */
export function Spinner({ size = 'regular', label, className, ...rest }: SpinnerProps) {
  return (
    <span
      className={cx('ios-spinner', size !== 'regular' && `ios-spinner--${size}`, className)}
      role="progressbar"
      aria-label={typeof label === 'string' ? label : 'Loading'}
      {...rest}
    >
      {label}
    </span>
  );
}

export type GaugeVariant = 'circular' | 'capacity';

export interface GaugeProps extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> {
  /** The current value, min…max. */
  value: number;
  /** Default 0. */
  min?: number;
  /** Default 1. */
  max?: number;
  /** circular (default: 270° ring, open at the bottom, a dot marks the value) · capacity (full ring that fills up). */
  variant?: GaugeVariant;
  /** Text in the middle. Default: the value as a percentage ("50%"). */
  currentValueLabel?: ReactNode;
  /** Small text in the opening at the bottom (circular), e.g. "CPU". Also the accessible name when it is a string. */
  label?: ReactNode;
  /** Small texts at the two ends of the ring (circular), e.g. 0 and 100. Use instead of label. */
  minimumValueLabel?: ReactNode;
  maximumValueLabel?: ReactNode;
  /** Ring colour. Default: the accent colour. */
  tint?: string;
  /** Colour behind the gauge (cuts the gap around the dot). Default: the page background. */
  surface?: string;
}

/**
 * An iOS gauge (SwiftUI Gauge with .accessoryCircular / .accessoryCircularCapacity; kit Lock Screen gauges): 58 pt.
 * For a level in a range (battery, speed, air quality), not for progress over time (use ProgressBar).
 * <Gauge value={0.72} label="CPU" />   <Gauge variant="capacity" value={0.4} currentValueLabel="40%" />
 */
export function Gauge({
  value,
  min = 0,
  max = 1,
  variant = 'circular',
  currentValueLabel,
  label,
  minimumValueLabel,
  maximumValueLabel,
  tint,
  surface,
  className,
  style,
  ...rest
}: GaugeProps) {
  const fraction = max > min ? Math.min(1, Math.max(0, (value - min) / (max - min))) : 0;
  const capacity = variant === 'capacity';
  return (
    <div
      className={cx('ios-gauge', capacity && 'ios-gauge--capacity', className)}
      role="meter"
      aria-valuemin={min}
      aria-valuemax={max}
      aria-valuenow={value}
      aria-label={typeof label === 'string' ? label : undefined}
      style={vars(style, { '--ios-gauge-value': fraction, '--ios-gauge-tint': tint, '--ios-gauge-surface': surface })}
      {...rest}
    >
      <svg className="ios-gauge__ring" viewBox="0 0 58 58" aria-hidden="true">
        <circle className="ios-gauge__track" cx="29" cy="29" r="26" pathLength={100} />
        {capacity ? (
          <circle className="ios-gauge__fill" cx="29" cy="29" r="26" pathLength={100} />
        ) : (
          <>
            <circle className="ios-gauge__cutout" cx="29" cy="29" r="26" pathLength={100} />
            <circle className="ios-gauge__indicator" cx="29" cy="29" r="26" pathLength={100} />
          </>
        )}
      </svg>
      <span className="ios-gauge__value">{currentValueLabel ?? `${Math.round(fraction * 100)}%`}</span>
      {label != null && !capacity && <span className="ios-gauge__label">{label}</span>}
      {minimumValueLabel != null && !capacity && <span className="ios-gauge__min">{minimumValueLabel}</span>}
      {maximumValueLabel != null && !capacity && <span className="ios-gauge__max">{maximumValueLabel}</span>}
    </div>
  );
}
// ---------------------------------------------------------------------------------------------------
// segmented-control.tsx
// ---------------------------------------------------------------------------------------------------

export interface SegmentedOption<T extends string = string> {
  value: T;
  /** Visible text. Default: the value. */
  label?: ReactNode;
  /** A symbol instead of (or before) the text. Icon-only segments need ariaLabel. */
  icon?: IconName;
  /** Accessible name for an icon-only segment. */
  ariaLabel?: string;
  disabled?: boolean;
}

export interface SegmentedControlProps<T extends string = string>
  extends Omit<HTMLAttributes<HTMLDivElement>, 'onChange' | 'defaultValue' | 'children'> {
  /** The segments: strings (value = label) or option objects. 2–5 segments on iPhone. */
  options: readonly (T | SegmentedOption<T>)[];
  /** Selected value (controlled). Use with onChange. */
  value?: T;
  /** Start value when uncontrolled. Default: the first option. */
  defaultValue?: T;
  /** Receives the newly selected value, not an event. */
  onChange?: (value: T) => void;
  /** small (32 tall, default) · large (50 tall). */
  size?: 'small' | 'large';
  disabled?: boolean;
  /** Form field name (and the radio group name). Default: a generated one. */
  name?: string;
  /** Accessible name of the control, e.g. "View". */
  label?: string;
}

/**
 * An iOS segmented control (kit "Segmented Control"): equal segments in a grey capsule, the selected one on a white pill.
 * Radio buttons inside: arrow keys move the selection, forms get the value.
 * <SegmentedControl label="View" options={['Day', 'Week', 'Month']} value={view} onChange={setView} />
 */
export function SegmentedControl<T extends string = string>({
  options,
  value,
  defaultValue,
  onChange,
  size = 'small',
  disabled,
  name,
  label,
  className,
  ...rest
}: SegmentedControlProps<T>) {
  const items: SegmentedOption<T>[] = options.map(o => (typeof o === 'string' ? { value: o as T } : (o as SegmentedOption<T>)));
  const [selected, setSelected] = useControllable<T>(value, (defaultValue ?? items[0]?.value) as T, onChange);
  const autoName = useId();
  const groupName = name ?? autoName;
  return (
    <div
      className={cx('ios-segmented', size === 'large' && 'ios-segmented--large', className)}
      role="radiogroup"
      aria-label={label}
      aria-disabled={disabled || undefined}
      {...rest}
    >
      {items.map(item => (
        <label key={item.value} className="ios-segmented__option">
          <input
            type="radio"
            name={groupName}
            value={item.value}
            checked={selected === item.value}
            disabled={disabled || item.disabled}
            onChange={() => setSelected(item.value)}
            aria-label={item.ariaLabel}
          />
          {item.icon && <Icon name={item.icon} />}
          {item.label ?? (item.icon ? null : item.value)}
        </label>
      ))}
    </div>
  );
}
// ---------------------------------------------------------------------------------------------------
// sheet.tsx
// ---------------------------------------------------------------------------------------------------

/** medium = a floating Thick-material card, about half the screen (iPhone). large = from the status bar down. */
export type SheetDetent = 'medium' | 'large';

export interface SheetProps extends Omit<DialogHTMLAttributes<HTMLDialogElement>, 'open' | 'title' | 'onChange'> {
  /** Shown or not. Drive it with state: open={open} onOpenChange={setOpen}. */
  open: boolean;
  /** Called with false when the user dismisses the sheet (swipe down, Esc, tap on the dimmed page, a close button). */
  onOpenChange: (open: boolean) => void;
  /** Title in the sheet's toolbar (Semibold 17 on iPhone, 15 on iPad). */
  title?: ReactNode;
  /** iPad two-line toolbar title: a subtitle under the title. */
  subtitle?: ReactNode;
  /** Toolbar, left: usually <Button variant="glass" icon="xmark" label="Cancel" />. */
  leading?: ReactNode;
  /** Toolbar, right: usually <Button variant="glass-prominent" icon="checkmark" label="Done" />. */
  trailing?: ReactNode;
  /** Detents the user can drag between (iPhone). Default ['large']. iPad ignores detents (a centred card). */
  detents?: SheetDetent[];
  /** Current detent (controlled) … */
  detent?: SheetDetent;
  /** … or the detent it opens at (default: the first of detents). */
  defaultDetent?: SheetDetent;
  onDetentChange?: (detent: SheetDetent) => void;
  /** false = no swipe down, no Esc, no tap outside (SwiftUI .interactiveDismissDisabled()). Default true. */
  dismissible?: boolean;
  /** Full-screen cover: the whole screen, no grabber, can't be swiped away. */
  fullScreen?: boolean;
  /** No dimming: the page behind stays usable (kit "Inspector" example). */
  inspector?: boolean;
  /** Show the grabber. Default: true (not for full-screen covers). */
  grabber?: boolean;
  /** iPad, popover-style sheets (ActivityView): placed next to this element. */
  anchorRef?: RefObject<HTMLElement | null>;
  children?: ReactNode;
}

// Open sheets, bottom to top: a sheet opened over a large sheet sits 10 px lower, the one under it steps back.
type SheetEntry = { id: number; detent: SheetDetent; stacked: boolean };
let sheetStack: SheetEntry[] = [];
const sheetListeners = new Set<() => void>();
let sheetCounter = 0;
const sheetStore = {
  subscribe(listener: () => void) {
    sheetListeners.add(listener);
    return () => {
      sheetListeners.delete(listener);
    };
  },
  get: () => sheetStack,
  set(next: SheetEntry[]) {
    sheetStack = next;
    sheetListeners.forEach(l => l());
  },
};

const INTERACTIVE = 'button, a, input, select, textarea, [role="button"]';
const cssPx = (el: Element, name: string) => parseFloat(getComputedStyle(el).getPropertyValue(name)) || 0;

/**
 * An iOS sheet (kit page "Sheets"). iPhone: medium (floating material card) and large detents with a grabber, drag to
 * resize or dismiss. iPad: a centred card. Put the actions in the sheet's own toolbar (leading / trailing).
 *
 *     <Sheet open={open} onOpenChange={setOpen} title="New Event" detents={['medium', 'large']}
 *            leading={<Button variant="glass" icon="xmark" label="Cancel" onClick={() => setOpen(false)} />}
 *            trailing={<Button variant="glass-prominent" icon="checkmark" label="Add" onClick={save} />}>
 *       …form…
 *     </Sheet>
 */
export function Sheet({
  open,
  onOpenChange,
  title,
  subtitle,
  leading,
  trailing,
  detents = ['large'],
  detent: detentProp,
  defaultDetent,
  onDetentChange,
  dismissible = true,
  fullScreen = false,
  inspector = false,
  grabber,
  anchorRef,
  className,
  children,
  onCancel,
  onClose,
  onClick,
  ...rest
}: SheetProps) {
  const ref = useRef<HTMLDialogElement>(null);
  const titleId = useId();
  const sizeClass = useSizeClass();
  const regular = sizeClass === 'regular';
  const [detent, setDetent] = useControllable<SheetDetent>(detentProp, defaultDetent ?? detents[0] ?? 'large', onDetentChange);
  const canDismiss = dismissible && !fullScreen;
  const showGrabber = grabber ?? !fullScreen;
  const idRef = useRef(0);
  if (idRef.current === 0) idRef.current = ++sheetCounter;
  const id = idRef.current;
  const stack = useSyncExternalStore(sheetStore.subscribe, sheetStore.get, sheetStore.get);
  const index = stack.findIndex(e => e.id === id);
  const stacked = index >= 0 && stack[index].stacked;
  const behind = index >= 0 && index < stack.length - 1 && stack[index + 1].stacked;
  const openRef = useRef(open);
  openRef.current = open;

  // Open / close the native <dialog> (top layer, ::backdrop dimming, focus trap, Esc). While open, the sheet is in
  // the stack (the effect's cleanup takes it out again: when it closes, and on unmount). A layout effect, so the
  // dialog is open (and measurable) before the anchor placement below runs.
  useLayoutEffect(() => {
    const el = ref.current;
    if (!el || !open) return;
    const below = sheetStore.get()[sheetStore.get().length - 1];
    sheetStore.set([...sheetStore.get(), { id, detent, stacked: !!below && (below.detent === 'large' || regular) }]);
    if (!el.open) {
      if (inspector) el.show();
      else el.showModal();
      if (!el.querySelector('[autofocus]')) el.focus({ preventScroll: true });
    }
    return () => sheetStore.set(sheetStore.get().filter(e => e.id !== id));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);
  useEffect(() => {
    const el = ref.current;
    if (!open && el?.open) el.close();
  }, [open]);
  useEffect(() => {
    if (!open) return;
    sheetStore.set(sheetStore.get().map(e => (e.id === id ? { ...e, detent } : e)));
  }, [detent, open, id]);

  // iPad: popover-style sheets (activity views) sit next to their button.
  useLayoutEffect(() => {
    const el = ref.current;
    const anchor = anchorRef?.current;
    if (!el || !open) return;
    el.style.removeProperty('left');
    el.style.removeProperty('top');
    el.style.removeProperty('right');
    if (!anchor || !regular) return;
    const s = anchor.getBoundingClientRect();
    const w = el.offsetWidth;
    const h = el.offsetHeight;
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v));
    const left = clamp(s.left + s.width / 2 > vw / 2 ? s.right - w : s.left, 8, vw - w - 8);
    const top = s.bottom + 6 + h <= vh - 8 ? s.bottom + 6 : clamp(s.top - 6 - h, 8, vh - h - 8);
    el.style.left = `${left}px`;
    el.style.top = `${top}px`;
    el.style.right = 'auto';
  }, [open, regular, anchorRef]);

  // FLIP: after a detent change from a drag, slide from where the finger left the sheet.
  const flipFrom = useRef<number | null>(null);
  useLayoutEffect(() => {
    const el = ref.current;
    const from = flipFrom.current;
    flipFrom.current = null;
    if (!el || from === null) return;
    const to = el.getBoundingClientRect().top;
    if (Math.abs(from - to) > 1 && !matchMedia('(prefers-reduced-motion: reduce)').matches) {
      el.style.translate = `0 ${from - to}px`;
      void el.offsetHeight;
    }
    el.style.removeProperty('transition');
    el.style.removeProperty('translate');
  }, [detent]);

  // Drag the grabber or the toolbar: resize between detents, or down to dismiss.
  const drag = useRef<{ pointer: number; y0: number; top0: number; moved: boolean; last: { y: number; t: number }[] } | null>(null);
  const dragged = useRef(false);
  const clearInline = (el: HTMLElement) => {
    el.style.removeProperty('top');
    el.style.removeProperty('height');
    el.style.removeProperty('translate');
  };
  const onDragStart = (e: ReactPointerEvent<HTMLElement>) => {
    const el = ref.current;
    if (!el || e.button !== 0 || fullScreen) return;
    if (e.currentTarget.classList.contains('ios-sheet__toolbar') && (e.target as Element).closest(INTERACTIVE)) return;
    e.currentTarget.setPointerCapture(e.pointerId);
    drag.current = { pointer: e.pointerId, y0: e.clientY, top0: el.getBoundingClientRect().top, moved: false, last: [{ y: e.clientY, t: e.timeStamp }] };
    dragged.current = false;
  };
  const onDragMove = (e: ReactPointerEvent<HTMLElement>) => {
    const d = drag.current;
    const el = ref.current;
    if (!d || !el || e.pointerId !== d.pointer) return;
    const dy = e.clientY - d.y0;
    if (!d.moved) {
      if (Math.abs(dy) < 4) return;
      d.moved = true;
      el.classList.add('is-dragging');
    }
    d.last.push({ y: e.clientY, t: e.timeStamp });
    if (d.last.length > 5) d.last.shift();
    const minTop = !regular && detents.includes('large') ? cssPx(el, '--ios-sheet-top-inset') : d.top0;
    let top = d.top0 + dy;
    if (top < minTop) top = minTop - Math.sqrt(minTop - top) * 2; // rubber band
    if (!canDismiss && top > d.top0) top = d.top0 + Math.sqrt(top - d.top0) * 2;
    if (top >= d.top0 || regular) {
      el.style.removeProperty('top');
      el.style.removeProperty('height');
      el.style.translate = `0 ${Math.max(top - d.top0, 0)}px`;
    } else {
      el.style.translate = '0 0';
      el.style.top = `${top}px`;
      el.style.height = 'auto';
    }
  };
  const onDragEnd = (e: ReactPointerEvent<HTMLElement>) => {
    const d = drag.current;
    const el = ref.current;
    if (!d || !el || e.pointerId !== d.pointer) return;
    drag.current = null;
    if (!d.moved) return;
    dragged.current = true;
    const r = el.getBoundingClientRect();
    const a = d.last[0];
    const b = d.last[d.last.length - 1];
    const v = b.t > a.t ? (b.y - a.y) / (b.t - a.t) : 0;
    const projected = r.top + v * 220;
    const H = window.innerHeight;
    const candidates: { top: number; detent: SheetDetent | null }[] = [];
    if (regular) candidates.push({ top: r.top - parseFloat(el.style.translate.split(' ')[1] || '0'), detent });
    else
      for (const dt of detents)
        candidates.push({
          top: dt === 'large' ? cssPx(el, '--ios-sheet-top-inset') : H * (1 - cssPx(el, '--ios-sheet-medium-height') / 100) - cssPx(el, '--ios-sheet-inset'),
          detent: dt,
        });
    if (canDismiss) candidates.push({ top: H, detent: null });
    candidates.sort((p, q) => Math.abs(p.top - projected) - Math.abs(q.top - projected));
    const target = candidates[0] ?? { top: r.top, detent };
    el.classList.remove('is-dragging');
    if (target.detent === null) {
      // Close in this same frame, so the slide-out starts where the finger left the sheet (onClose tells the parent).
      clearInline(el);
      el.close();
      return;
    }
    if (target.detent === detent) {
      const before = r.top;
      el.style.transition = 'none';
      clearInline(el);
      const after = el.getBoundingClientRect().top;
      if (Math.abs(before - after) > 1) {
        el.style.translate = `0 ${before - after}px`;
        void el.offsetHeight;
      }
      el.style.removeProperty('transition');
      el.style.removeProperty('translate');
      return;
    }
    flipFrom.current = r.top;
    el.style.transition = 'none';
    clearInline(el);
    setDetent(target.detent);
  };
  const dragHandlers = { onPointerDown: onDragStart, onPointerMove: onDragMove, onPointerUp: onDragEnd, onPointerCancel: onDragEnd };

  const hasToolbar = title != null || leading != null || trailing != null;
  return (
    <dialog
      ref={ref}
      className={cx(
        'ios-sheet',
        fullScreen && 'ios-sheet--full-screen',
        inspector && 'ios-sheet--inspector',
        stacked && 'is-stacked',
        behind && 'is-behind',
        className,
      )}
      data-detent={detent}
      aria-labelledby={title != null ? titleId : undefined}
      tabIndex={-1}
      onCancel={e => {
        e.preventDefault();
        if (canDismiss) onOpenChange(false);
        onCancel?.(e);
      }}
      onClose={e => {
        const el = ref.current;
        if (el && !el.open) {
          clearInline(el);
          if (openRef.current) onOpenChange(false); // closed by a swipe or a <form method="dialog">
        }
        onClose?.(e);
      }}
      onClick={e => {
        const el = ref.current;
        if (el && e.target === el && canDismiss) {
          const r = el.getBoundingClientRect();
          if (e.clientX < r.left || e.clientX > r.right || e.clientY < r.top || e.clientY > r.bottom) onOpenChange(false);
        }
        onClick?.(e);
      }}
      {...rest}
    >
      {showGrabber && (
        <button
          type="button"
          className="ios-sheet__grabber"
          aria-label="Sheet Grabber"
          {...dragHandlers}
          onClick={() => {
            if (dragged.current) {
              dragged.current = false;
              return;
            }
            if (detents.length > 1 && !regular) setDetent(detents[(detents.indexOf(detent) + 1) % detents.length]);
          }}
        />
      )}
      {hasToolbar && (
        <header className="ios-sheet__toolbar" {...dragHandlers}>
          {leading}
          {subtitle != null ? (
            <div className="ios-sheet__title-group">
              <h2 className="ios-sheet__title" id={titleId}>{title}</h2>
              <p className="ios-sheet__subtitle">{subtitle}</p>
            </div>
          ) : title != null ? (
            <h2 className="ios-sheet__title" id={titleId}>{title}</h2>
          ) : (
            <span className="ios-sheet__title" aria-hidden="true" />
          )}
          {trailing}
        </header>
      )}
      <div className="ios-sheet__content">{children}</div>
    </dialog>
  );
}
