// sidebar.tsx
// ---------------------------------------------------------------------------------------------------

/* ==========================================================================
   Sidebars — kit page "Sidebars" (Sidebar, Sidebar Row, Section Header, Sidebar Search Field, _Selection BG…).
   Renders the markup of sidebars.css. iPad column; on iPhone the App shows it as a full-screen page (sidebar apps)
   or hides it (tab apps).
   ========================================================================== */

interface SidebarState {
  value: string | undefined;
  select: (value: string) => void;
}
const SidebarContext = createContext<SidebarState | null>(null);
const SidebarLevelContext = createContext(0);

export interface SidebarSearch {
  value?: string;
  /** Receives the new text. */
  onChange?: (value: string) => void;
  /** Default "Search". */
  placeholder?: string;
  /** Show the microphone (dictation) symbol at the end. */
  dictation?: boolean;
}

export interface SidebarProps extends Omit<HTMLAttributes<HTMLElement>, 'onChange' | 'defaultValue'> {
  /** The selected row's value (controlled). */
  value?: string;
  defaultValue?: string;
  /** Receives the new selected value. */
  onChange?: (value: string) => void;
  /** Bar buttons at the start of the 44 pt toolbar row (e.g. <BarButton>Edit</BarButton>). */
  toolbar?: ReactNode;
  /** Bar buttons at the end of the toolbar row. */
  toolbarTrailing?: ReactNode;
  /** iPad: add the "Hide Sidebar" button at the end of the toolbar row (only inside App/SplitView). Default true. */
  toggleButton?: boolean;
  /** Large title at the top of the list (Bold 34). Give it when the sidebar is the iPhone first page (a sidebar app). */
  title?: string;
  /** A search field under the toolbar (kit "Sidebar Search Field"). */
  search?: SidebarSearch;
  /** The window is not focused (kit BG Active = False): lighter background. */
  inactive?: boolean;
  /** Accessible name. Default: the title, or "Sidebar". */
  label?: string;
  /** SidebarItem and SidebarSection elements. */
  children?: ReactNode;
}

/**
 * The iPad sidebar (kit "Sidebar"). Pass it to App / SplitView / TabView as `sidebar`.
 *
 *     <Sidebar value={folder} onChange={setFolder} search={{ value: q, onChange: setQ }}>
 *       <SidebarItem value="inbox" icon="tray" label="Inbox" detail="12" />
 *       <SidebarSection title="Folders">
 *         <SidebarItem value="work" icon="folder" label="Work" />
 *       </SidebarSection>
 *     </Sidebar>
 */
export function Sidebar({
  value, defaultValue, onChange, toolbar, toolbarTrailing, toggleButton = true, title, search, inactive, label, className,
  children, ...rest
}: SidebarProps) {
  const shell = useAppShell();
  const win = useContext(IpadWindowContext);
  const [current, setCurrent] = useControllable<string | undefined>(value, defaultValue, v => {
    if (v !== undefined) onChange?.(v);
  });
  const select = (v: string) => {
    setCurrent(v);
    // iPhone: choosing a row on the full-screen sidebar page opens the main column.
    if (shell && shell.sizeClass === 'compact' && shell.sidebarVisible) shell.setSidebarVisible(false);
  };
  const showToggle = toggleButton && shell?.hasSidebar && shell.sizeClass === 'regular';
  const showControls = win?.controls;
  const hasToolbar = toolbar != null || toolbarTrailing != null || showToggle || showControls;

  // Loose rows are grouped into one list; sections stay as they are.
  const parts: ReactNode[] = [];
  let run: ReactNode[] = [];
  const flush = () => {
    if (run.length) parts.push(<ul key={`list-${parts.length}`} className="ios-sidebar__list">{run}</ul>);
    run = [];
  };
  for (const child of Children.toArray(children)) {
    if (isValidElement(child) && child.type === SidebarItem) run.push(child);
    else {
      flush();
      parts.push(child);
    }
  }
  flush();

  return (
    <SidebarContext.Provider value={{ value: current, select }}>
      <nav className={cx('ios-sidebar', inactive && 'ios-sidebar--inactive', className)} aria-label={label ?? title ?? 'Sidebar'} {...rest}>
        {hasToolbar && (
          <div className="ios-sidebar__toolbar">
            {showControls && (
              <span className={cx('ios-window__controls', win?.inactive && 'ios-window__controls--inactive')} aria-hidden="true">
                <span />
                <span />
                <span />
              </span>
            )}
            {toolbar}
            {(toolbarTrailing != null || showToggle) && (
              <div className="ios-sidebar__toolbar-trailing">
                {toolbarTrailing}
                {showToggle && (
                  <button
                    type="button"
                    className="ios-bar-button ios-bar-button--icon"
                    aria-label="Hide Sidebar"
                    aria-expanded={shell?.sidebarVisible}
                    onClick={shell?.toggleSidebar}
                  >
                    <Icon name="sidebar-left" />
                  </button>
                )}
              </div>
            )}
          </div>
        )}
        <div className="ios-sidebar__content">
          {title && <h1 className="ios-sidebar__heading">{title}</h1>}
          {search && (
            <label className="ios-sidebar__search">
              <Icon name="magnifyingglass" />
              <input
                type="search"
                placeholder={search.placeholder ?? 'Search'}
                aria-label={search.placeholder ?? 'Search'}
                value={search.value}
                onChange={search.onChange ? e => search.onChange?.(e.target.value) : undefined}
                readOnly={search.value != null && !search.onChange}
              />
              {search.dictation && <Icon name="mic" />}
            </label>
          )}
          {parts}
        </div>
      </nav>
    </SidebarContext.Provider>
  );
}

export interface SidebarSectionProps extends HTMLAttributes<HTMLElement> {
  /** Section heading (kit "Section Header"). */
  title: string;
  /** Optional text at the end of the header. */
  detail?: ReactNode;
  /** The header collapses the section (chevron). Default true. */
  collapsible?: boolean;
  /** Open at first (collapsible sections). Default true. */
  defaultExpanded?: boolean;
  /** SidebarItem elements. */
  children?: ReactNode;
}

/** A titled group of sidebar rows; collapses from its header like iPadOS sidebars. */
export function SidebarSection({ title, detail, collapsible = true, defaultExpanded = true, className, children, ...rest }: SidebarSectionProps) {
  const header = (
    <>
      {title}
      {detail != null && <span className="ios-sidebar__detail">{detail}</span>}
    </>
  );
  if (!collapsible)
    return (
      <section className={cx('ios-sidebar__section', className)} {...rest}>
        <h2 className="ios-sidebar__header">{header}</h2>
        <ul className="ios-sidebar__list">{children}</ul>
      </section>
    );
  return (
    <details className={cx('ios-sidebar__section', className)} open={defaultExpanded} {...rest}>
      <summary className="ios-sidebar__header">{header}</summary>
      <ul className="ios-sidebar__list">{children}</ul>
    </details>
  );
}

export interface SidebarItemProps extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'value' | 'children'> {
  /** Identifies the row (the Sidebar value). */
  value: string;
  label: string;
  /** Leading symbol, drawn in the accent colour. */
  icon?: IconName;
  /** Leading picture instead of a symbol (28 × 28, radius 6): an image URL. */
  image?: string;
  /** Second line under the label (13 pt, secondary). */
  subtitle?: string;
  /** Trailing text: a count or a value. */
  detail?: ReactNode;
  /** Trailing element after the detail (a checkmark symbol, a Toggle…). */
  accessory?: ReactNode;
  /** Nested rows (SidebarItem): this row expands and collapses with a chevron. */
  children?: ReactNode;
  /** Nested rows shown at first. Default true. */
  defaultExpanded?: boolean;
}

/** One sidebar row (kit "Sidebar Row"): symbol, label, detail; selected = grey capsule. */
export function SidebarItem({
  value, label, icon, image, subtitle, detail, accessory, children, defaultExpanded = true, disabled, className, onClick, type = 'button',
  ...rest
}: SidebarItemProps) {
  const sidebar = useContext(SidebarContext);
  const level = useContext(SidebarLevelContext);
  const selected = sidebar?.value === value;
  const cls = cx('ios-sidebar__item', level > 0 && `ios-sidebar__item--level-${Math.min(level, 2)}`, className);
  const inner = (
    <>
      {image ? <img className="ios-sidebar__image" src={image} alt="" /> : icon && <Icon name={icon} />}
      {subtitle ? (
        <span className="ios-sidebar__text">
          <span className="ios-sidebar__title">{label}</span>
          <span className="ios-sidebar__subtitle">{subtitle}</span>
        </span>
      ) : (
        <span className="ios-sidebar__title">{label}</span>
      )}
      {detail != null && <span className="ios-sidebar__detail">{detail}</span>}
      {accessory}
    </>
  );
  const nested = Children.toArray(children).filter(isValidElement) as ReactElement[];
  if (nested.length)
    return (
      <li>
        <details className="ios-sidebar__group" open={defaultExpanded}>
          <summary className={cls}>{inner}</summary>
          <SidebarLevelContext.Provider value={level + 1}>
            <ul className="ios-sidebar__list">{nested}</ul>
          </SidebarLevelContext.Provider>
        </details>
      </li>
    );
  return (
    <li>
      <button
        type={type}
        className={cls}
        aria-current={selected ? 'page' : undefined}
        aria-disabled={disabled || undefined}
        disabled={disabled}
        onClick={e => {
          onClick?.(e);
          if (!e.defaultPrevented) sidebar?.select(value);
        }}
        {...rest}
      >
        {inner}
      </button>
    </li>
  );
}
