export interface SliderProps
  extends Omit<InputHTMLAttributes<HTMLInputElement>, 'type' | 'value' | 'defaultValue' | 'onChange' | 'min' | 'max' | 'step' | 'children'> {
  /** The value (controlled). Use with onChange. */
  value?: number;
  /** Start value when uncontrolled. Default: min. */
  defaultValue?: number;
  /** Receives the new number, not an event. Called while dragging. */
  onChange?: (value: number) => void;
  /** Range. Default 0…100. */
  min?: number;
  max?: number;
  /** Default 1. Use a bigger step together with ticks for a few discrete values. */
  step?: number;
  /** Tick marks under the track: true = one per step (use for 2–11 stops), or a number of ticks. */
  ticks?: boolean | number;
  /** Symbol at the low end (kit "Symbol - Min"), e.g. "speaker". */
  minIcon?: IconName;
  /** Symbol at the high end (kit "Symbol - Max"), e.g. "speaker-wave". */
  maxIcon?: IconName;
  /** Accessible name when no visible label points at the slider (e.g. "Volume"). */
  label?: string;
  /** Class and style go on the wrapper (placement only). */
  className?: string;
  style?: CSSProperties;
}

/**
 * An iOS slider (kit "Sliders"): accent fill on a 6 pt track, 38 × 24 white knob with a soft shadow,
 * optional tick marks and min / max symbols.
 * <Slider label="Volume" value={volume} onChange={setVolume} minIcon="speaker" maxIcon="speaker-wave" />
 */
export function Slider({
  value,
  defaultValue,
  onChange,
  min = 0,
  max = 100,
  step = 1,
  ticks,
  minIcon,
  maxIcon,
  label,
  id,
  className,
  style,
  disabled,
  ...rest
}: SliderProps) {
  const [current, setCurrent] = useControllable(value, defaultValue ?? min, onChange);
  const fieldId = useFieldId(id);
  const clamped = Math.min(max, Math.max(min, current));
  const pct = max > min ? ((clamped - min) / (max - min)) * 100 : 0;
  const tickCount = ticks === true ? Math.round((max - min) / step) + 1 : typeof ticks === 'number' ? ticks : 0;
  return (
    <div
      className={cx('ios-slider', tickCount >= 2 && 'ios-slider--ticks', className)}
      style={vars(style, { '--ios-slider-ticks': tickCount >= 2 ? tickCount : undefined })}
    >
      {minIcon && <Icon name={minIcon} className="ios-slider__symbol" />}
      <input
        type="range"
        id={fieldId}
        className="ios-slider__input"
        min={min}
        max={max}
        step={step}
        value={clamped}
        disabled={disabled}
        onChange={e => setCurrent(Number(e.target.value))}
        aria-label={label}
        style={vars(undefined, { '--ios-slider-value': `${pct}%` })}
        {...rest}
      />
      {maxIcon && <Icon name={maxIcon} className="ios-slider__symbol" />}
    </div>
  );
}
