/* ==========================================================================
   Status bar — kit page "Status Bars and Menu Bars". FOR MOCKUPS ONLY (device frames, screenshots, prototypes).
   A real app never draws a status bar: the system does. Renders the markup of status-bars.css.
   ========================================================================== */

export interface StatusBarProps extends HTMLAttributes<HTMLDivElement> {
  /** iphone (62 tall, Dynamic Island) · ipad (32 tall, time + date, menu bar) · auto (from the window size). */
  device?: 'iphone' | 'ipad' | 'auto';
  /** "9:41" (Apple's marketing time). iPad shows "9:41 AM". */
  time?: string;
  /** iPad only: the date ("Wed Apr 1"). */
  date?: string;
  /** iPad only: the app name shown bold in the menu bar. */
  appName?: string;
  /** iPad only: menu titles shown while the menu bar is expanded (["File", "Edit", "View"]). */
  menus?: string[];
  /** iPad only: the open menu (highlighted). */
  selectedMenu?: string;
  /** iPad only: red/yellow/green window controls instead of time and date (full-screen app with its menu bar shown). */
  windowControls?: boolean;
  /** Battery level shown on iPad (percent). */
  battery?: number;
  /** auto: primary label colour (black in Light, white in Dark) · on-dark: white over dark images · on-light: black. */
  appearance?: 'auto' | 'on-dark' | 'on-light';
}

/** A static iPhone or iPad status bar for mockups. */
export function StatusBar({
  device = 'auto',
  time = '9:41',
  date = 'Wed Apr 1',
  appName = 'App',
  menus,
  selectedMenu,
  windowControls,
  battery = 100,
  appearance = 'auto',
  className,
  ...rest
}: StatusBarProps) {
  const sizeClass = useSizeClass();
  const ipad = device === 'ipad' || (device === 'auto' && sizeClass === 'regular');
  const cls = cx('ios-status-bar', ipad && 'ios-status-bar--ipad', appearance !== 'auto' && `ios-status-bar--${appearance}`, className);

  if (!ipad) {
    return (
      <div role="img" aria-label={`Status bar: ${time}, full signal, Wi-Fi, battery full`} className={cls} {...rest}>
        <span className="ios-status-bar__time">{time}</span>
        <span className="ios-status-bar__island" />
        <span className="ios-status-bar__levels">
          <span className="ios-status-bar__cellular" />
          <span className="ios-status-bar__wifi" />
          <span className="ios-status-bar__battery" />
        </span>
      </div>
    );
  }
  const clock = /AM|PM/i.test(time) ? time : `${time} AM`;
  return (
    <div role="img" aria-label={`Status bar: ${clock}, ${date}, Wi-Fi, battery ${battery}%`} className={cls} {...rest}>
      {windowControls ? (
        <span className="ios-status-bar__window-controls">
          <span className="ios-status-bar__close" />
          <span className="ios-status-bar__minimize" />
          <span className="ios-status-bar__fullscreen" />
        </span>
      ) : (
        <>
          <span className="ios-status-bar__time">{clock}</span>
          <span className="ios-status-bar__date">{date}</span>
        </>
      )}
      <span className="ios-status-bar__menus">
        <span className={cx('ios-status-bar__menu', 'ios-status-bar__menu--app', selectedMenu === appName && 'is-selected')}>{appName}</span>
        {menus?.map(m => (
          <span key={m} className={cx('ios-status-bar__menu', selectedMenu === m && 'is-selected')}>
            {m}
          </span>
        ))}
      </span>
      <span className="ios-status-bar__levels">
        <span className="ios-status-bar__wifi" />
        <span className="ios-status-bar__percent">{battery}%</span>
        <span className="ios-status-bar__battery" />
      </span>
    </div>
  );
}
