export interface StepperProps extends Omit<HTMLAttributes<HTMLDivElement>, 'onChange' | 'defaultValue' | 'children'> {
  /** The value (controlled). Use with onChange. The stepper never shows it: put it in the row label. */
  value?: number;
  /** Start value when uncontrolled. Default: min (or 0). */
  defaultValue?: number;
  /** Receives the new number, not an event. */
  onChange?: (value: number) => void;
  /** Lowest value: the − half is disabled there. Default: no limit. */
  min?: number;
  /** Highest value: the + half is disabled there. Default: no limit. */
  max?: number;
  /** Amount per tap. Default 1. */
  step?: number;
  disabled?: boolean;
  /** Accessible name of the stepper, e.g. "Guests". */
  label?: string;
  /** Accessible names of the halves. Default "Decrease" / "Increase". */
  decrementLabel?: string;
  incrementLabel?: string;
}

/**
 * An iOS stepper (kit "Stepper"): − and + in a 92 × 32 capsule. Holding a half repeats.
 * <span>Guests: {guests}</span> <Stepper label="Guests" value={guests} onChange={setGuests} min={1} max={10} />
 */
export function Stepper({
  value,
  defaultValue,
  onChange,
  min = -Infinity,
  max = Infinity,
  step = 1,
  disabled,
  label,
  decrementLabel = 'Decrease',
  incrementLabel = 'Increase',
  className,
  ...rest
}: StepperProps) {
  const [current, setCurrent] = useControllable(value, defaultValue ?? (Number.isFinite(min) ? min : 0), onChange);
  const latest = useRef(current);
  const timer = useRef<{ timeout?: ReturnType<typeof setTimeout>; interval?: ReturnType<typeof setInterval>; repeated: boolean }>({
    repeated: false,
  });
  useEffect(() => {
    latest.current = current;
  }, [current]);
  const stop = () => {
    clearTimeout(timer.current.timeout);
    clearInterval(timer.current.interval);
  };
  useEffect(() => stop, []);

  const stepBy = (dir: 1 | -1) => {
    const next = Math.min(max, Math.max(min, Math.round((latest.current + dir * step) * 1e6) / 1e6));
    if (next === latest.current) return false;
    latest.current = next;
    setCurrent(next);
    return true;
  };
  const half = (dir: 1 | -1) => ({
    onPointerDown: (e: ReactPointerEvent<HTMLButtonElement>) => {
      if (e.button !== 0) return;
      stop();
      timer.current.repeated = false;
      timer.current.timeout = setTimeout(() => {
        timer.current.interval = setInterval(() => {
          timer.current.repeated = true;
          if (!stepBy(dir)) stop();
        }, 100);
      }, 500);
    },
    onPointerUp: stop,
    onPointerLeave: stop,
    onPointerCancel: stop,
    onClick: () => {
      if (timer.current.repeated) {
        timer.current.repeated = false;
        return;
      }
      stepBy(dir);
    },
  });

  return (
    <div className={cx('ios-stepper', className)} role="group" aria-label={label} {...rest}>
      <button
        type="button"
        className="ios-stepper__decrement"
        aria-label={decrementLabel}
        disabled={disabled || current <= min}
        {...half(-1)}
      >
        <Icon name="minus" />
      </button>
      <button
        type="button"
        className="ios-stepper__increment"
        aria-label={incrementLabel}
        disabled={disabled || current >= max}
        {...half(1)}
      >
        <Icon name="plus" />
      </button>
    </div>
  );
}
// ---------------------------------------------------------------------------------------------------
// tab-bar.tsx
// ---------------------------------------------------------------------------------------------------

/* ==========================================================================
   Tab bars — kit page "Tab Bars". Renders the markup of tab-bars.css:
   iPhone = floating Regular-material capsule at the bottom (symbol + 10 pt label), search/prominent tab as a separate
   circle, minimized state; iPad = material capsule at the top centre with text tabs, sidebar button, search symbol.
   ========================================================================== */

/** default · search (the search role: a separate circle at the end) · prominent (a separate circle for one key tab). */
export type TabVariant = 'default' | 'search' | 'prominent';

export interface TabProps extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'value' | 'children'> {
  /** Identifies the tab (the value of TabBar / TabView). */
  value: string;
  /** The tab's name: under the symbol on iPhone, the tab text on iPad, and the accessible name. One short word. */
  label: string;
  /** The symbol (iPhone shows it; iPad shows the label). Use the filled version of a symbol for tabs. */
  icon: IconName;
  variant?: TabVariant;
  /** In a TabView: the grouped background on this tab's page (automatic when the page has an inset grouped <List>
   *  or a <Grid> as a direct child; set it for other grouped content). Ignored in a TabBar. */
  grouped?: boolean;
  /** In a TabView: the page shown while this tab is selected. Ignored in a TabBar. */
  children?: ReactNode;
}

interface TabBarState {
  value: string;
  select: (value: string) => void;
  minimized: boolean;
  expand: () => void;
}
const TabBarContext = createContext<TabBarState | null>(null);

/** One tab. Only inside a TabBar or a TabView. */
export function Tab({ value, label, icon, variant = 'default', className, onClick, grouped: _grouped, children: _page, type = 'button', ...rest }: TabProps) {
  const bar = useContext(TabBarContext);
  const selected = bar?.value === value;
  const separate = variant !== 'default';
  return (
    <button
      type={type}
      className={cx('ios-tab', separate && `ios-tab--${variant}`, className)}
      aria-current={selected ? 'page' : undefined}
      aria-label={separate ? label : undefined}
      onClick={e => {
        onClick?.(e);
        if (e.defaultPrevented || !bar) return;
        if (bar.minimized && selected) bar.expand();
        else bar.select(value);
      }}
      {...rest}
    >
      <Icon name={icon} />
      {!separate && <span className="ios-tab__label">{label}</span>}
    </button>
  );
}

export interface TabBarProps extends Omit<HTMLAttributes<HTMLElement>, 'onChange' | 'defaultValue'> {
  /** The selected tab's value (controlled). */
  value?: string;
  /** First selected tab (uncontrolled). Default: the first tab. */
  defaultValue?: string;
  /** Receives the new tab value. */
  onChange?: (value: string) => void;
  /** iPhone: only the selected tab's symbol in a circle (after scrolling down). Ignored on iPad. */
  minimized?: boolean;
  /** Called with false when the minimized bar is tapped (expand it). */
  onMinimizedChange?: (minimized: boolean) => void;
  /** iPad: show the sidebar button at the start. Default: automatic inside an App/SplitView that has a sidebar. */
  onSidebarToggle?: () => void;
  /** iPad: the sidebar is visible (sets the button's accessible name and aria-expanded). */
  sidebarVisible?: boolean;
  /** Accessible name of the bar. Default "Tabs". */
  label?: string;
  /** 2–5 <Tab> elements; a Tab with variant "search" or "prominent" last. */
  children?: ReactNode;
}

/**
 * The app's tab bar (kit "Tab Bar - iPhone" / "Tab Bar - iPad"). Usually you don't use it directly: TabView builds it.
 *
 *     <TabBar value={tab} onChange={setTab}>
 *       <Tab value="home" icon="house" label="Home" />
 *       <Tab value="search" icon="magnifyingglass" label="Search" variant="search" />
 *     </TabBar>
 */
export function TabBar({
  value, defaultValue, onChange, minimized = false, onMinimizedChange, onSidebarToggle, sidebarVisible, label = 'Tabs',
  className, children, ...rest
}: TabBarProps) {
  const tabs = Children.toArray(children).filter(isValidElement) as ReactElement<TabProps>[];
  const [current, setCurrent] = useControllable(value, defaultValue ?? tabs[0]?.props.value ?? '', onChange);
  const shell = useAppShell();
  const toggle = onSidebarToggle ?? (shell?.hasSidebar ? shell.toggleSidebar : undefined);
  const visible = sidebarVisible ?? shell?.sidebarVisible ?? false;
  const normal = tabs.filter(t => (t.props.variant ?? 'default') === 'default');
  const separate = tabs.filter(t => (t.props.variant ?? 'default') !== 'default');
  return (
    <TabBarContext.Provider value={{ value: current, select: setCurrent, minimized, expand: () => onMinimizedChange?.(false) }}>
      <nav className={cx('ios-tab-bar', minimized && 'ios-tab-bar--minimized', className)} aria-label={label} {...rest}>
        {toggle && (
          <button
            type="button"
            className="ios-tab-bar__sidebar-button"
            aria-label={visible ? 'Hide Sidebar' : 'Show Sidebar'}
            aria-expanded={visible}
            onClick={toggle}
          >
            <Icon name="sidebar-left" />
          </button>
        )}
        <div className="ios-tab-bar__tabs">{normal}</div>
        {separate}
      </nav>
    </TabBarContext.Provider>
  );
}

export interface TabViewProps extends Omit<AppProps, 'tabBar' | 'scroll' | 'onChange' | 'defaultValue' | 'children'> {
  /** The selected tab's value (controlled). */
  value?: string;
  /** First selected tab (uncontrolled). Default: the first tab. */
  defaultValue?: string;
  /** Receives the new tab value. */
  onChange?: (value: string) => void;
  /** iPhone: minimize the tab bar while scrolling down, expand it on scroll up (SwiftUI .tabBarMinimizeBehavior(.onScrollDown)). */
  minimizeOnScroll?: boolean;
  /** Accessible name of the tab bar. Default "Tabs". */
  tabBarLabel?: string;
  /** <Tab value icon label>page</Tab> for each tab (2–5; a search tab last). */
  children?: ReactNode;
}

/**
 * A tab app: the App shell + a TabBar + one scrolling page per tab (each keeps its scroll position while you switch
 * tabs; a new screen pushed in a tab starts at the top: its NavigationBar scrolls the page up when it mounts).
 * iPhone: bar at the bottom. iPad: bar at the top centre, optional sidebar (`sidebar` prop) with a sidebar button.
 *
 *     <TabView defaultValue="home">
 *       <Tab value="home" icon="house" label="Home"><HomePage /></Tab>
 *       <Tab value="library" icon="book" label="Library"><LibraryPage /></Tab>
 *       <Tab value="search" icon="magnifyingglass" label="Search" variant="search"><SearchPage /></Tab>
 *     </TabView>
 */
export function TabView({ value, defaultValue, onChange, minimizeOnScroll, tabBarLabel, inset, children, ...appProps }: TabViewProps) {
  const tabs = Children.toArray(children).filter(isValidElement) as ReactElement<TabProps>[];
  const [current, setCurrent] = useControllable(value, defaultValue ?? tabs[0]?.props.value ?? '', onChange);
  const [visited, setVisited] = useState<ReadonlySet<string>>(() => new Set([current]));
  if (!visited.has(current)) setVisited(new Set(visited).add(current));
  const [minimized, setMinimized] = useState(false);
  const sizeClass = useSizeClass();
  const lastY = useRef(0);

  const onScroll = (e: ReactUIEvent<HTMLElement>) => {
    if (!minimizeOnScroll || sizeClass === 'regular') return;
    const y = e.currentTarget.scrollTop;
    const d = y - lastY.current;
    if (d > 6 && y > 40) setMinimized(true);
    else if (d < -6 || y <= 0) setMinimized(false);
    if (Math.abs(d) > 6 || y <= 0) lastY.current = y;
  };
  const select = (v: string) => {
    lastY.current = 0;
    setMinimized(false);
    setCurrent(v);
  };

  return (
    <App
      {...appProps}
      scroll={false}
      tabBar={
        <TabBar value={current} onChange={select} minimized={minimized && sizeClass === 'compact'} onMinimizedChange={setMinimized} label={tabBarLabel}>
          {tabs.map(t => cloneElement(t, { key: t.props.value, grouped: undefined, children: undefined }))}
        </TabBar>
      }
    >
      {tabs.map(t =>
        visited.has(t.props.value) ? (
          <main
            key={t.props.value}
            className={cx('ios-app__content', inset && 'ios-app__content--inset', t.props.grouped && 'ios-app__content--grouped')}
            hidden={t.props.value !== current}
            onScroll={onScroll}
          >
            {t.props.children}
          </main>
        ) : null,
      )}
    </App>
  );
}
