/** When the clear button (xmark.circle.fill) shows: while-editing (default, iOS forms) · always (when there is text) · never. */
export type TextFieldClearButton = 'while-editing' | 'always' | 'never';

export interface TextFieldProps extends Omit<InputHTMLAttributes<HTMLInputElement>, 'value' | 'defaultValue' | 'onChange' | 'size'> {
  /** The text (controlled). Use defaultValue for uncontrolled. */
  value?: string;
  defaultValue?: string;
  /** Receives the new text (not an event). */
  onChange?: (value: string) => void;
  /** Accessible name when no visible label points at the field. Defaults to the placeholder. */
  label?: string;
  clearButton?: TextFieldClearButton;
}

/**
 * An iOS text field: one 52 pt row of a form (kit "Text Field"), text 17 Medium, accent caret, clear button while editing.
 * Several fields in a row get separators between them. Put them in <TextFieldGroup> (a card) or in list rows.
 *
 *     <TextField placeholder="Name" value={name} onChange={setName} />
 */
export function TextField({
  value,
  defaultValue = '',
  onChange,
  label,
  placeholder,
  clearButton = 'while-editing',
  className,
  style,
  id,
  disabled,
  type = 'text',
  ...rest
}: TextFieldProps) {
  const [text, setText] = useControllable(value, defaultValue, onChange);
  const inputId = useFieldId(id);
  const input = useRef<HTMLInputElement>(null);
  return (
    <label className={cx('ios-text-field', clearButton === 'always' && 'ios-text-field--clear-always', className)} style={style}>
      <input
        {...rest}
        ref={input}
        id={inputId}
        className="ios-text-field__input"
        type={type}
        value={text}
        placeholder={placeholder || ' '}
        aria-label={label ?? (placeholder || undefined)}
        disabled={disabled}
        onChange={e => setText(e.target.value)}
      />
      {clearButton !== 'never' && !disabled && (
        <button
          type="button"
          className="ios-text-field__clear"
          aria-label="Clear text"
          tabIndex={-1}
          onPointerDown={e => e.preventDefault()}
          onClick={() => {
            setText('');
            input.current?.focus();
          }}
        >
          <Icon name="xmark-circle-fill" />
        </button>
      )}
    </label>
  );
}

export type SecureFieldProps = Omit<TextFieldProps, 'type' | 'clearButton'>;

/** A password field (iOS SecureField): dots instead of letters, no clear button. */
export function SecureField({ autoComplete = 'current-password', ...props }: SecureFieldProps) {
  return <TextField {...props} type="password" clearButton="never" autoComplete={autoComplete} />;
}

export interface TextViewProps extends Omit<TextareaHTMLAttributes<HTMLTextAreaElement>, 'value' | 'defaultValue' | 'onChange'> {
  value?: string;
  defaultValue?: string;
  /** Receives the new text (not an event). */
  onChange?: (value: string) => void;
  /** Accessible name when no visible label points at the field. Defaults to the placeholder. */
  label?: string;
}

/** Multi-line text (iOS TextEditor / TextField(axis: .vertical)): the text-field row look, grows with its text. */
export function TextView({ value, defaultValue = '', onChange, label, placeholder, className, style, id, rows = 3, ...rest }: TextViewProps) {
  const [text, setText] = useControllable(value, defaultValue, onChange);
  const inputId = useFieldId(id);
  return (
    <label className={cx('ios-text-view', className)} style={style}>
      <textarea
        {...rest}
        id={inputId}
        className="ios-text-view__input"
        rows={rows}
        value={text}
        placeholder={placeholder || ' '}
        aria-label={label ?? (placeholder || undefined)}
        onChange={e => setText(e.target.value)}
      />
    </label>
  );
}

export interface TextFieldGroupProps extends HTMLAttributes<HTMLDivElement> {
  children?: ReactNode;
}

/** A card of text fields (kit "Grouped Table View": radius 26, grouped secondary background). */
export function TextFieldGroup({ className, children, ...rest }: TextFieldGroupProps) {
  return (
    <div className={cx('ios-text-field-group', className)} {...rest}>
      {children}
    </div>
  );
}

export interface SearchFieldProps extends Omit<InputHTMLAttributes<HTMLInputElement>, 'value' | 'defaultValue' | 'onChange' | 'size' | 'onSubmit'> {
  value?: string;
  defaultValue?: string;
  /** Receives the new text (not an event). */
  onChange?: (value: string) => void;
  /** Return / the Search key. */
  onSubmit?: (value: string) => void;
  /** regular = 48 tall (iPhone bottom toolbar, tab bar search) · small = 44 tall (iPad top toolbar). */
  size?: 'regular' | 'small';
  /** Shows the microphone (dictation) button and is called when it is tapped. */
  onDictate?: () => void;
  /** Accessible name. Default "Search". */
  label?: string;
}

/**
 * The search field of toolbars and tab bars: a Regular-material capsule (kit "_Search - 48pt / 44pt").
 *
 *     <SearchField value={query} onChange={setQuery} onSubmit={search} />
 */
export function SearchField({
  value,
  defaultValue = '',
  onChange,
  onSubmit,
  size = 'regular',
  onDictate,
  label = 'Search',
  placeholder = 'Search',
  className,
  style,
  disabled,
  onKeyDown,
  ...rest
}: SearchFieldProps) {
  const [text, setText] = useControllable(value, defaultValue, onChange);
  const input = useRef<HTMLInputElement>(null);
  const keyDown = (e: ReactKeyboardEvent<HTMLInputElement>) => {
    onKeyDown?.(e);
    if (e.defaultPrevented) return;
    if (e.key === 'Enter') onSubmit?.(text);
    if (e.key === 'Escape' && text) {
      e.preventDefault();
      setText('');
    }
  };
  return (
    <div className={cx('ios-search-field', size === 'small' && 'ios-search-field--small', className)} role="search" style={style}>
      <Icon name="magnifyingglass" className="ios-search-field__icon" />
      <input
        {...rest}
        ref={input}
        className="ios-search-field__input"
        type="search"
        enterKeyHint="search"
        value={text}
        placeholder={placeholder || ' '}
        aria-label={label}
        disabled={disabled}
        onChange={e => setText(e.target.value)}
        onKeyDown={keyDown}
      />
      {!disabled && (
        <button
          type="button"
          className="ios-search-field__clear"
          aria-label="Clear text"
          tabIndex={-1}
          onPointerDown={e => e.preventDefault()}
          onClick={() => {
            setText('');
            input.current?.focus();
          }}
        >
          <Icon name="xmark-circle-fill" />
        </button>
      )}
      {onDictate && (
        <button type="button" className="ios-search-field__mic" aria-label="Dictate" disabled={disabled} onClick={onDictate}>
          <Icon name="mic" />
        </button>
      )}
    </div>
  );
}
