type ToggleNativeProps = Omit<
  InputHTMLAttributes<HTMLInputElement>,
  'type' | 'role' | 'checked' | 'defaultChecked' | 'value' | 'defaultValue' | 'onChange' | 'children'
>;

export interface ToggleProps extends ToggleNativeProps {
  /** On (controlled). Use with onChange. `value` is the same thing. */
  checked?: boolean;
  defaultChecked?: boolean;
  value?: boolean;
  defaultValue?: boolean;
  /** Receives the new state (true = on), not an event. */
  onChange?: (checked: boolean) => void;
  /** Accessible name when no visible label points at the switch (in a list row the row title labels it). */
  label?: string;
  /** Accessibility "On/Off Labels": draws I (on) and O (off) inside the track. */
  onOffLabels?: boolean;
}

/**
 * An iOS switch (kit "Toggle - Switch"): 64 × 28, green when on. For on/off settings that apply immediately.
 * <Toggle label="Wi-Fi" checked={wifi} onChange={setWifi} />
 */
export function Toggle({
  checked,
  defaultChecked,
  value,
  defaultValue,
  onChange,
  label,
  onOffLabels,
  id,
  className,
  ...rest
}: ToggleProps) {
  const [on, setOn] = useControllable(checked ?? value, defaultChecked ?? defaultValue ?? false, onChange);
  const fieldId = useFieldId(id);
  return (
    <input
      type="checkbox"
      role="switch"
      id={fieldId}
      className={cx('ios-toggle', onOffLabels && 'ios-toggle--labels', className)}
      checked={on}
      onChange={e => setOn(e.target.checked)}
      aria-label={label}
      {...rest}
    />
  );
}

export interface CheckboxProps extends ToggleNativeProps {
  /** Selected (controlled). Use with onChange. `value` is the same thing. */
  checked?: boolean;
  defaultChecked?: boolean;
  value?: boolean;
  defaultValue?: boolean;
  /** Receives the new state (true = selected), not an event. */
  onChange?: (checked: boolean) => void;
  /** Accessible name, e.g. "Select Photo" (the circle has no visible text). */
  label?: string;
}

/**
 * The iOS selection circle (kit "_Edit Buttons" Selected / Unselected): 22 × 22, accent fill + white checkmark when
 * selected. For picking several items (edit mode, to-do items). For on/off settings use Toggle.
 * <Checkbox label="Select Photo" checked={selected} onChange={setSelected} />
 */
export function Checkbox({ checked, defaultChecked, value, defaultValue, onChange, label, id, className, ...rest }: CheckboxProps) {
  const [on, setOn] = useControllable(checked ?? value, defaultChecked ?? defaultValue ?? false, onChange);
  const fieldId = useFieldId(id);
  return (
    <input
      type="checkbox"
      id={fieldId}
      className={cx('ios-checkbox', className)}
      checked={on}
      onChange={e => setOn(e.target.checked)}
      aria-label={label}
      {...rest}
    />
  );
}
