/* ==========================================================================
   Bars — kit page "Toolbars": navigation bars (top), bottom toolbars, bar buttons and groups (Regular material).
   Renders the markup of toolbars.css. Sizes come from the bar: 44 pt in navigation bars and iPad toolbars,
   48 pt in iPhone bottom toolbars (automatic).
   ========================================================================== */

export interface BarButtonProps extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'children'> {
  /** default (Regular material) · prominent (solid accent, white content: THE main action of the bar, e.g. Done, Compose). */
  variant?: 'default' | 'prominent';
  /** A symbol. Without children the button is a circle; then `label` is required (accessible name). */
  icon?: IconName;
  /** Back button: chevron (+ optional children as the previous screen's title). Accessible name defaults to "Back". */
  back?: boolean;
  /** Accent-coloured symbol/label on the normal material (kit State = Tinted). */
  tinted?: boolean;
  /** On/off button (filter, bold…): true = accent capsule inside the button (aria-pressed). Leave undefined for actions. */
  selected?: boolean;
  /** Accessible name for an icon-only button. */
  label?: string;
  children?: ReactNode;
}

/** A bar button (a Regular-material circle or capsule). Only inside NavigationBar, Toolbar or BarGroup. */
export function BarButton({ variant = 'default', icon, back, tinted, selected, label, className, children, type = 'button', ...rest }: BarButtonProps) {
  const iconOnly = !back && icon != null && children == null;
  return (
    <button
      type={type}
      className={cx(
        'ios-bar-button',
        variant === 'prominent' && 'ios-bar-button--prominent',
        back && 'ios-bar-button--back',
        iconOnly && 'ios-bar-button--icon',
        tinted && 'ios-bar-button--tinted',
        className,
      )}
      aria-label={label ?? (back && children == null ? 'Back' : undefined)}
      aria-pressed={selected}
      {...rest}
    >
      {back && <span className="ios-icon ios-icon-chevron-backward" aria-hidden="true" />}
      {!back && icon && <Icon name={icon} />}
      {children}
    </button>
  );
}

export interface BarGroupProps extends HTMLAttributes<HTMLDivElement> {
  /** Accessible name of the group ("Format", "Navigation"). */
  label?: string;
  /** Stacked vertically (kit "Preferred Axis = Vertical"). */
  vertical?: boolean;
  children?: ReactNode;
}

/** Several related bar buttons in ONE material capsule (kit "Button Group"). Put BarButtons with icons inside. */
export function BarGroup({ label, vertical, className, children, ...rest }: BarGroupProps) {
  return (
    <div role="group" aria-label={label} className={cx('ios-bar-group', vertical && 'ios-bar-group--vertical', className)} {...rest}>
      {children}
    </div>
  );
}

export interface BarSegmentedControlProps extends Omit<HTMLAttributes<HTMLDivElement>, 'onChange' | 'defaultValue'> {
  /** The choices (2–4 short words). */
  options: string[] | { value: string; label: ReactNode }[];
  value?: string;
  defaultValue?: string;
  /** Receives the new value. */
  onChange?: (value: string) => void;
  /** Accessible name ("Scope"). */
  label?: string;
}

/** Scope filters in a material capsule (kit "_Segmented Control Button", iPad search accessory). */
export function BarSegmentedControl({ options, value, defaultValue, onChange, label, className, ...rest }: BarSegmentedControlProps) {
  const items = options.map(o => (typeof o === 'string' ? { value: o, label: o } : o));
  const [current, setCurrent] = useControllable(value, defaultValue ?? items[0]?.value ?? '', onChange);
  const refs = useRef<(HTMLButtonElement | null)[]>([]);
  const onKeyDown = (e: ReactKeyboardEvent<HTMLDivElement>) => {
    const step = e.key === 'ArrowRight' || e.key === 'ArrowDown' ? 1 : e.key === 'ArrowLeft' || e.key === 'ArrowUp' ? -1 : 0;
    if (!step) return;
    e.preventDefault();
    const i = Math.max(0, items.findIndex(it => it.value === current));
    const next = (i + step + items.length) % items.length;
    setCurrent(items[next].value);
    refs.current[next]?.focus();
  };
  return (
    <div role="radiogroup" aria-label={label} className={cx('ios-bar-group', 'ios-bar-group--segmented', className)} onKeyDown={onKeyDown} {...rest}>
      {items.map((it, i) => (
        <button
          key={it.value}
          ref={el => {
            refs.current[i] = el;
          }}
          type="button"
          role="radio"
          aria-checked={it.value === current}
          tabIndex={it.value === current ? 0 : -1}
          className="ios-bar-group__segment"
          onClick={() => setCurrent(it.value)}
        >
          {it.label}
        </button>
      ))}
    </div>
  );
}

export type NavigationBarVariant = 'inline' | 'leading-title' | 'large' | 'compact-large';

export interface NavigationBarProps extends Omit<HTMLAttributes<HTMLElement>, 'title'> {
  title?: ReactNode;
  /** Second line under the title (centered/leading: 12 pt; large: 15 pt). */
  subtitle?: ReactNode;
  /**
   * inline (default): title centered in the bar · leading-title: title left after the leading buttons ·
   * large: 34 pt title below the bar that collapses into the bar on scroll (top-level screens) ·
   * compact-large: 34 pt title in the bar (top-level screens with little content).
   */
  variant?: NavigationBarVariant;
  /** Bar buttons on the leading side (back button first). */
  leading?: ReactNode;
  /** Bar buttons on the trailing side (the main action last). */
  trailing?: ReactNode;
  /** iPad: a search field after the trailing buttons (180 wide). Pass a SearchField. */
  search?: ReactNode;
  /** iPad: a tab bar or segmented control centered in the bar; the title moves below the buttons. */
  center?: ReactNode;
  /** iPad: a row under the bar (search field + BarSegmentedControl scope filters). */
  accessory?: ReactNode;
  /** Opaque band instead of the soft scroll edge effect. */
  hardEdge?: boolean;
  /** Large titles: force collapsed (true) / expanded (false). Default: automatic while scrolling. */
  collapsed?: boolean;
}

/**
 * The navigation bar at the top of a screen. Render it as the FIRST child of the scrolling page (it sticks).
 * Large titles collapse automatically when they scroll under the bar (also on a tab or column that was hidden), and
 * show as an inline title in iPhone landscape. A screen that appears (a pushed screen, another `key`) starts at the
 * top: when the bar mounts it scrolls its page (.ios-app__content) to the top. Switching tabs keeps each tab's place.
 */
export function NavigationBar({
  title,
  subtitle,
  variant = 'inline',
  leading,
  trailing,
  search,
  center,
  accessory,
  hardEdge,
  collapsed,
  className,
  ...rest
}: NavigationBarProps) {
  const large = variant === 'large';
  const barRef = useRef<HTMLDivElement>(null);
  const largeRef = useRef<HTMLHeadingElement>(null);
  const [autoCollapsed, setAutoCollapsed] = useState(false);

  // A new screen starts at the top of its page (the page element is shared by the screens of a tab or column).
  useIsoLayoutEffect(() => {
    // Only the page the bar heads (never the page behind a sheet or popover the bar sits in).
    const page = barRef.current?.closest<HTMLElement>('.ios-app__content, dialog, [popover]');
    if (page?.classList.contains('ios-app__content')) page.scrollTop = 0;
  }, []);

  useEffect(() => {
    if (!large || collapsed !== undefined) return;
    let frame = 0;
    const check = () => {
      frame = 0;
      const bar = barRef.current;
      const big = largeRef.current;
      // On a hidden page (a tab or column that isn't shown) there is nothing to measure: decide once it is shown.
      if (!bar || !big || !bar.getClientRects().length) return;
      setAutoCollapsed(big.getBoundingClientRect().bottom <= bar.getBoundingClientRect().bottom + 1);
    };
    const queue = () => {
      if (!frame) frame = requestAnimationFrame(check);
    };
    check();
    document.addEventListener('scroll', queue, { capture: true, passive: true });
    window.addEventListener('resize', queue, { passive: true });
    // Re-check when the bar's size changes: that includes its page being shown again (0 × 0 while hidden).
    const sizes = typeof ResizeObserver === 'function' ? new ResizeObserver(queue) : null;
    if (sizes && barRef.current) sizes.observe(barRef.current);
    return () => {
      document.removeEventListener('scroll', queue, { capture: true });
      window.removeEventListener('resize', queue);
      sizes?.disconnect();
      if (frame) cancelAnimationFrame(frame);
    };
  }, [large, collapsed]);

  const isCollapsed = large && (collapsed ?? autoCollapsed);
  // A centred title (inline, large) needs both side containers, empty or not, to stay centred on the bar.
  const centered = variant === 'inline' || variant === 'large';
  const hasSubtitle = subtitle != null && subtitle !== false;
  const titleBlock =
    title != null ? (
      <div className="ios-navigation-bar__title" aria-hidden={large ? true : undefined}>
        {large ? <span className="ios-navigation-bar__heading">{title}</span> : <h1 className="ios-navigation-bar__heading">{title}</h1>}
        {hasSubtitle && <p className="ios-navigation-bar__subtitle">{subtitle}</p>}
      </div>
    ) : null;

  return (
    <header
      className={cx(
        'ios-navigation-bar',
        variant !== 'inline' && `ios-navigation-bar--${variant}`,
        hardEdge && 'ios-navigation-bar--hard-edge',
        isCollapsed && 'is-collapsed',
        className,
      )}
      {...rest}
    >
      <div className="ios-navigation-bar__bar" ref={barRef}>
        {(leading != null || centered) && <div className="ios-navigation-bar__leading">{leading}</div>}
        {titleBlock}
        {center != null && <div className="ios-navigation-bar__center">{center}</div>}
        {(trailing != null || search != null || centered) && (
          <div className="ios-navigation-bar__trailing">
            {trailing}
            {search != null && <div className="ios-navigation-bar__search">{search}</div>}
          </div>
        )}
      </div>
      {large && title != null && (
        <div className="ios-navigation-bar__large">
          <h1 className="ios-navigation-bar__large-title" ref={largeRef}>
            {title}
          </h1>
          {hasSubtitle && <p className="ios-navigation-bar__subtitle">{subtitle}</p>}
        </div>
      )}
      {accessory != null && <div className="ios-navigation-bar__accessory">{accessory}</div>}
    </header>
  );
}

export interface ToolbarProps extends HTMLAttributes<HTMLDivElement> {
  /** Buttons at the leading edge. */
  leading?: ReactNode;
  /** Buttons in the middle (or a ToolbarPageControl). */
  center?: ReactNode;
  /** Buttons at the trailing edge (the main action last). */
  trailing?: ReactNode;
  /** A search field that fills the toolbar (iPhone search). leading/trailing then sit right next to it. */
  search?: ReactNode;
  /** Accessible name ("Actions"). */
  label?: string;
  /** Opaque band instead of the soft scroll edge effect. */
  hardEdge?: boolean;
}

/** The bottom toolbar. Render it as the LAST child of the scrolling page (it sticks to the bottom). */
export function Toolbar({ leading, center, trailing, search, label = 'Toolbar', hardEdge, className, children, ...rest }: ToolbarProps) {
  return (
    <div role="toolbar" aria-label={label} className={cx('ios-toolbar', hardEdge && 'ios-toolbar--hard-edge', className)} {...rest}>
      {search != null ? (
        <>
          {leading}
          <div className="ios-toolbar__search">{search}</div>
          {trailing}
        </>
      ) : (
        <>
          {leading != null && <div className="ios-toolbar__leading">{leading}</div>}
          {center != null && <div className="ios-toolbar__center">{center}</div>}
          {trailing != null && <div className="ios-toolbar__trailing">{trailing}</div>}
        </>
      )}
      {children}
    </div>
  );
}

/** Dot sizes of the toolbar page control (kit "_Toolbar page control"): up to 6 pages all 8 pt; 7 pages: the dot
 * at the far end shrinks to 6; 8+ pages: a window of 8 dots whose outer dots shrink to 6 and 4. */
export function toolbarPageDots(count: number, current: number): { page: number; size: 8 | 6 | 4 }[] {
  const n = Math.max(1, Math.floor(count));
  const c = Math.min(Math.max(0, Math.floor(current)), n - 1);
  if (n <= 6) return Array.from({ length: n }, (_, i) => ({ page: i, size: 8 as const }));
  if (n === 7)
    return Array.from({ length: 7 }, (_, i) => ({ page: i, size: (c < 6 ? i === 6 : i === 0) ? (6 as const) : (8 as const) }));
  const atStart = c <= 3;
  const atEnd = c >= n - 3;
  const start = atStart ? 0 : atEnd ? n - 8 : c - 4;
  return Array.from({ length: 8 }, (_, i) => {
    let size: 8 | 6 | 4 = 8;
    if (!atStart && i === 0) size = 4;
    if (!atStart && i === 1) size = 6;
    if (!atEnd && i === 6) size = 6;
    if (!atEnd && i === 7) size = 4;
    return { page: start + i, size };
  });
}

export interface ToolbarPageControlProps extends HTMLAttributes<HTMLDivElement> {
  /** Number of pages. */
  count: number;
  /** The current page, 0-based. */
  current: number;
}

/** Page dots in a material capsule for the middle of a bottom toolbar (kit "_Toolbar page control"). An indicator:
 * change pages with swipes or the toolbar buttons. */
export function ToolbarPageControl({ count, current, className, ...rest }: ToolbarPageControlProps) {
  const dots = toolbarPageDots(count, current);
  return (
    <div role="img" aria-label={`Page ${current + 1} of ${count}`} className={cx('ios-toolbar__page-control', className)} {...rest}>
      {dots.map(d => (
        <span
          key={d.page}
          className={cx('ios-toolbar__dot', d.size === 6 && 'ios-toolbar__dot--small', d.size === 4 && 'ios-toolbar__dot--tiny')}
          aria-current={d.page === current ? 'true' : undefined}
        />
      ))}
    </div>
  );
}
// ---------------------------------------------------------------------------------------------------
// widget.tsx
// ---------------------------------------------------------------------------------------------------

export type WidgetSize = 'small' | 'medium' | 'large' | 'extra-large';

export interface WidgetProps extends Omit<AnchorHTMLAttributes<HTMLElement>, 'children'> {
  /**
   * small 164.67² · medium 349.67 × 164.33 · large 349.67 × 365 · extra-large 349.67 × 565.67 on iPhone;
   * 136² · 300 × 136 · 300 × 300 · 628 × 300 on iPad (switches at the regular size class).
   */
  size?: WidgetSize;
  /** The label under the widget on the Home Screen (usually the app name). */
  name?: string;
  /** Background colour (default: Backgrounds/Primary - Elevated, white / #1C1C1E). Any CSS colour or var(--ios-…). */
  background?: string;
  /** No 18 px content margin: photos and maps that fill the widget. */
  fullBleed?: boolean;
  /** See-through Home Screen appearance: the Thin material, label colours (follow Light / Dark). */
  clear?: boolean;
  /** With href the whole widget is a link (one tap target, like a small widget on iOS). */
  href?: string;
  children?: ReactNode;
}

/**
 * A Home Screen widget FRAME (kit page "Widgets") for mockups and web previews. Real widgets are SwiftUI (WidgetKit).
 * Content goes inside the 18 px margin; inner corner radius 11 for content that touches it.
 */
export function Widget({ size = 'small', name, background, fullBleed, clear, href, className, style, children, ...rest }: WidgetProps) {
  const cls = cx(
    'ios-widget',
    size !== 'small' && `ios-widget--${size}`,
    fullBleed && 'ios-widget--full-bleed',
    clear && 'ios-widget--clear',
    className,
  );
  const st = vars(style, { '--ios-widget-bg': background });
  const body = (
    <>
      {children}
      {name && <span className="ios-widget__name">{name}</span>}
    </>
  );
  return href ? (
    <a className={cls} style={st} href={href} {...rest}>
      {body}
    </a>
  ) : (
    <div className={cls} style={st} {...(rest as AnchorHTMLAttributes<HTMLDivElement>)}>
      {body}
    </div>
  );
}
