// window.tsx
// ---------------------------------------------------------------------------------------------------

/* ==========================================================================
   Windows — kit page "Windows" (Window, Window with Sidebar, _Window Controls, _Window Resize).
   Renders the markup of windows.css. A MOCKUP of an iPadOS window (screenshots, demos, desktop-like web apps):
   a normal web app is already in a browser window and uses App instead.
   ========================================================================== */

/** Tells a Sidebar inside an IpadWindow to show the window controls in its toolbar row. */
export const IpadWindowContext = createContext<{ controls: boolean; inactive: boolean } | null>(null);

export interface IpadWindowProps extends HTMLAttributes<HTMLDivElement> {
  /** Not the focused window: grey window controls, lighter sidebar (kit Mode = Inactive). */
  inactive?: boolean;
  /** A <Sidebar>: the window gets a sidebar column (kit "Window with Sidebar"); the controls go into its toolbar. */
  sidebar?: ReactNode;
  /** Show the window controls (close, minimize, full screen). Default true. */
  controls?: boolean;
  /** Show the resize grabber in the bottom-right corner. Default true. */
  resizable?: boolean;
  children?: ReactNode;
}

/**
 * An iPadOS 27 window (kit "Window"): radius 34, large soft shadow, window controls, resize grabber.
 * Give it a size with `style` or a class.
 *
 *     <IpadWindow style={{ width: 720, height: 400 }} sidebar={<Sidebar>…</Sidebar>}>
 *       <NavigationBar title="Notes" />
 *     </IpadWindow>
 */
export function IpadWindow({ inactive = false, sidebar, controls = true, resizable = true, className, children, ...rest }: IpadWindowProps) {
  const hasSidebar = sidebar != null && sidebar !== false;
  return (
    <IpadWindowContext.Provider value={{ controls: controls && hasSidebar, inactive }}>
      <div className={cx('ios-window', inactive && 'ios-window--inactive', className)} {...rest}>
        {hasSidebar ? <SplitView sidebar={sidebar}>{children}</SplitView> : children}
        {controls && !hasSidebar && (
          <span className="ios-window__controls" aria-hidden="true">
            <span />
            <span />
            <span />
          </span>
        )}
        {resizable && <span className="ios-window__resize" aria-hidden="true" />}
      </div>
    </IpadWindowContext.Provider>
  );
}